(window.GIM_TS=window.GIM_TS||{})["Yoma.2"]={"from":48,"a":[["\u0003למאי אתא\u0004 \u0005[למה בא]\u0006 ללמדנו? ומסבירים \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיצד היה עושה — נותן את הפדר\u0004 על \u0003בית השחיטה,\u0004 על הצואר החתוך, \u0003ומעלהו\u0004 כך, \u0003וזהו דרך כבוד של מעלה\u0004 שלא יראה בית השחיטה מגולה ודמו שותת.","\u0003הפייס השלישי\u0004 היו מכריזים: \u0003חדשים לקטרת\u0004 שלא הקריבו קטורת מימיהם \u0003באו והפיסו.\u0004 והפייס \u0003הרביעי: חדשים\u0004 שלא עשו עבודה זו \u0003עם ישנים\u0004 שעשוה כבר — \u0003מי מעלה אברים מן הכבש,\u0004 ששם הניחוהו הכהנים שזכו בהבאתו \u0003למזבח.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003מעולם לא שנה אדם בה\u0004 בעבודת הקטורת, שתמיד נמצא כהן חדש לעבודה זו. ושואלים: \u0003מאי טעמא\u0004 היו מקפידים שלא ישנה בה אדם? \u0003אמר ר' חנינא: מפני שמעשרת\u0004 מפני שסגולתה להביא עושר, ולכך רצו שכל כהן יזכה בכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: מאי טעמא\u0004 \u0005[מה טעם הדבר],\u0006 מניין יודע אתה כי יש בקטורת סגולה לעשירות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישימו קטרה באפך\u0004 וכליל על מזבחך\u0003\"\u0004 (דברים לג, י) \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"ברך ה' חילו\u0004 ופועל ידיו תרצה\u0003\"\u0004 (דברים לג, יא), \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003עולה נמי\u0004 \u0005[גם כן]\u0006 תהיה סגולה לעושר, \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 בה: \u0003\"וכליל על מזבחך\"!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אף על פי כן, \u0003הא שכיחא\u0004 \u0005[זו\u0006 הקרבת עולה \u0005מצויה]\u0006 שהרי יש הרבה עולות חובה ונדבה \u0003והא לא שכיחא\u0004 \u0005[וזו אינה מצויה]\u0006 ומסתבר לומר שמתנת העושר אינה ניתנת לכולם, אלא מעט מעט ליחידים.","אגב הזכרת פסוקים אלה \u0003אמר רבא: לא משכחת צורבא מרבנן דמורי\u0004 \u0005[אין אתה מוצא תלמיד חכם המורה\u0006 הלכה\u0005]\u0006 \u0003אלא\u0004 אחד \u0003דאתי\u0004 \u0005[שהוא בא]\u0006 או \u0003משבט לוי או משבט יששכר,\u0004 וראיה לדבר — שבט \u0003לוי, דכתיב\u0004 שנאמר בו: \u0003\"יורו משפטיך ליעקב\u0004 ותורתך לישראל\u0003\"\u0004 (דברים לג, י). ושבט \u0003יששכר, דכתב\u0004 שנאמר בו: \u0003\"ומבני יששכר יודעי בינה לעתים לדעת מה יעשה ישראל\"\u0004 (דברי הימים א' יב, לג). ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי משבט \u0003יהודה נמי\u0004 \u0005[גם כן],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"יהודה מחקקי\"\u0004 (תהלים ס, ט)! ומשיבים: אכן, לתורה זוכים גם בני יהודה, ורבא לענין \u0003אסוקי שמעתא אליבא דהילכתא קאמינא\u0004 \u0005[העלאת שמועה,\u0006 העיון, \u0005על פי הלכה אומר אני],\u0006 כי אף שישנם תלמידי חכמים מופלגים גם בשבטים אחרים, אבל אלה הזוכים להגיע מתוך המשא והמתן למסקנות הלכתיות אינם באים אלא משני שבטים אלו.","\u0003אמר ר' יוחנן: אין מפייסין\u0004 על שחיטת והקרבת \u0003תמיד של בין הערבים\u0004 לחוד, \u0003אלא כהן שזכה בו\u0004 באחת מן העבודות הנעשות בקרבן התמיד של \u0003שחרית זוכה בו\u0004 בעבודה זו גם בתמיד של \u0003ערבית,\u0004 ופייס זה לשתי העבודות כאחת. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003כשם שמפייסין שחרית כך מפייסין בין הערבים,\u0004 הרי ששני פייסות נפרדים היו! ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא] \u0003ההיא —\u0004 הרי זה \u0003בקטרת\u0004 בלבד, שבעשייתה היה עסוק בכל פעם כהן אחר, כאמור.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשם שמפייסין לו שחרית כך מפייסין לו ערבית\u0004 משמע ששתי פייסות הן לקרבן התמיד, שהרי נאמר הדבר בלשון זכר, (\"לו\"), ומכוון בודאי לקרבן התמיד! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 לא בלשון \"לו\", אלא \u0003\"לה\",\u0004 כלומר: כדרך שעושים לקטורת של שחר כך עושים לקטורת של בין הערבים.","ומקשים עוד: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003כשם שמפייסין לו שחרית כך מפייסין לו ערבית, וכשם שמפייסין לה שחרית כך מפייסין לה ערבית\u0004 הרי ששנינו שני פייסות גם לענין התמיד וגם לענין קטורת!","\u0003אמר רב שמואל בר רב יצחק:\u0004 אין מכאן סתירה, כי \u0003הכא\u0004 \u0005[כאן]\u0006 בברייתא אחרונה זו ביום ה\u0003שבת עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003הואיל ומשמרות מתחדשות\u0004 שהמשמר החדש מתחיל את עבודתו ביום השבת, ועבודת שחרית נעשית במשמר היוצא ושל בין הערבים במשמר הנכנס, ואנשי המשמר החדש צריכים פייסות חדשים.","ושואלים: \u0003ולמאי דסליק אדעתין מעיקרא\u0004 \u0005[ולמה שעלה בדעתנו מתחילה]\u0006 לפי הקושיה, שיש בכל יום פייס מיוחד לתמיד של בין הערבים, אם כן \u0003נפישי להו\u0004 \u0005[רבו להם]\u0006 ה\u0003פייסות\u0004 יותר מארבעה, שהרי יש לעשות פייסות נוספים בערבית! ומשיבים: \u0003מייתי כולהו מצפרא אתו\u0004 \u0005[לבוא, כולם\u0006 כבר \u0005מהבוקר באים]\u0006 \u0003דזכי ביה\u0004 \u0005[הזוכה בו\u0006 בהקרבת התמיד\u0005]\u0006 של \u0003שחרית — זכי\u0004 \u0005[זוכה],\u0006 \u0003דזכי\u0004 \u0005[\u0006ו\u0005הזוכה\u0006 בהקרבת תמיד של \u0003ערבית\u0004 \u0005[בין הערבים] —\u0006 \u0003זכי\u0004 \u0005[זוכה]\u0006 שהיו עושים בשעות הפייס גם פייסות מיוחדים לעבודות הערב, ואם כן אין משם כל הוכחה.","הפייס \u0003הרביעי\u0004 היה \u0003חדשים עם ישנים\u0004 להעלות איברים מן הכבש למזבח. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו\u0006 זו\u0005]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' אליעזר בן יעקב\u0004 היא. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת תמיד: \u0003ר' אליעזר בן יעקב אומר:\u0004 הכהן \u0003המעלה איברים לכבש הוא המעלה אותן\u0004 מן הכבש \u0003למזבח,\u0004 שלא כפי הנראה ממשנתנו, שדבר זה היה נעשה על ידי כהן אחר על פי הגורל.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]?\u0006 \u0003מר\u0004 \u0005[חכם זה],\u0006 התנא שלנו, \u0003סבר\u0004 לפי הכתוב: \u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח) ומשום הדרת מלך ראוי שיהיו עסוקים בעבודתו כהנים מרובים, מהם המעלים את אברי הקרבן לכבש, ומהם המעלים אותם למזבח. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' אליעזר בן יעקב, \u0003סבר: מקום שכינה לאו אורח ארעא\u0004 \u0005[אינו דרך ארץ]\u0006 להרבות באנשים המתעסקים במלאכתו, דבר המורה על שטורח הוא להם.","\u0003אמר רבא: לא ר' אליעזר בן יעקב אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003ר' יהודה\u0004 בפייסות שאמר שאין פייס מיוחד למחתה, \u0003ולא ר' יהודה אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את שיטת \u0003ר' אליעזר בן יעקב\u0004 האומר כי כן היו עושים פייס מיוחד למחתה. ש\u0003אם כן\u0004 אתה אומר, הרי \u0003בצרו להו\u0004 \u0005[חסרים להם]\u0006 \u0003פייסות,\u0004 שהרי לפי זה אין ארבע פייסות אלא רק שלושה. אלא צריך לומר שלדעת ר' אליעזר היה פייס מיוחד למחתה ופייס מיוחד לקטורת, ולדעת ר' יהודה, היה פייס להעלאת איברים.","\u0003ואי משכחת\u0004 \u0005[ואם תמצא]\u0006 \u0003תנא דתני\u0004 \u0005[ששונה]\u0006 \u0003חמש\u0004 פייסות בסדר היום במקדש"],["\u0003ההוא\u0004 \u0005[אותו\u0006 תנא\u0005]\u0006 סבור ש\u0003לא\u0004 כשיטת \u0003ר' אליעזר בן יעקב\u0004 וש\u0003לא\u0004 כשיטת \u0003ר' יהודה\u0004 ולכן היו צריכים חמש פייסות גם למחתה וגם להעלאת איברים.","קרבן ה\u0003תמיד\u0004 ניתן להיות \u0003קרב\u0004 ומוליכין את איבריו פעמים \u0003בתשעה\u0004 כהנים, כפי שכבר נאמר (לעיל יומא כה, א) שהכהנים המוליכים את אבריו והמנחות והנסכים השייכים לו תשעה היו, ופעמים \u0003בעשרה\u0004 כהנים, פעמים \u0003באחד עשר,\u0004 ופעמים \u0003בשנים עשר\u0004 כהנים. \u0003לא פחות\u0004 מתשעה \u0003ולא יותר\u0004 משנים עשר. \u0003כיצד?\u0004 קרבן התמיד \u0003עצמו\u0004 קרב \u0003בתשעה\u0004 כהנים כפי שהסברנו. ו\u0003בחג\u0004 הסוכות מוסיפים כהן נוסף, כי \u0003ביד\u0004 כהן \u0003אחד\u0004 היתה \u0003צלוחית של מים\u0004 לניסוך המים, שנוסף בחג על ניסוך היין — \u0003הרי כאן עשרה\u0004 כהנים.","\u0003בין הערבים\u0004 בכל יום היו באים \u0003אחד עשר\u0004 כהנים, כיצד? \u0003הוא\u0004 קרבן התמיד \u0003עצמו\u0004 היה נעשה \u0003בתשעה, ושנים\u0004 נוספים ש\u0003בידם שני גזירי עצים\u0004 שהיו מניחים על המזבח, ומצות נתינת שני עצים על המזבח מיוחדת לבין הערבים בלבד. \u0003בשבת\u0004 היה בא \u0003באחד עשר,\u0004 כיצד? \u0003הוא עצמו בתשעה, ושנים\u0004 נוספים ש\u0003בידם שני בזיכי לבונה של לחם הפנים\u0004 שאותם היו מקטירים ביום השבת. \u0003ובשבת שבתוך חג\u0004 הסוכות נוסף להם עוד כהן כי \u0003ביד אחד צלוחית של מים\u0004 לניסוך המים, הרי בסך הכל שנים עשר.","\u0003אמר ר' אבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רמי בר חמא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יוחנן: אין מנסכין מים בחג\u0004 הסוכות \u0003אלא\u0004 בשעת הקרבת \u0003תמיד של שחר\u0004 ולא בין הערבים. \u0003ממאי\u0004 \u0005[ממה],\u0006 מהיכן יודעים אנו דבר זה? — \u0003מדקתני\u0004 \u0005[ממה ששנינו]:\u0006 \u0003ובשבת שבתוך החג\u0004 היה \u0003ביד אחד צלוחית של מים\u0004 ואז הגיע המספר לשנים עשר כהנים. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003בתמיד של בין הערבים\u0004 גם \u0003מנסכין\u0004 מים, אם כן \u0003בחול\u0004 המועד \u0003נמי משכחת לה\u0004 \u0005[גם כן אתה מוצא אותה]\u0006 שיהיו שנים עשר: תשעה לקרבן התמיד, שנים לגזירי עצים, ואחד לניסוך המים.","\u0003אמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 שלא היו מנסכים את המים אלא בבוקר, ששנינו: \u0003ולמנסך אומר לו: הגבה ידיך\u0004 כדי שיראו כולם שאתה מערה את המים לתוך ספל כסף המונח על גבי המזבח, שזוהי דרך קיום מצות ניסוך המים. וכל זאת משום \u0003שפעם אחד נסך\u0004 כהן צדוקי, שאינו מודה במצוות ניסוך המים, את המים הללו \u0003על גבי רגליו, ורגמוהו כל העם באתרוגיהן\u0004 מתוך כעס. ומתוך שנאמר כי רגמוהו באתרוגיהם, הרי שדבר זה היה בבוקר, בשעה שכל העם באים באתרוגיהם. ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחאי אומר: מניין לתמיד של בין הערבים שטעון\u0004 הבאת \u0003שני גזירי עצים\u0004 וצריך שיובאו \u0003בשני כהנים,\u0004 לפי \u0003שנאמר\u0004 בקרבן עולה: \"ונתנו בני אהרן הכהן אש על המזבח \u0003וערכו עצים\u0004 על האש\" (ויקרא א, ז), ו\u0003אם אינו ענין\u0004 שאין לך ללמוד ממנו דבר \u0003לתמיד של שחר\u0004 שהרי כבר \u0003כתיב ביה\u0004 \u0005[נאמר בו]\u0006 במפורש: \u0003\"ובער עליה הכהן עצים בבקר בבקר וערך עליה\u0004 העולה\u0003\"\u0004 (ויקרא ו, ה) — \u0003תניהו ענין\u0004 ולמד ממנו \u0003לתמיד של בין הערבים,\u0004 ששיש להוסיף אז שני גיזרי עצים לפני ההקרבה.","ושואלים: \u0003ואימא אידי ואידי\u0004 \u0005[ואמור שזה וזה]\u0006 שני הפסוקים כאחד מדברים \u0003בתמיד של שחר,\u0004 אלא ש\u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003עביד והדר עביד\u0004 \u0005[עשה, וחזור ועשה]\u0006 כלומר יערוך עצים ואחר כך יערוך עצים שנית! ודוחים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"ובער\" \"ובער\"\u0004 שתי פעמים באותה לשון, וכיון שבמקום אחד כתוב הלשון \"ובער\" ובשני לשון \"וערכו\", יש ללמוד מכאן כי אין מדובר בזמן אחד.","ומשיבים: \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 \u0003\"ובער\"\u0004 פעמיים \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003חד\u0004 \u0005[\u0006כהן \u0005אחד] —\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003תרי\u0004 \u0005[שנים] —\u0006 \u0003לא,\u0004 על כן \u0003קא משמע לן דנעביד חד ונעביד תרי\u0004 \u0005[השמיע לנו\u0006 הכתוב \u0005שייעשה\u0006 בכהן \u0005אחד וייעשה בשנים]\u0006 ואם כן יש טעם בשינוי הלשון!","ודוחים: \u0003אם כן, נימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 לשון זהה: \u0003\"ובער\" \"ובערו\",\u0004 בשינוי הלשון לצורת רבים שבו, ללמד אף על דבר זה, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שיאמר: \u0003\"וערך\" \"וערכו\", מאי\u0004 \u0005[מה]\u0006 אם כן מלמדנו השינוי בין \u0003\"ובער\" \"וערכו\" — שמע מינה כדקא אמרינן\u0004 \u0005[למד מכאן שכמו שאמרנו]\u0006 שיש כאן ללמד הן להוספת עצים, והן לעריכת העצים בערב על ידי שנים דווקא, כלשון הכתוב.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: פייס פעמים שלשה עשר\u0004 כהנים זוכים בו, כפי שאמרנו, \u0003פעמים ארבעה עשר\u0004 שהרי בחג הסוכות זוכה עוד כהן בניסוך המים, \u0003פעמים חמשה עשר\u0004 כשהוא בשבת, שנוספו שני כהנים להקטרת בזיכי לבונה \u0003פעמים ששה עשר\u0004 בשבת שבחג הסוכות, שנוספו שלושה כהנים לניסוך ולבזיכים.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שלפעמים היו שם \u0003שבעה עשר\u0004 כהנים בפייס אחד! שלדעתו היו מפייסים גם על העלאת איברים מן הכבש למזבח.","ומשיבים: \u0003ההיא\u0004 \u0005[אותה\u0006 ברייתא\u0005]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' אליעזר בן יעקב, אלא\u0004 כשיטת \u0003ר' יהודה\u0004 שהיה אומר שאין פייס מיוחד למחתת הקטורת, וממילא אף בהוספת הכהן המעלה את האיברים מן הכבש למזבח, עדיין נשאר המספר הזה.","\u0003איל\u0004 שהיו מקריבים לעולת ציבור היה \u0003קרב באחד עשר\u0004 כהנים. \u0003הבשר\u0004 לאיבריו השונים \u0003בחמשה\u0004 כהנים כדרך שמביאים את כבש התמיד. אולם \u0003הקרביים, והסולת והיין\u0004 היו באים \u0003בשנים שנים\u0004 כהנים, שכן באיל מרבים במנחה ובנסכים. ה\u0003פר\u0004 היה \u0003קרב בעשרים וארבעה\u0004 כהנים, כיצד? \u0003הראש והרגל\u0004 היו קרבים ראשונה, אבל מפני גודל הפר \u0003הראש באחד והרגל בשנים. העוקץ והרגל — העוקץ\u0004 היה קרב \u0003בשנים, והרגל בשנים. החזה והגרה — החזה\u0004 קרב בכהן \u0003אחד, והגרה בשלשה\u0004 כהנים. \u0003שתי ידים — בשנים, ושתי דפנות — בשנים, הקרביים והסולת והיין בשלשה שלשה,\u0004 שבפר מרובים גם המנחה וגם היין.","\u0003במה דברים אמורים,\u0004 שנוהגים כסדר זה — זהו דווקא \u0003בקרבנות ציבור, אבל בקרבן יחיד\u0004 כשמקריב אדם עולת נדבה או חובה, \u0003אם רצה\u0004 כהן אחד \u0003להקריב\u0004 הכל — \u0003מקריב\u0004 בעצמו, או משתף אחרים עמו כרצונו. \u0003הפשיטן וניתוחן של אלו\u0004 ושל \u0003אלו\u0004 של ציבור ושל יחיד — כולן \u0003שוין\u0004 שמותרים להיעשות בזר, כמבואר בסוגיית הגמרא\u0003.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003הפשיטן וניתוחן שוין\u0004 כלומר, שמותרים להיעשות בזר, שאין זו מעבודות כהונה.","\u0003אמר חזקיה: מניין להפשט וניתוח ששוה\u0004 שמותר להיעשות \u0003בזר? — שנאמר\u0004 קודם בסדר מעשה העולה: \"והפשיט את העולה וניתח אותה לנתחיה\" (ויקרא א, ו) ואחר כך נאמר: \u0003\"ונתנו בני אהרן הכהן אש על המזבח\"\u0004 (ויקרא א, ז) ללמדנו: \u0003נתינת אש בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה\u0004 שהיא עבודת קודש, \u0003הפשט וניתוח לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003כהונה.\u0004"],["ומקשים: והרי \u0003האי מיבעי ליה לגופיה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו לגופו]\u0006 ללמד שהבאת העצים צריכה כהן! \u0003אמר רב שימי בר אשי: אשכחתיה\u0004 \u0005[מצאתי את]\u0006 \u0003אביי דהוה מסבר ליה לבריה\u0004 \u0005[שהיה מסביר לו לבנו]\u0006 שיטה זו של חזקיה, על ידי הברייתא הבאה. נאמר: \u0003\"ושחט\u0004 את בן הבקר לפני ה'\u0003\"\u0004 (ויקרא א, ה) — ללמד כי \u0003שחיטה בזר כשירה. וכי מאין באת\u0004 לפקפק בדבר ולחשוב ששחיטה זו פסולה, שבשל כך הוצרכת ללומדו מן הכתוב? — \u0003מכלל שנאמר: \"ואתה ובניך אתך תשמרו את כהנתכם\"\u0004 (במדבר יח, ז), \u0003שומע אני\u0004 שאף אחת מן העבודות אינה נעשית בזר ו\u0003אפילו שחיטה,\u0004 לכך","\u0003תלמוד לומר: \"ושחט את בן הבקר לפני ה' והקריבו בני אהרן הכהנים את הדם\"\u0004 (ויקרא א, ה), ללמדנו \u0003מקבלה\u0004 (הקרבת הדם) \u0003ואילך\u0004 הוא \u0003מצות כהונה,\u0004 אבל כל מה שלפני קבלה ובכלל זה אף השחיטה, אינו מכלל מצוות הכהונה. וכן נאמר: \u0003\"וסמך ידו\u0004 על ראש העולה ונרצה לו לכפר עליו \u0003ושחט\u0004 את בן הבקר לפני ה'\u0003\"\u0004 (ויקרא א, ד-ה), ומתוך שסמך הכתוב את הסמיכה שמצוותה בבעלים שהוא זר, לשחיטה — בכך \u0003לימד\u0004 אף \u0003על השחיטה שכשירה בזר.\u0004 עד כאן לשון הברייתא.","ומדייק מכאן אביי: \u0003מכדי\u0004 \u0005[והרי]\u0006 \u0003מקבלה ואילך מצות כהונה,\u0004 אם כן מה שנאמר לאחר מכן \u0003\"ונתנו בני אהרן\", למה לי?\u0004 שהרי כיון שעבודה זו היא לאחר שחיטה מובן שהיא ממצוות הכהנים! על כן יש לומר כי לא הוצרך הדבר לגופו אלא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003הפשט וניתוח\u0004 הקודמים לנתינת העצים, ולומר שנעשים אף על ידי זר.","ומקשים: \u0003ואכתי איצטריך\u0004 \u0005[ועדיין הוצרך]\u0006 הכתוב בנתינת עצים לגופו, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך\u0006 לומר\u0005]\u0006 \u0003כיון דלאו\u0004 \u0005[שאין]\u0006 זו \u0003עבודה דמעכבא\u0004 \u0005[שמעכבת]\u0006 את ה\u0003כפרה היא\u0004 ולכך \u0003לא תיבעי\u0004 \u0005[תצטרך]\u0006 דווקא \u0003כהונה\u0004 וגם זר יוכל לתת עצים על האש — \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על פי כן \u0003בעי\u0004 \u0005[צריכה]\u0006 \u0003כהונה,\u0004 ואין ללמוד מכאן למעט דבר אחר!","\u0003אלא\u0004 עלינו לדחות מה שאמרנו תחילה, ולומר כי ההוכחה היא \u0003מהכא\u0004 \u0005[מכאן]:\u0006 נאמר: \u0003\"וערכו בני אהרן הכהנים את הנתחים את הראש ואת הפדר\"\u0004 (ויקרא א, ח), \u0003מכדי\u0004 \u0005[הרי]:\u0006 \u0003מקבלה ואילך\u0004 הן \u0003מצות כהונה,\u0004 אם כן הדגשת הכתוב \u0003\"וערכו\u0004 בני אהרן\u0003\", למה לי?\u0004 מובן שבני אהרן עושים זאת! אלא בא כתוב זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003הפשט וניתוח\u0004 שאינם צריכים כהן.","ומקשים: \u0003ואימא למעוטי\u0004 \u0005[ואמור\u0006 שבא הדבר \u0005למעט]\u0006 \u0003סידור שני גזירי עצים\u0004 ולומר שמותר אף לזר לעשותו! ודוחים: \u0003מסתברא דיבחא דכותיה\u0004 \u0005[מסתבר שזבח שכמותו]\u0006 הוא \u0003ממעט.\u0004 כלומר: כיון שהכתוב מדבר בענין עריכת הזבח בידי בני אהרן, בודאי התכווין למעט דבר הקרוב לו במהותו, וכגון הפשטתו וניתוחו הכשרים אפילו באחרים, ולא את סידור העצים שהוא נושא אחר.","ומקשים: \u0003אדרבה,\u0004 יכולים אנו לומר \u0003סדור דכותיה\u0004 \u0005[שכמותו]\u0006 הריהו \u0003ממעט,\u0004 שהרי עריכת הנתחים דומה לעריכת (סידור) העצים, ושמא בא הדבר ללמדנו שסידור נתחים נעשה על ידי כהנים בלבד, וסידור עצים יכול להיעשות אפילו בזר!","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[אינו\u0006 יכול \u0005לעלות על דעתך],\u0006 כיון ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 נאמר לאחר מצות קבלת הדם: \u0003\"והקריב הכהן את הכל\u0004 והקטיר \u0003המזבחה\"\u0004 (ויקרא א, יג), ופירשו חכמים כי \u0003זו הולכת אברים לכבש.\u0004 והדגשת לשון \"והקריב הכהן\" בפסוק זה בודאי באה למעט ולהדגיש: כי \u0003הולכת אברים לכבש הוא דבעיא\u0004 \u0005[שצריכה]\u0006 \u0003כהונה,\u0004 אולם \u0003הולכת עצים לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003כהונה. הא\u0004 \u0005[הרי]\u0006 תלמד מכאן כי \u0003סידור שני גזירי עצים\u0004 שלא נתמעט — \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה!\u0004","אם כן יכולים אנו לחזור לשאלה הראשונה \u0003\"וערכו\" למה לי?\u0004 — אלא הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003הפשט וניתוח\u0004 ולומר שנעשים אף בזר, וכפי שכבר רצינו להוכיח. הוכחה זו דוחים: \u0003ואימא הכי נמי לגופיה\u0004 \u0005[ואמור\u0006 פסוק זה \u0005כך גם כן לגופו\u0006 בא\u0005],\u0006 כדי ללמדנו שעריכת איברים על המזבח צריכה כהנים, שהרי אין עבודה זו מעכבת את הכפרה, וראוי היה להדגיש שאף על פי כן צריכה היא להיעשות בידי כהנים!","\u0003אלא\u0004 עלינו לדחות מה שאמרנו, ונוכיח מכאן; נאמר: \u0003\"והקטיר הכהן את הכל\u0004 המזבחה\u0003\"\u0004 (ויקרא א, ט), \u0003למאי אתא\u0004 \u0005[למה,\u0006 לאיזה צורך \u0005הוא בא],\u0006 שהרי לגופו אינו צריך, שהוא מעשה שלאחר קבלת הדם, אלא בא \u0003למעוטי הפשט וניתוח.\u0004","\u0003\"והקריב הכהן את הכל המזבחה\"\u0004 (ויקרא א, יג) — \u0003זו הולכת אברים לכבש\u0004 וגם כתוב זה בא למעט, וללמד: \u0003הולכת אברים לכבש הוא דבעיא\u0004 \u0005[שצריכה]\u0006 \u0003כהונה, הולכת עצים — לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003כהונה, הא\u0004 \u0005[הרי]\u0006 תלמד מכאן כי \u0003סדור שני גזירי עצים בעיא\u0004 \u0005[צריכה]\u0006 \u0003כהונה. \"ונתנו\u0004 בני אהרן הכהן אש על המזבח\u0003\"\u0004 (ויקרא א, ז) נלמד \u0003לגופיה\u0004 \u0005[לגופו],\u0006 שצריך שתיעשה עבודה זו על ידי כהנים.","\u0003\"וערכו\"\u0004 (ויקרא א, ח) מלמד שנעשה דווקא בידי \u0003שנים,\u0004 שהרי בלשון רבים נאמר, ומיעוט רבים שנים. \u0003\"בני אהרן\"\u0004 הרי \u0003שנים נוספים, \"הכהנים\"\u0004 הריהו מוסיף עוד \u0003שנים\u0004 אחרים — \u0003למדנו לטלה\u0004 הקרבן \u0003שטעון ששה\u0004 כהנים שיעלוהו למזבח — הבשר בחמישה, והקרביים באחד.","\u0003אמר רב המנונא: קשיא ליה\u0004 \u0005[קשה לו]\u0006 \u0003לר' אלעזר: האי\u0004 \u0005[הרי זה]\u0006 הפסוק הלא \u0003בבן הבקר\u0004 המוקרב לעולה \u0003כתיב\u0004 \u0005[\u0006הוא \u0005נאמר]\u0006, והרי \u0003בן הבקר עשרים וארבעה\u0004 כהנים \u0003בעי\u0004 \u0005[צריך]!\u0006 \u0003וניחא ליה\u0004 \u0005[ונוח לו]\u0006 שהוא עצמו מיישב את הקושיה הזו כך: בפסוק זה עצמו נאמר: \u0003\"על העצים אשר על האש אשר על המזבח\"\u0004 (ויקרא א, יב), שאינו מלמד לכאורה דבר לגופו של קרבן, אלא בא לרמז: \u0003איזהו דבר שנאמר בו\u0004 שיש להכין עבורו במיוחד \u0003עצים אש ומזבח,\u0004 ואין מסתפקים בנמצא מן המוכן —"],["\u0003הוי אומר זה טלה\u0004 של קרבן תמיד של שחר, שהצריך הכתוב לסדר לצורכו בכל יום מערכה חדשה של עצים, ולהביא אש על המזבח בכל בוקר מחדש.","\u0003אמר ר' אסי אמר ר' יוחנן: זר שסידר את המערכה חייב\u0004 מיתה, משום שעשה עבודה המותרת רק לכהן. \u0003כיצד הוא עושה\u0004 כדי להכשיר את המערכה — \u0003פורקה וחוזר וסודרה.\u0004 ותוהים: \u0003מאי אהני ליה\u0004 \u0005[מה הועיל לו]?\u0006 הרי אותו זר שפירק הוא החוזר וסודרה, ואם כן הריהי שוב מסודרת בידי זר! \u0003אלא\u0004 כך יש לומר: \u0003פורקה זר\u0004 וחוזר \u0003וסודרה\u0004 ה\u0003כהן.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על עיקר ההלכה \u0003ר' זירא: וכי יש לך עבודה שכשירה בלילה ופסולה בזר?\u0004 וסידור המערכה יכול הרי להיעשות גם בלילה, הרי שאין זו עבודה מובהקת.","ותוהים על שאלתו: \u0003ולא\u0004 \u0005[וכי אין]\u0006 עבודה כזו נחשבת כעבודה גמורה שיהיה זר חייב עליה? \u0003והרי\u0004 הקטרת \u0003אברים ופדרים\u0004 על המזבח שנמשכת כל הלילה, ושנינו שלדעת הכל זר שעשאה חייב עליה? ודוחים: מזו אין להקשות, כי הקטרת איברים ופדרים אינה נחשבת כעבודת לילה, אלא \u0003סוף עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא.\u0004","ומקשים עוד: \u0003והרי תרומת הדשן\u0004 שהיא עבודת לילה ופסולה בזר! ודוחים: גם מזו אין להקשות, כיון ש\u0003תחלת עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא.\u0004 ש\u0003אמר ר' אסי אמר ר' יוחנן:\u0004 כהן ש\u0003קידש ידיו לתרומת הדשן, למחר,\u0004 כלומר: לכשיאיר היום \u0003אינו צריך לקדש\u0004 את ידיו בשנית לעבודה אחרת, כיון \u0003שכבר קידש מתחלת עבודה\u0004 משמע שתרומת הדשן שייכת וראשונה היא לעבודות היום. כיון שלא נדחתה קושיית ר' זירא, אומרים: \u0003ואלא קשיא\u0004 \u0005[קשה]\u0006 לדברי ר' יוחנן, לענין זר שסידר את המערכה!","\u0003אלא\u0004 עלינו לומר כי לא כך אמר ר' יוחנן, ו\u0003כי איתמר הכי איתמר\u0004 \u0005[כאשר נאמר כך נאמר]:\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: זר שסידר שני גזירי עצים — חייב, הואיל ועבודת יום היא. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: אלא מעתה\u0004 אם סידור שני גזירי העצים עבודת כהונה חשובה היא, אם כן \u0003תיבעי\u0004 \u0005[שתצטרך]\u0006 \u0003פייס\u0004 והרי לא שנינו שעשו לה פייס מיוחד! ומעירים: \u0003אשתמיטתיה\u0004 \u0005[נשמט ממנו]\u0006 כלומר שכח רבא, \u0003הא דתניא\u0004 \u0005[\u0006הלכה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שזכה\u0004 בפייס \u0003בתרומת הדשן — זכה\u0004 אף \u0003בסדור\u0004 ה\u0003מערכה ובסדור שני גזירי עצים.\u0004 ואם כן הרי שהיה פייס לעבודה זו.","ושואלים מצד אחר על רבא: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכל האמור ש\u0003עבודת יום בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס\u0004 ואילו \u0003עבודת לילה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס? והרי\u0004 הקטרת \u0003אברים ופדרים\u0004 על המזבח שנעשית בלילה ובכל אופן צריכים לכך פייס! ומשיבים: זו אינה קושיה כי הקטרת איברים ופדרים \u0003סוף עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא.\u0004 ומקשים: \u0003והרי תרומת הדשן\u0004 שהיא עבודת לילה והצריכו לה פייס! ומשיבים: לא הצריכו בה פייס אלא \u0003משום מעשה שהיה,\u0004 שבאו בה לידי סכנה.","ושואלים עוד: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 כי מסקנת הדברים היא שכל עבודה שהיא \u0003עבודת יום ושזר חייב עליה מיתה בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס,\u0004 ואילו עבודה ש\u0003אין זר חייב עליה מיתה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס? והרי שחיטה\u0004 שכשירה בזר וצריכה פייס! ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שחיטה\u0004 ש\u0003תחלת עבודה היא\u0004 ולכן היא חשובה בעיני הכהנים וצריכה אף היא לפייס.","\u0003אמר מר זוטרא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אשי: והא אנן לא תנן הכי\u0004 \u0005[והרי אנו לא כך שנינו]\u0006 שסידור הגזירים הוא עבודת יום דווקא, שהרי שנינו: \u0003אמר להם הממונה צאו וראו אם הגיע זמן השחיטה. ואילו \"\u0004אם הגיע \u0003זמן שני גזירי עצים\" לא קתני\u0004 \u0005[שנה],\u0006 והרי זו ראיה שעבודה זו אינה דווקא עבודת יום, ויכולה להיעשות גם בלילה.","ודוחים: מכאן אין להוכיח כי רק \u0003הך דלית לה תקנתא קתני\u0004 \u0005[זו,\u0006 שחיטה בלילה, \u0005שאין לה תקנה —\u0006 \u0005שנה]\u0006 כי אם נשחט הקרבן שלא בזמנו, בלילה, אין כל תיקון לדבר, והקרבן נפסל. אבל \u0003הך דאית לה תקנתא\u0004 \u0005[זו,\u0006 סידור גזירי העצים, \u0005שיש לה תקנה]\u0006 שהרי אפשר להסירם ולחזור ולהניחם — \u0003לא קתני\u0004 \u0005[שנה]\u0006 אך לכתחילה זמנם ביום.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 סוגיה זו בלשון אחרת, \u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על דברי ר' יוחנן בענין זר שסידר את המערכה \u0003ר' זירא\u0004: \u0003וכי יש לך עבודה שיש אחריה עבודה\u0004 אחרת (כמו סידור שני גיזרי עצים) \u0003ופסולה בזר?\u0004"],["\u0003והרי\u0004 הקרבת \u0003אברים ופדרים\u0004 שפסולה בזר, אף שיש אחריה עבודה! ומשיבים: אין מכך ראיה, כיון שהקטרת איברים ופדרים \u0003סוף עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא.\u0004 ומקשים: \u0003והרי תרומת הדשן,\u0004 שיש לאחריה הוצאת הדשן ופסולה בזר! ודוחים: תרומת הדשן חשובה, לפי ש\u0003תחילת עבודה דיממא היא,\u0004 שהרי \u0003אמר ר' יוחנן:\u0004 מי ש\u0003קדש ידיו לתרומת הדשן, למחר\u0004 כשעלה השחר \u0003אינו צריך לקדש\u0004 שנית שהרי \u0003כבר קדש\u0004 ידיו \u0003מתחלת עבודה.\u0004 כיון שנדחו הפירכות על קושיית ר' זירא, שואלים: \u0003אלא קשיא\u0004 \u0005[קשה]\u0006 על דברי ר' יוחנן! \u0003אלא\u0004 יש לומר שלא נמסרו דברי ר' יוחנן כראוי ו\u0003אי אתמר הכי אתמר\u0004 \u0005[אם נאמר כך נאמר];\u0006 \u0003אמר ר' אסי אמר ר' יוחנן: זר שסידר שני גזירי עצים — חייב, הואיל ועבודה תמה היא\u0004 כלומר עבודה גמורה ושלימה היא, שאין לאחריה סידור נוסף של המערכה.","","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא: אלא מעתה תבעי\u0004 \u0005[תצטרך]\u0006 \u0003פייס\u0004 אף עבודה זו! ותוהים על דברי רבא: וכי \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003פייס? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שזכה בתרומת הדשן — יזכה\u0004 אף \u0003בסידור שני גזירי עצים,\u0004 הרי שיש פייס אף לסידור שני גזירי העצים! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך היתה קושייתו של רבא: אם עבודה חשובה היא, אם כן \u0003יפייסו לה בפני עצמה!\u0004 ומתרצים: \u0003כדאמרינן\u0004 \u0005[כמו שאמרנו]\u0006 בתחילת הפרק, שמתחילה לא היה פייס כלל לעבודות אלה משום שהן עבודות לילה (מהרשש\"ן).","","על פי דברי רבא שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שכל עבודה שהיא \u0003עבודה תמה וזר חייב עליה מיתה — בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס,\u0004 ואם \u0003אין זר חייב עליה מיתה — לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס? והרי שחיטה,\u0004 המותרת בזר וצריכה פייס! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 ה\u0003שחיטה\u0004 בכך ש\u0003תחילת עבודה דיממא\u0004 \u0005[של\u0006 יום\u0005]\u0006 היא ולכן היא חשובה. ושואלים עוד: \u0003למימרא\u0004 [האם לומר] ש\u0003עבודה תמה בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס,\u0004 ואילו \u0003עבודה שיש אחריה עבודה — לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003פייס? והרי\u0004 הקטרת \u0003אברים ופדרים\u0004 שיש אחריה עבודה וצריכה פייס! ומשיבים: אין מכאן קושיה, כי הקטרת איברים ופדרים \u0003סוף עבודה דיממא\u0004 \u0005[של היום]\u0006 \u0003היא\u0004 ולכן חשובה היא. ומקשים: \u0003הרי תרומת הדשן\u0004 שיש אחריה עבודה, וצריכה פייס? ומשיבים: אכן לא תיקנו בה פייס אלא \u0003משום מעשה שהיה,\u0004 שהסתכנו בה הכהנים ולכן תיקנו לה פייס מיוחד.","","\u0003אמר מר זוטרא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 שסידור שני גזירי העצים עבודה תמה היא, אלא שהיא עבודת לילה, שכן שנינו: \u0003אמר להם הממונה צאו וראו אם הגיע זמן השחיטה. ואילו \"זמן סידור גזירי עצים\" לא קתני\u0004 \u0005[שנה],\u0006 משמע שאין זמן עבודה זו ביום.","ודוחים: מכאן אין ראיה, כי \u0003הך דלית לה תקנתא\u0004 \u0005[זו,\u0006 השחיטה, \u0005שאין לה תקנה]\u0006 אם יעשוה שלא בזמנה \u0003קתני\u0004 \u0005[שנה],\u0006 \u0003הך דאית לה תקנתא\u0004 \u0005[זו שיש לה תקנה]\u0006 על ידי שיסדרנה מחדש \u0005—\u0006 \u0003לא קתני\u0004 \u0005[שנה],\u0006 אבל יתכן שאף היא נחשבת כעבודת יום, אלא שאינה עבודה תמה.","","בהמשך סדר היום, \u0003אמר להם הממונה\u0004 לכהנים: \u0003צאו\u0004 ועמדו על הגג או על החומה \u0003וראו אם הגיע זמן השחיטה,\u0004 כלומר: אם כבר האיר היום. כי שחיטה פסולה בלילה. \u0003אם הגיע\u0004 כבר הזמן, \u0003הרואה אומר: \"ברקאי\"\u0004 — הבריק האור. \u0003מתיא בן שמואל אומר:\u0004 בלשון אחרת שהוא שואל את הרואהו: \u0003\"האיר פני כל המזרח עד\u0004 שנראה האור אף \u0003בחברון\"? והוא\u0004 הרואה \u0003אומר: \"הן\"! ולמה הוצרכו לכך\u0004 לעלות ולבדוק אם האיר היום, שהוא לכאורה דבר הנראה לעין בכל מקום. משום \u0003שפעם אחת\u0004 אירע ש\u0003עלה מאור הלבנה, ודימו\u0004 לחשוב \u0003שהאיר\u0004 ה\u0003מזרח\u0004 בזריחת השמש, \u0003ושחטו את התמיד\u0004 לפני זמנו, ומשהבינו כי נשחט בלילה \u0003הוציאוהו לבית השריפה,\u0004 שהרי נפסל בשחיטה שלא בזמנו. וכדי להמנע מטעות כגון זו תיקנו שלעולם יהיו בודקים היטב אם אכן זרחה השמש.","לאחר שהיו מודיעים על תחילת היום, \u0003הורידו\u0004 את ה\u0003כהן\u0004 ה\u0003גדול לבית הטבילה.\u0004 ומעירים: \u0003זה הכלל היה במקדש: כל המיסך את רגליו\u0004 לצרכים גדולים — \u0003טעון טבילה\u0004 לאחר מכן, \u0003וכל המטיל מים — טעון קידוש\u0004 (רחיצת) \u0003ידים ורגלים\u0004 לאחר מכן."],["\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו חכמים מה היתה בדיוק הלשון שהיו אומרים במקדש, \u0003ר' ישמעאל אומר:\u0004 הנוסח היה \u0003\"ברק ברקאי\". ר' עקיבא אומר: \"עלה ברקאי\",\u0004 כלומר: האיר יותר מברק. \u0003נחומא בן אפקשיון אומר: \"אף ברקאי בחברון\". מתיא בן שמואל אומר: הממונה על הפייסות אומר: \"האיר פני כל המזרח עד שבחברון\". ר' יהודה בן בתירא אומר:\u0004 כך הוא אומר: \u0003\"האיר פני כל המזרח עד שבחברון, ויצאו כל העם איש איש למלאכתו\".\u0004","על שיטת ר' יהודה בן בתירא תוהים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שכבר יצאו הכל למלאכתם \u0003נגה ליה טובא\u0004 \u0005[האיר\u0006 היום \u0005ביותר],\u0006 שאין זה סמוך לעלות השחר, שהרי העם הולך למלאכתו כאשר היום כבר בעיצומו. ומשיבים: הכוונה היא \u0003לשכור פועלים קאמרינן\u0004 \u0005[אומרים אנו],\u0006 כלומר: בעלי השדות והפועלים היו משכימים לשכור את הפועלים לעבודתם, כדי שיתחילו במלאכתם עם האיר היום ושעה זו סמוכה לעלות השחר.","\u0003אמר רב ספרא: צלותיה\u0004 \u0005[תפילת]\u0006 מנחה של \u0003אברהם, מכי משחרי כותלי\u0004 \u0005[מהזמן שבו הכתלים משחירים]\u0006 כלומר מהרגע בו נוטה השמש מעט מאמצע השמים ונמצא צל כלשהו בכתלים הוא תחילת ערוב היום, ומאותה שעה היה מתפלל.","\u0003אמר רב יוסף:\u0004 וכי \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003מאברהם ניקום וניגמר\u0004 \u0005[נעמוד ונלמד]?!\u0006 והרי אברהם קודם מתן תורה היה, ואין ללמוד ממנו להלכה (גאונים)! \u0003אמר רבא:\u0004 הרי ה\u0003תנא גמר\u0004 \u0005[למד]\u0006 דבר הלכה \u0003מאברהם ואנן לא גמרינן מיניה\u0004 \u0005[ואנו לא נלמד ממנו]?!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"וביום השמיני ימול בשר ערלתו\"\u0004 (ויקרא יב, ג) \u0003מלמד\u0004 פסוק זה \u0003שכל היום\u0004 מתחלתו עד סופו, \u0003כשר למילה אלא שהזריזין מקדימין למצות, שנאמר: \"וישכם אברהם בבקר ויחבש\u0004 את חמורו\u0003\"\u0004 (בראשית כב, ג), שהשכים למצוה מיד ולא דחה. הרי שנלמדת הלכה ממנהגו של אברהם!","\u0003אלא אמר רבא: רב יוסף הא קא קשיא ליה\u0004 \u0005[\u0006דבר \u0005זה היה קשה לו],\u0006 כלומר: לא עצם הלימוד מאברהם אלא מפני טעם אחר, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 כש\u0003חל ערבי פסחים להיות בערב שבת\u0004 יש לנהוג כך: \u0003נשחט\u0004 התמיד של בין הערבים \u0003בשש ומחצה\u0004 שעות ביום, \u0003וקרב\u0004 על המזבח \u0003בשבע ומחצה,\u0004 שהיו מקדימים אז את שחיטת התמיד של בין הערבים ככל האפשר, משום שקרבן הפסח נשחט אחר תמיד זה, ויש לסיים את שחיטת הפסחים ולצלותם מבעוד יום, כדי שלא תיעשה מלאכה זו בשבת. ואם למדים הלכה זו מאברהם, מדוע אם כן לא נקדים \u0003ונשחטיה מכי משחרי כותלי\u0004 \u0005[ונשחט את\u0006 התמיד מיד \u0005כאשר מחחילים הכתלים להשחיר]\u0006 משעה ששית! אלא ודאי אין למדים מאברהם.","ודוחים: \u0003מאי קשיא\u0004 \u0005[מה הקושיה]?\u0006 \u0003ודילמא כותלי\u0004 \u0005[ושמא הכתלים]\u0006 של \u0003בית המקדש\u0004 אכן בשעה \u0003שש ומחצה\u0004 ביום בלבד \u0003משחרי\u0004 \u0005[\u0006היו \u0005משחירים],\u0006 \u0003משום\u0004 ש\u0003לא מכווני טובא\u0004 \u0005[\u0006היו \u0005מכוונים היטב],\u0006 שקירות המקדש היו רחבים במקצת מלמטה מפני רוב גובהם והלכו והצרו כלפי מעלה, ולכן לא הצל חודו העליון על תחתיתו אלא רק בשעה שש ומחצה. \u0003אי נמי\u0004 \u0005[או גם],\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003אברהם\u0004 שהרי אנו יודעים ש\u0003איצטגנינות גדולה היתה בלבו,\u0004 כלומר: שהיה חכם מופלג בחשבון התקופות והמזלות, והיה בקי ביותר בשעות, ואנו איננו בקיאים עד כדי כך. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003משום\u0004 ש\u0003זקן ויושב בישיבה הוה\u0004 \u0005[היה]\u0006 והיתה שכינה עמו, ויכול היה לכוון לשעה המדוייקת, ואין אחרים יכולים לעשות כן. כפי ש\u0003אמר ר' חמא בר' חנינא: מימיהן של אבותינו לא פרשה ישיבה מהם,\u0004 כלומר: שאבות האומה היו גדולי הדורות, ומורים את התורה לתלמידים שבאו לפניהם.","\u0003היו במצרים\u0004 — היתה \u0003ישיבה עמהם, שנאמר: \"לך ואספת את זקני ישראל\"\u0004 (שמות ג, טז), משמע כי במצרים היו חכמים (\"זקנים\") בישראל, שהיו לומדים תורה, וכן \u0003היו במדבר —\u0004 היתה \u0003ישיבה עמהם, שנאמר: \"אספה לי שבעים איש מזקני ישראל\"\u0004 (במדבר יא, טז). \u0003אברהם אבינו\u0004 עצמו \u0003זקן,\u0004 כלומר: חכם \u0003ויושב בישיבה היה, שנאמר: \"ואברהם זקן בא בימים\"\u0004 (בראשית כד, א), שכפילות הלשון \"זקן\" וגם \"בא בימים\" באה ללמד ש\"זקן\" פירושו בחכמה ובמעלות התורה, \"בא בימים\" — הוא זקן בשנים. וכן \u0003יצחק אבינו זקן ויושב בישיבה היה, שנאמר: \"ויהי כי זקן יצחק\"\u0004 (בראשית כז, א) וכן \u0003יעקב אבינו זקן ויושב בישיבה היה, שנאמר: \"ועיני ישראל כבדו מזקן\"\u0004 (בראשית מח, י).","ואף \u0003אליעזר עבד אברהם זקן ויושב בישיבה היה, שנאמר: \"ויאמר אברהם אל עבדו זקן ביתו המשל בכל אשר לו\"\u0004 (בראשית כד, ב) \u0003אמר ר' אלעזר:\u0004 כוונתו \u0003שמושל בתורת רבו\u0004 כלומר שהיה בקי בכל תורתו של אברהם, ולכן נאמר עליו: \u0003\"הוא דמשק אליעזר\"\u0004 (בראשית טו, ב) — \u0003אמר ר' אלעזר:\u0004 \"דמשק\" נוטריקון הוא: \u0003שדולה ומשקה מתורתו של רבו לאחרים.\u0004","ואכן אגב דברים אלה מביאים מה ש\u0003אמר רב: קיים אברהם אבינו כל התורה כולה\u0004 לפני שניתנה, \u0003שנאמר: \"עקב אשר שמע אברהם בקלי וישמר\u0004 משמרתי מצוותי חוקותי ותורותי\u0003\"\u0004 (בראשית כו, ה). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שימי בר חייא לרב: ואימא\u0004 \u0005[ואמור]\u0006 שקיים רק את \u0003שבע מצו‍ת\u0004 בני נח ולא את שאר כל התורה? ענה לו: \u0003הא איכא נמי\u0004 \u0005[הרי יש גם כן]\u0006 \u0003מילה,\u0004 שמפורש בכתוב שקיים אברהם, ומילה איננה בכלל שבע מצוות הללו, הרי שקיים אברהם יותר מהן! והקשה לו שוב: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שקיים רק \u0003שבע מצו‍ת ומילה! אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003אם כן\u0004 מה שנאמר באברהם ששמר \u0003\"מצותי ותורתי\" למה לי?\u0004 שהרי זה מראה על ריבוי מצות ותורות מסוגים שונים. ואינו נראה שמתכוון רק לשבע מצוות בלבד אלא לכאורה לכל התורה כולה!","\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב אשי: קיים אברהם אבינו\u0004 כל התורה \u0003אפילו\u0004 מצות \u0003עירובי תבשילין\u0004 שהיא מדברי סופרים, שתיקנוה לאחר מכן, \u0003שנאמר: \"תורתי\"\u0004 בלשון רבים, ללמד שקיים שתי תורות \u0003אחת תורה שבכתב ואחת תורה שבעל פה,\u0004 ובגדר תורה שבעל פה קיים את כל הפרטים והגדרים המצויים בה.","במשנתנו למדנו כי \u0003מתיא בן שמואל אומר\u0004 האיר פני כל המזרח עד שבחברון \u0003והוא אומר הן.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 זה ש\u0003אמר \"הן\"? אילימא הך דקאי אאיגרא\u0004 \u0005[אם תאמר זה שעומד על הגג]\u0006 — \u0003הוא חלים והוא מפשר\u0004 \u0005[הוא חולם והוא פותר]?!\u0006 כלומר: כיצד יתכן שהוא עצמו הוא השואל והוא העונה? \u0003אלא\u0004 תאמר \u0003הך דקאי אארעא\u0004 \u0005[\u0006ש\u0005זה שעומד בקרקע]\u0006 אומר \"הן\", \u0003מנא ידע\u0004 \u0005[מניין יודע\u0006 הוא\u0005]\u0006 שכן הוא, שיכול לענות הן?","ומתרצים בשני אופנים; \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור] —\u0006 \u0003הך דקאי אארעא\u0004 \u0005[זה שעומד על הארץ]\u0006 הוא שענה הן, \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור] —\u0006 \u0003הך דקאי אאיגרא\u0004 \u0005[זה שעומד על הגג]\u0006 הוא זה שענה. \u0003איבעית אימא הך דקאי אאיגרא\u0004 \u0005[אם תרצה אמור זה שעומד על הגג]\u0006 — \u0003אמר איהו\u0004 \u0005[הוא\u0006 זה שבגג\u0005]:\u0006 \u0003האיר פני כל המזרח. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003הך דקאי אארעא\u0004 \u0005[זה שעומד בקרקע]\u0006 בשאלה: האיר \u0003עד שבחברון? ואמר ליה\u0004 \u0005[לו]\u0006 \u0003איהו\u0004 \u0005[הוא,\u0006 העומד על הגג\u0005]:\u0006 \u0003הן.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 יכול אתה לפרש את הדו-שיח כך: \u0003הך דקאי אארעא\u0004 \u0005[זה שעומד על הקרקע]\u0006 הוא שאמר הן. וכך היה: \u0003אמר איהו\u0004 \u0005[הוא],\u0006 זה שבקרקע \u0003האיר פני כל המזרח? ואמר ליה\u0004 \u0005[לו]\u0006 זה שעל הגג, האם מתכוון אתה \u0003עד שבחברון? ואמר ליה\u0004 \u0005[לו]\u0006 העומד על הקרקע: \u0003הן,\u0004 אכן לכך אני מתכוון.","במשנה מוסבר \u0003ולמה הוצרכו לכך\u0004 לבדוק אם אמנם זרחה השמש, משום שפעם טעו והחליפו בין אור זריחת השמש ובין אור הירח והקדימו להקריב את התמיד של שחר. ושואלים: \u0003ומי מיחליף\u0004 \u0005[והאם\u0006 באמת \u0005מתחלפים\u0006 שני מאורות אלה\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003רבי אומר: אינו דומה תימור\u0004 (עליה) \u0003של\u0004 אור ה\u0003לבנה לתימור של חמה\u0004 (עלות השחר), כי \u0003תימור של לבנה מתמר ועולה\u0004 ישר \u0003כמקל\u0004 באור אחד ואילו \u0003תימור של חמה מפציע\u0004 (מתחלק אורו) \u0003לכאן ולכאן.\u0004 ומשיבים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 אותו יום \u0003יום המעונן היה, ומפציע\u0004 היה אף אור הלבנה \u0003לכאן ולכאן,\u0004 ובשל כך טעו לחשוב כי זוהי זריחת השמש. \u0003אמר רב פפא: שמע מינה\u0004 \u0005[למדנו מכאן]\u0006 מדברי ר' ישמעאל כי \u0003יומא דעיבא כוליה שמשא\u0004 \u0005[יום המעונן כולו שמש]\u0006 שאור השמש מתפזר על ידי העננים ומצוי בכל הפינות והכוונים.","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 אם אנו אומרים שיום זה כולו שמש? ומסבירים: \u0003לשטוחי\u0004 \u0005[ל\u0006ענין \u0005פריסת]\u0006 \u0003עורות\u0004 לייבוש, שביום המעונן אין הבדל באיזה מקום פורסים אותם, כיון שאור השמש הנשבר בעננים מגיע לכל מקום. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש לכך משמעות הלכתית \u0003לכדדרש\u0004 \u0005[לכמו שדרש]\u0006 \u0003רבא\u0004 לענין מצה: \u0003אשה לא תלוש\u0004 את העיסה למצות של פסח \u0003לא בחמה\u0004 במקום המואר בקרני שמש גם \u0003ולא בחמי חמה\u0004 (במים חמים שנתחממו על ידי השמש) ואם כן, לדברי רב פפא, ביום המעונן אינה יכולה ללוש אלא בתוך הבית, כיון שקרני השמש מפציעים מכל מקום.","אגב דברים אלה מביאים מה ש\u0003אמר רב נחמן: זוהמא דשימשא\u0004 \u0005[אותו אור עמום של השמש\u0006 ביום המעונן\u0005]\u0006 \u0003קשי משימשא\u0004 \u0005[\u0006הוא \u0005קשה\u0006 וחזק ומזיק יותר \u0005מאשר השמש\u0006 עצמה\u0005].\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 לכך: \u0003דנא דחלא\u0004 \u0005[מכסה של\u0006 כד \u0005חומץ],\u0006 שכל עוד מכוסה כד החומץ יפה, הריהו מונע בעד ריח החומץ מלצאת, אבל בהנקבו אפילו נקב קל, הריהו מדיף ריח חריף, יותר מאשר ריח החומץ עצמו. כך גם קרני השמש, כשהן כלואות תחת מסך העננים ויוצאות בנקבים שביניהן, עוצמתן רבה וחזקה מאד, יותר מכרגיל. \u0003שברירי דשימשא\u0004 \u0005[סנוורי השמש],\u0006 הבאים דרך נקבים זעירים שבעננים \u0003קשו משימשא\u0004 \u0005[קשים\u0006 לעיניים \u0005יותר\u0006 מאור \u0005השמש]\u0006 הגלוי. \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003דילפא\u0004 \u0005[דלף]\u0006 היורד במקום אחד, שהוא מטריד את האדם הרבה יותר מאשר אם נכנס כולו למים."],["\u0003הרהורי עבירה קשו\u0004 \u0005[קשים,\u0006 גרועים\u0005]\u0006 \u0003מעבירה\u0004 עצמה \u0003וסימניך\u0004 \u0005[סימנך]:\u0006 \u0003ריחא דבישרא\u0004 \u0005[ריח של בשר],\u0006 שריח הבשר מגרה יותר מאשר הוא עצמו. \u0003שילהי דקייטא קשיא מקייטא\u0004 \u0005[\u0006סוף הקיץ קשה בחומו \u0005מהקיץ\u0006 עצמו\u0005].\u0006 \u0003וסימניך\u0004 \u0005[סימנך]:\u0006 \u0003תנורא שגירא\u0004 \u0005[תנור שהוסק]\u0006 שלאחר שהוסק כמה פעמים ביום ונתחמם כבר למדי, הסקה נוספק ולו הקלה ביותר, גורמת לחממו ביותר. וכן הוא בסוף הקיץ, שמאחר שהכל חם מכבר, חומו קשה יותר.","\u0003אישתא דסיתוא קשיא מדקייטא\u0004 \u0005[קדחת בחורף קשה מזו של הקיץ].\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]:\u0006 \u0003תנורא קרירא\u0004 \u0005[תנור קר],\u0006 כי כדי לחמם תנור קר יש צורך בהיסק רב יותר, וכמו כן קדחת המחממת את הגוף בחורף למרות הצינה ודאי קשה היא מזו שבקיץ. \u0003מיגמר בעתיקתא קשיא מחדתא\u0004 \u0005[ללמוד\u0006 דבר \u0005ישן,\u0006 שלמד ושכח, \u0005קשה מללמוד\u0006 דבר \u0005חדש].\u0006 \u0003וסימניך\u0004 \u0005[וסימנך]\u0006 \u0003טינא בר טינא\u0004 \u0005[טיט בן טיט]\u0006 כי קשה מאד לגבל טיט שנעשה מחרס שגיבלו פעם אחת והתפורר.","לענין ראשון של תימור הלבנה והחמה \u0003אמר ר' אבהו: מאי טעמיה\u0004 \u0005[מה טעמו],\u0006 כלומר: מהיכן הביא \u0003רבי\u0004 ראיה לדבריו כי קרני החמה מפציעות ובכך אינו דומה תימור הלבנה לתימור החמה? — \u0003דכתיב\u0004 [שנאמר]: \u0003\"למנצח על אילת השחר\"\u0004 (תהלים כב, א), לומר: \u0003מה אילה זו קרניה מפצילות לכאן ולכאן — אף שחר זה מפציע\u0004 אורו \u0003לכאן ולכאן\u0004 וכדברי רבי.","במסכת מגילה (ז, א) נאמר, כי מזמור זה נאמר בשעתו על ידי אסתר המלכה כדברי נבואה על עצמה ועל מצבה בעת ההיא. \u0003אמר ר' זירא: למה נמשלה אסתר לאילה — לומר לך: מה אילה רחמה צר וחביבה על בעלה כל שעה ושעה כשעה ראשונה, אף אסתר היתה חביבה על אחשורוש כל שעה ושעה כשעה ראשונה. אמר ר' אסי: למה נמשלה אסתר לשחר — לומר לך: מה שחר סוף כל הלילה, אף אסתר סוף כל הנסים\u0004 שהיו לכלל ישראל.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את נס \u0003חנוכה\u0004 שאירע שנים רבות לאחר מכן! ומשיבים: \u0003ניתנה לכתוב קא אמרינן\u0004 \u0005[אומרים אנו]\u0006 שאומנם היו ניסים גם לאחר נס פורים, אבל זה היה הנס האחרון שניתן ליכתב בתוך ספרי המקרא. ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה נוח\u0006 לשיטת \u0005מי שאומר]\u0006 כי מגילת \u0003אסתר ניתנה לכתוב\u0004 והיא חלק מהותי מספרי המקרא. \u0003אלא למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאומר]\u0006 כי \u0003אסתר לא ניתנה לכתוב\u0004 ומגילת אסתר הכתובה אין קדושתה כקדושת שאר ספרי המקרא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 לפי שיטתו?","ומשיבים: \u0003מוקים לה\u0004 \u0005[מעמיד אותה]\u0006 מסביר את הדימוי לאילת השחר כדברי \u0003ר' בנימין בר יפת אמר ר' אלעזר.\u0004 ש\u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: למה נמשלו תפלתן של צדיקים כאילת — לומר לך מה אילה זו כל זמן שמגדלת\u0004 כלומר כל שנה ושנה — \u0003קרניה מפצילות,\u0004 שמוסיפות פיצול נוסף \u0003אף צדיקים\u0004 כן, \u0003כל זמן שמרבין בתפלה — תפלתן נשמעת.\u0004","במשנה מסופר כי פעם אירע שטעו ו\u0003שחטו את התמיד\u0004 לפני זמן עלות השחר, לאחר שהחליפו את מאור החמה במאור הלבנה. ושואלים: \u0003אימת\u0004 \u0005[אימתי היה]\u0006 מעשה זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה מעשה זה \u0003בשאר ימות השנה, לא סגיא דלאו\u0004 \u0005[לא די שלא]\u0006 \u0003כהן גדול\u0004 הוא שעושה עבודה זו? שהרי מסופר שם שהורידו כהן גדול לבית הטבילה, והרי בשאר ימות השנה אין הכהן הגדול צריך להשכים לעבודה זו, שהרי יכולה היא שתיעשה בכל כהן שהוא. \u0003אלא\u0004 חייב אתה לפרש שמעשה זה היה \u0003ביום הכפורים\u0004 שרק הוא יכול לעשותה, אולם אז \u0003מאור הלבנה מי איכא\u0004 \u0005[האם יש]?\u0006 כי לפי חוקי הבריאה, לעולם לא יעלה הירח במזרח סמוך לעלות השחר ביום הכיפורים!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: הטעות שאירעה היתה בשאר ימות השנה, ומאז תיקנו תקנה זו שיכריזו על עלות השחר. ואילו \u0003ביום הכפורים כי אמר\u0004 \u0005[כאשר אומר]\u0006 האיש \u0003\"ברק ברקאי\"\u0004 מיד \u0003הורידו\u0004 את ה\u0003כהן\u0004 ה\u0003גדול לבית הטבילה.\u0004","בקשר להלכה היסודית \u0003תני אבוה\u0004 \u0005[שנה אביו]\u0006 של \u0003ר' אבין\u0004 ברייתא זו: \u0003לא זו בלבד אמרו\u0004 שקרבן התמיד שנשחט לפני עלות השחר פסול וצריך לשורפו, \u0003אלא אף מליקת העוף, וקמיצת מנחה\u0004 אם נעשתה \u0003בלילה — תשרף.\u0004 ומעיינים בלשון הברייתא: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003עולת העוף, מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 שכיון שנמלק העוף שלא בזמן הראוי לו, ואי אפשר לתקן את המעשה — הרי הוא פסול, ונשרף, \u0003אלא קומץ\u0004 המנחה מה טעם יישרף?"],["\u0003נהדרה\u0004 \u0005[נחזיר אותה]\u0006 את הקמיצה שהוציאו מן המנחה בלילה \u0003ונהדר ונקמצה ביממא\u0004 \u0005[ונחזור ונקמוץ אותה ביום]\u0006 ומפני מה תשרף המנחה? ומסבירים: \u0003הוא תני לה והוא אמר לה\u0004 \u0005[הוא שנה אותה\u0006 את הברייתא הזו שבאה אליו במסורת \u0005והוא אמר\u0006 תרגם והסביר \u0005אותה]\u0006 כך: \u0003כלי שרת מקדשין\u0004 את שבתוכן \u0003אפילו שלא בזמנו.\u0004 וכיון שהניחו את הקומץ בתוך כלי שרת מיוחד, מיד חלה עליו קדושת הקומץ, ואף שנעשה הדבר שלא בזמנו, כבר חלה עליו הקדושה, ומכיון שנעשה כשלא בזמנו — שוב אין לו תקנה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003זה הכלל: כל\u0004 קרבן \u0003הקרב ביום קדוש\u0004 (מתקדש) בהקרבתו \u0003ביום, וכל הקרב בלילה —\u0004 אינו נעשה \u0003קדוש\u0004 אלא \u0003בלילה, וכל הקרב בין ביום ובין בלילה —\u0004 נשעה \u0003קדוש בין ביום בין בלילה.\u0004 ולעניננו: \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 כי \u0003כל הקרב ביום — קדוש ביום,\u0004 ונדייק: \u0003ביום — אין\u0004 \u0005[כן],\u0006 אולם \u0003בלילה לא,\u0004 אינו מתקדש, ואם אינו מתקדש — אף אינו נפסל, וקשה אם כן לדברי ר' אבין! ומשיבים: \u0003דילמא\u0004 \u0005[שמא]\u0006 מה שאמרו \u0003\"אינו קדוש\",\u0004 כוונתו: אם נעשה שלא בזמנו אינו קדוש כדי \u0003ליקרב\u0004 על המזבח, \u0003אבל קדוש\u0004 מספיק כדי \u0003ליפסל.\u0004","על עיקר סברתו של ר' אבין \u0003מתיב\u0004 \u0005[מקשה]\u0006 עוד \u0003ר' זירא,\u0004 ממה ששנינו: \u0003סידר את הלחם\u0004 (לחם הפנים) על שולחן הזהב \u0003ואת הבזיכין\u0004 של קטורת השייכים ללחם, במקום לסדרם כדינם בשבת, סדרם \u0003אחר השבת\u0004 (ביום ראשון), אף כי \u0003הקטיר את הבזיכין בשבת — פסולה,\u0004 שהרי סידרו שלא בזמנו ונמצא שאינה מונחת על השלחן שבעה ימים כמשפטה.","\u0003כיצד יעשה\u0004 ולא יפסל? \u0003יניחנו\u0004 את הלחם הזה \u0003לשבת הבאה\u0004 בלא שיסירנו מעל השולחן. \u0003שאפילו עמדה\u0004 מערכת הלחם \u0003על השלחן ימים רבים אין בכך כלום\u0004 ובשבת עושים את הסידור ואת ההנחה כדרכם. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 תועיל תקנה זו? שהרי אם כלי שרת מקדשין אפילו שלא בזמנם, כיון שהניחו את מערכת הלחם על השולחן \u0003תקדוש\u0004 \u0005[תקדש]\u0006 \u0003ותיפסל!\u0004","\u0003אמר רבא: מאן דקא מותיב\u0004 \u0005[מי שמקשה,\u0006 ר' זירא\u0005]\u0006 \u0003— שפיר קא מותיב\u0004 \u0005[יפה הוא מקשה]\u0006 \u0003ואבוה\u0004 \u0005[ואביו]\u0006 של \u0003ר' אבין נמי מתניתא קאמר\u0004 \u0005[גם כן ברייתא אמר].\u0006 כלומר: מקור דבריו הוא בדברי תנאים בברייתא, ולכך יש עדיין ליישב את סתירת הברייתות ואין לדחות את דבריו בסתם. וכך יש ליישב את הסתירה: התנא שהביא ר' אבין \u0003קסבר\u0004 \u0005[סבר]:\u0006 \u0003לילה אין מחוסר זמן,\u0004 כלומר: דבר שצריך להיעשות ביום ונעשה בלילה טרם זמנו, אינו נקרא לגמרי \"מחוסר זמן\" משום שהלילה והיום נחשבים כיחידה אחת, ולכן כלי שרת מקדשים אותו אף בלילה, אולם אם חסר \u0003יום\u0004 שלם או יותר הרי זה כ\u0003מחוסר זמן,\u0004 ואין קדושה חלה עליו ולכן אין השולחן מקדש את הלחם שהונח עליו שבוע טרם זמנו.","ומקשים: לשיטה זו, שלילה אינו מחוסר זמן, אם כן \u0003כי מטי בי שמשי תקדוש ותפסול\u0004 \u0005[כאשר יגיע הערב\u0006 ערב שבת \u0005תקדש\u0006 מערכת הלחם משום קדושת השלחן \u0005ותפסל]\u0006 אז! שהרי התקדש הלחם בליל שבת ומשעלה השחר נפסל בלינה. \u0003אמר רבינא:\u0004 מדובר כאן \u0003שקדם וסלקו,\u0004 כלומר: שסמוך לחשכה צריך לסלק הלחם מעל השלחן, כך שלא חלה עליו קדושה להפסל וחוזר ומסדרו ביום. \u0003מר זוטרא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב אשי אמר\u0004 לתרץ קושיה זו כך: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003בשלא קדם וסלקו,\u0004 אלא \u0003כיון שסדרו\u0004 מתחילה \u0003שלא כמצותו\u0004 ושלא בזמנו, \u0003נעשה\u0004 כאילו \u0003סדרו הקוף\u0004 ואינו נחשב כסידור שיתקדש בשלו הלחם, ולכן אף אינו נפסל. ומשיעלה השחר יסלקנו הכהן מעל השלחן ויחזור יסדרנו כמצוותו. מה שאין כן בקמיצה שהוקטרה לפני זמנה, שכיון שנעשתה כמצותה ובכוונה, הרי בשעה שמניחים אותה בכלי קודש חלה עליה מיד קדושת הכלי והריהי נפסלת.","שנינו במשנה: \u0003זה הכלל היה במקדש\u0004 שהמיסך רגליו טובל לפני עבודה, והנפנה לצרכים קטנים צריך לקדש (לרחוץ) ידיו ורגליו. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שצריך לרחוץ רגליו יש לכך טעם \u0003משום ניצוצות\u0004 (טיפות זעירות) העשויות להיות ניתזות על רגליו בשעה שהוא נפנה, \u0003אלא ידים מאי טעמא\u0004 \u0005[מה טעם]\u0006 יש לרחוץ אותן, והלא ידים לא נגעו כלל בדבר מטונף? \u0003אמר ר' אבא: זאת אומרת,\u0004 מכאן יש ללמוד להלכות דרך ארץ, כי"],["\u0003מצוה לשפשף\u0004 את ניתזי מי הרגלים מעל רגליו כדי שלא ייראו. ומשום שבשפשוף זה מתלכלכות ידיו — צריך קידוש. ומעירים: \u0003מסייע ליה\u0004 הדבר \u0003לר' אמי,\u0004 ש\u0003אמר ר' אמי: אסור לאדם שיצא בניצוצות\u0004 של מי רגלים \u0003שעל גבי רגליו, מפני שנראה ככרות שפכה\u0004 (שנפגם אבר המין שלו) וכיון שאנשים יודעים שמי שהוא כרות שפכה אין מי רגליו ניתזין למרחוק, וכשרואים אדם שיש עליו נתזים, סבורים שהוא כרות שפכה ואינו יכול להוליד, ובכך הריהו \u0003מוציא לעז על בניו\u0004 בכך שיאמרו האנשים \u0003שהן ממזרים,\u0004 לפי שאינם ממנו. ומשום כך מצוה לשפשף שלא לגרום לידי הוצאת לעז כזאת.","אגב הדברים האמורים בענין זה \u0003אמר רב פפא: צואה במקומה\u0004 כלומר: בנקב פי טבעת \u0003אסור\u0004 אדם זה \u0003לקרות קריאת שמע\u0004 עד שיתנקה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר שהיא \u0003נראית\u0004 מבחוץ, אם כן \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאסור לו לקרוא, שהרי צואה על בשרו מבחוץ. \u0003אי\u0004 \u0005[אם]\u0006 מדובר שהיא \u0003לא נראית\u0004 והיא מבפנים, כיצד נוכל לומר שאסור לו לקרוא? והרי \u0003לא ניתנה תורה למלאכי השרת,\u0004 ולא יתכן שיהיה אדם שגופו נקי בלי צואה כלל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא באופן זה שכשהוא \u0003יושב\u0004 הריהי \u0003נראית\u0004 בחוץ, וכש\u0003עומד אינה נראית\u0004 ובאופן כזה אסור הוא בקריאת שמע.","ושואלים: אם כך \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מצואה\u0004 ש\u0003על בשרו? דאיתמר\u0004 \u0005[ש\u0006כבר \u0005נאמר]\u0006 שנחלקו חכמים במי שהיתה \u0003צואה על בשרו, או שהיו ידיו\u0004 בלבד \u0003בבית הכסא; רב הונא אמר: מותר\u0004 לו \u0003לקרות קריאת שמע\u0004 שצואה זו אינה מעכבת, \u0003ורב חסדא אמר: אסור לקרות קריאת שמע.\u0004 ודוחים: אין להשוות את הדברים זה לזה, כי צואה במקומה חמורה יותר שכן \u0003במקומה\u0004 (בפי הטבעת) \u0003נפיש זוהמא\u0004 \u0005[גדולה זוהמתה]\u0006 שהרי טריה היא ומסריחה ביותר, \u0003שלא במקומה\u0004 כבר התייבשה ו\u0003לא נפיש זוהמא\u0004 \u0005[ואין זוהמתה מרובה\u0006 כל כך\u0005],\u0006 ולכן יתכן שאין מקום למחלוקת באותו נושא.","ועוד באותם נושאים. נאמרה בברייתא \u0003תנו רבנן הלכה בסעודה: אדם יוצא להשתין מים\u0004 בזמן הסעודה — \u0003נוטל ידו אחת\u0004 שבה שפשף את הניצוצות \u0003ונכנס\u0004 שוב לסעודה. יצא, \u0003דיבר עם חבירו והפליג\u0004 (ושהה זמן רב בחוץ) \u0003נוטל שתי ידיו ונכנס\u0004 שמן הסתם שכח בתוך כדי הדבור להזהר בנקיות הידים, והיסח הדעת טעון נטילת ידים שנית. \u0003וכשהוא נוטל\u0004 ידיו לסעודה \u0003לא יטול מבחוץ ויכנס, מפני\u0004 ה\u0003חשד\u0004 שיחשדוהו שאר האורחים שמא לא נטל ידיו. \u0003אלא\u0004 כך עושה: \u0003נכנס ויושב במקומו ונוטל שתי ידיו, ומחזיר הטפיח\u0004 (כד המים) \u0003על\u0004 פני \u0003האורחין\u0004 ושואל מי מהם זקוק למים, כדי שיוודע לכולם שנטל ידיו, ולא יחשדוהו.","\u0003אמר רב חסדא: לא אמרן\u0004 דבר זה שעליו ליטול ידיו בפומבי \u0003אלא\u0004 כשהוא נכנס ואינו מתכווין אלא \u0003לשתות\u0004 בלבד, \u0003אבל\u0004 אם נכנס ועדיין בכוונתו \u0003לאכול\u0004 — אף \u0003נוטל מבחוץ ונכנס,\u0004 ומדוע? — \u0003דמידע ידיע דאנינא דעתיה\u0004 \u0005[שידוע הדבר שאנינה דעתו,\u0006 שהוא מפונק\u0005]\u0006 ובודאי לא יבוא לקחת בידיו מאכלים כשידיו מלוכלכות ממי רגלים וכיוצא בהם. \u0003אמר רב נחמן בר יצחק: ואנא\u0004 \u0005[ואני,\u0006 ושכמותי\u0005]\u0006 \u0003אפילו\u0004 אני נכנס \u0003לשתות נמי\u0004 \u0005[גם כן]\u0006 איני צריך ליטול ידי בפומבי, כי \u0003מידע ידעי דאנינא דעתאי\u0004 \u0005[ידוע שאנינה דעתי,\u0006 שאני מפונק\u0005]\u0006 ובודאי נטלתי ידים קודם שנכנסתי לאכול.","\u0003אין אדם נכנס לעזרה לעבודה\u0004 בקודש \u0003אפילו\u0004 אם היה \u0003טהור\u0004 ודאי \u0003עד שיטבול\u0004 טבילה מיוחדת. ואילו ביום הכיפורים \u0003חמש טבילות ועשרה קדושין\u0004 (רחיצות ידים ורגלים) \u0003טובל\u0004 היה ה\u0003כהן\u0004 ה\u0003גדול ומקדש בו ביום, וכולן\u0004 כל הטבילות והקדושין הללו היו \u0003בקדש,\u0004 מ\u0003על\u0004 גג לשכת \u0003בית הפרוה. חוץ מזו\u0004 טבילה ראשונה \u0003בלבד\u0004 שאינה שייכת דווקא לטבילות של יום הכיפורים, ולכן יכולה להיעשות אף בחוץ. \u0003פרסו סדין של בוץ\u0004 (פשתן) \u0003בינו ובין העם\u0004 משום צניעות ואז היה טובל ומקדש.","\u0003שאלו את בן זומא: טבילה זו\u0004 שטובל בכל יום כל הנכנס לעבודה, \u0003למה? אמר להם: ומה המשנה מקודש לקודש\u0004 כהן גדול ביום הכיפורים, המשנה מעבודת קודש אחת לעבודת קודש אחרת, והוא נכנס \u0003ממקום שענוש כרת\u0004 אם נכנס בו בטומאה, כלומר, מן העזרה \u0003למקום שענוש כרת,\u0004 כגון האולם או קודש הקדשים, ובכל זאת כיון שמשנה מעבודה לעבודה — \u0003טעון טבילה. המשנה מחול לקודש, וממקום שאין ענוש כרת למקום שענוש כרת — אינו דין שטעון טבילה?\u0004 ומשום כך תיקנו טבילה זו שהיא טבילה לקדושה, ולא להטהר מטומאה.","\u0003ר' יהודה אומר: סרך טבילה היא זו,\u0004 שאין בה מצוה מצד עצמה, אלא היא כתוספת לענין טבילה \u0003כדי שיזכור טומאה ישנה שבידו ויפרוש\u0004 שאגב טבילה יזכר, שמא הוא טמא טומאת מת או טומאה אחרת שהיא טומאת שבעה, ולא יבוא לעבוד בטומאה.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005חלוקים]\u0006 בן זומא ור' יהודה, שהם נותנים שני הסברים שונים לטבילה זו?"],["\u0003באחולי\u0004 \u0005[בחילול]\u0006 ה\u0003עבודה\u0004 אם לא טבל לפניה \u0003קא מיפלגי\u0004 \u0005[הם חלוקים].\u0006 לשיטת \u0003בן זומא\u0004 אם לא טבל, הריהו \u0003מחיל\u0004 \u0005[מחלל]\u0006 \u0003עבודה,\u0004 שלדעתו טבילת קדושה זו היא חלק מסדר העבודה. ואילו לשיטת \u0003ר' יהודה לא מחיל\u0004 \u0005[אינו מחלל]\u0006 את ה\u0003עבודה,\u0004 כיון שטבילה זו אינה אלא משום סייג.","ותוהים: \u0003ולבן זומא מי מחיל\u0004 \u0005[האם מחלל הוא]\u0006 עבודה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כהן גדול שלא טבל ולא קידש\u0004 ידיו ורגליו \u0003בין בגד\u0004 זהב \u0003לבגד\u0004 לבן, וכן אם לא טבל \u0003בין עבודה לעבודה — עבודתו כשרה.\u0004 אולם \u0003אחד כהן גדול ואחד כהן הדיוט שלא קידש ידיו ורגליו\u0004 כלל \u0003שחרית ועבד עבודה — עבודתו פסולה.\u0004 וכיון שאפילו טבילת כהן גדול בין עבודה לעבודה איננה מחללת, כל שכן טבילה ראשונה, שבן זומא לומד אותה רק מטבילת כהן גדול!","\u0003אלא\u0004 יש לדחות הסבר זה, ולומר: \u0003למיקם\u0004 \u0005[לעמוד\u0006 לעבור\u0005]\u0006 באיסור \u0003עשה קא מיפלגי\u0004 \u0005[\u0006בכך \u0005הם נחלקו]:\u0006 לשיטת \u0003בן זומא — קאי\u0004 \u0005[עומד הוא,\u0006 עובר\u0005]\u0006 \u0003בעשה,\u0004 שהרי היא מצוה מיוחדת לטבול לצורך הקדושה. ואילו לשיטת \u0003ר' יהודה — לא קאי\u0004 \u0005[אינו עומד,\u0006 עובר\u0005]\u0006 באיסור \u0003בעשה\u0004","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 מקבל\u0005]\u0006 \u0003לר' יהודה האי סברא\u0004 \u0005[סברה זו]\u0006 של חיוב טבילה כדי להיזכר בטומאה ישנה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003מצורע\u0004 ביום השמיני לטהרתו, אחר שטבל כבר בסוף היום השביעי — \u0003טובל\u0004 פעם נוספת \u0003ועומד בשער ניקנור\u0004 במקדש כדי להביא קרבנות כפרתו, וכדי שיתן הכהן על בהונותיו מדם האשם והשמן כדי לטהרו לגמרי. \u0003ר' יהודה אומר: אינו צריך טבילה,\u0004 לפי \u0003שכבר טבל מבערב.\u0004 הרי שלא הצריך ר' יהודה טבילה מיוחדת בבוקר כדי לפרוש מטומאה!","ותוהים: \u0003ההוא\u0004 \u0005[שם]\u0006 בענין מצורע, אינו צריך לטבול פעם נוספת \u0003כדתני טעמא\u0004 \u0005[כפי ששנוי הטעם]\u0006 במפורש: לפי \u0003שכבר טבל מבערב,\u0004 ובאותה טבילה כבר תיקן כל הצריך תיקון, ואף נזכר לפרוש מטומאתו. ואין איפוא שייכות בין דין זה לענין סרך טבילה של הנכנס לעזרה.","ושואלים: אם כן \u0003ודקארי לה מאי קארי לה\u0004 \u0005[וזה שהקשה\u0006 את הקושיה \u0005מה ראה להקשות\u0006 קושיה זו\u0005]?\u0006 שהרי לכאורה טעם הדין מפורש בגוף הענין! ומשיבים: \u0003משום דקא בעי למרמא אחריתי עליה\u0004 \u0005[שרצה להקשות\u0006 עוד ברייתא \u0005אחרת עליה]\u0006 ומתוך צירוף הדברים תתברר הקושיה. שהרי שנינו: מדוע היתה נקראת \u0003לשכת המצורעין — ששם מצורעין טובלין. ר' יהודה אומר: לא מצורעין בלבד אמרו, אלא כל אדם.\u0004 הרי שלדבריו בברייתא זו היו המצורעים טעונים טבילה במקדש (אלא שלא רק הם בלבד) והרי זו סתירה לדבריו בברייתא הראשונה, שאינו צריך לטבול במקדש ביום השמיני ודי לו במה שטבל מאתמול!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא דטביל\u0004 \u0005[זה שטבל]\u0006 כבר מבערב — אינו צריך לטבול שנית, \u0003והא דלא טביל\u0004 \u0005[וזה שלא טבל]\u0006 ולשם כך היתה מוכנה עבורו לשכה מיוחדת, שבה היו המצורעין טובלין. ומקשים: \u0003אי דלא טביל\u0004 \u0005[אם לא טבל]\u0006 המצורע כלל מבערב הקודם אם כן עדיין \u0003הערב שמש בעי\u0004 \u0005[צריך]\u0006 שיש לו להמתין עד שתעריב השמש בסוף היום כדי שיטהר לגמרי מטומאתו, ובינתים אסור לו כלל להיכנס למקדש! \u0003אלא\u0004 יש לתרץ באופן אחר; \u0003אידי ואידי דטביל\u0004 \u0005[זה וזה\u0006 מדובר \u0005שטבל]\u0006 כבר המצורע, אלא \u0003הא\u0004 \u0005[זה]\u0006 שהצריכוהו טבילה שנית מדובן באופן \u0003דאסח דעתיה\u0004 \u0005[שהסיח דעתו]\u0006 ולא נשמר מטומאת מת, \u0003הא\u0004 \u0005[זה]\u0006 שאינו טעון טבילה, מדובר ש\u0003לא אסח דעתיה\u0004 \u0005[הסיח דעתו].\u0006","ומקשים: \u0003אי אסח דעתיה\u0004 \u0005[אם הסיח דעתו]\u0006 מלהשמר בטהרה, אם כן אין די לו בטבילה, אלא \u0003הזאת שלישי ורביעי בעי\u0004 \u0005[צריך\u0006 הוא\u0005],\u0006 שיש להזות עליו מי חטאת ביום שלישי והשביעי לטהרו מספק טומאת מת, שכן \u0003אמר ר' דוסתאי בר מתון אמר ר' יוחנן: הסח הדעת צריך הזאה שלישי ושביעי!\u0004 ואם כן אין מקום להסבר זה בהיסח הדעת.","\u0003אלא אידי ואידי דלא אסח דעתיה\u0004 \u0005[זה וזה\u0006 מדובר \u0005שלא הסיח דעתו]\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 \u0003הא\u0004 \u0005[כאן]\u0006 שר' יהודה אינו מצריכו טבילה שנית, מדובר \u0003דטביל\u0004 \u0005[שטבל]\u0006 בערב גם \u0003על דעת\u0004 טהרה המיוחדת ל\u0003ביאת מקדש, הא\u0004 \u0005[זו]\u0006 שהצריכו טבילה שנית מדובר ש\u0003לא טביל\u0004 \u0005[טבל]\u0006 \u0003בערב על דעת ביאת מקדש\u0004 ולכן צריך טבילה שניה להיטהר אפילו לקודש. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 ותקן משהו בגירסת אותה ברייתא, ובכך תתורץ הקושיה מעצמה, וכך תאמר: \u0003לא מצורעין אמרו אלא כל אדם.\u0004 כלומר, ר' יהודה אינו מוסיף על דברי חכמים, אלא חולק עליהם: לדעתו מצורעין אינם צריכים טבילה, אבל שאר כל אדם זקוקים לכך.","\u0003רבינא אמר\u0004 אפשר להסביר כך: \u0003ר' יהודה\u0004 בברייתא השניה \u0003לדבריהם דרבנן קאמר להו\u0004 \u0005[אמר להם]\u0006 שהרי אין בדבריו ביטוי מלא לשיטתו, אלא נאמרו תוך כדי ויכוח עם החכמים, וכך יש להבין את דבריו: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003מצורע אין צריך טבילה\u0004 כלל בבואו למקדש, אבל \u0003לדידכו אודו לי איזי מיהת\u0004 \u0005[לשיטתכם הודו לי לפחות]\u0006 ש\u0003לא מצורעין בלבד אמרו\u0004 שטעונים טבילה זו \u0003אלא כל אדם.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם סבורים כן, כיצד אכן מסבירים הם את שיטתם? ומתרצים: לטענתם אין זו השוואה: שכן \u0003מצורע\u0004 כיון שהיה טמא טומאה חמורה \u0003דייש\u0004 \u0005[הריהו דש,\u0006 רגיל\u0005]\u0006 \u0003בטומאה\u0004 ולכן הצריכוהו טבילה מיוחדת כדי להזכירו שמא נטמא טומאה אחרת ושכח להטהר מאותה טומאה, אבל \u0003כל\u0004 שאר בני \u0003אדם לא דיישי\u0004 \u0005[דשים,\u0006 רגילים\u0005]\u0006 \u0003בטומאה\u0004 ואם נטמאו בודאי זכורים הם, ואינם צריכים עוד טבילה מיוחדת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: נימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003רבנן דפליגי עליה\u0004 \u0005[חכמים שחלוקים עליו]\u0006 על \u0003ר' יהודה\u0004 בענין הטבילות \u0003כבן זומא\u0004 הסובר כי טבילת כל הנכנס לעבודה הריהי חובה מן התורה \u0003סבירא להו\u0004 \u0005[סבורים הם],\u0006 \u0003והאי דקתני\u0004 \u0005[וזה ששנו]\u0006 את המחלוקת הזו לענין \u0003מצורע\u0004 דווקא ולא אמרו כבן זומא, הרי זה \u0003להודיעך כחו\u0004 של \u0003ר' יהודה\u0004 ששיטתו קיצונית כל כך, עד שאפילו במצורע אינו מצריך טבילה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 בעיקר הדברים סבורים הם כר' יהודה אולם \u0003שאני\u0004 \u0005[שונה]\u0006 דין ה\u0003מצורע\u0004 משום \u0003דדייש\u0004 \u0005[שהוא דש,\u0006 רגיל\u0005]\u0006 \u0003בטומאה\u0004 ולכן התקינו לו טבילה מיוחדת להפרישו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: לדעתו טעמם של חכמים הוא משום \u0003שאני\u0004 \u0005[שונה]\u0006 דין ה\u0003מצורע\u0004 משום \u0003דדייש\u0004 \u0005[שהוא דש,\u0006 רגיל\u0005]\u0006 \u0003בטומאה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 לשיטת \u0003ר' יהודה\u0004 ש\u0003אמר: סרך טבילה היא זו\u0004 שטבילה זו איננה מצוה ממש, אלא לתוספת ולזכרון בלבד היא,"],["האם דבר שנחשב כחציצה בשאר טבילות \u0003חוצץ\u0004 אף בטבילה זו ופוסלה, \u0003או אינו חוצץ,\u0004 כיון שאין טבילה זו אלא כתוספת לענין זכרון? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003כל\u0004 דין \u0003דתקון רבנן\u0004 \u0005[שתיקנו חכמים] —\u0006 \u0003כעין דאורייתא תקון\u0004 \u0005[\u0006דברי \u0005תורה תיקנו]\u0006 ולכן אף הלכה שאינה אלא מדברי סופרים יש לנהוג בה כבדברי תורה, ולכן יש להקפיד אף על חציצה בטבילה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: ביאה במקצת\u0004 כאשר אדם איננו נכנס כולו, אלא רק במקצת גופו, האם \u0003שמה ביאה\u0004 ונחשבת ככניסה לאותו מקום \u0003או לא? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בהונות\u0004 של מצורע \u0003יוכיחו;\u0004 שהרי המצורע מכניס רק את בהונותיו למקדש \u0003שהן ביאה במקצת\u0004 בלבד, \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003מצורע טובל ועומד בשער ניקנור,\u0004 משמע שצריך טבילה אפילו לביאה במקצת. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003מהו שיעשה\u0004 הטמא \u0003סכין ארוכה\u0004 מאד \u0003וישחוט\u0004 בה את הקרבן בעזרה, כשהוא עצמו עומד חוץ לעזרה? האם עצם העבודה מצריכה טבילה, או רק הכניסה לעזרה?","ומעירים: \u0003תיבעי\u0004 \u0005[\u0006שאלה זו יכולה \u0005להישאל]\u0006 \u0003ל\u0004שיטת \u0003בן זומא,\u0004 המחמיר בטבילה, \u0003תיבעי לרבנן דפליגי עליה\u0004 \u0005[תישאל\u0006 השאלה אף \u0005ל\u0006שיטת \u0005החכמים החולקים עליו]\u0006 על \u0003ר' יהודה,\u0004 שאינם מצריכים טבילה לכל אדם. ומפרטים: \u0003תיבעי\u0004 \u0005[\u0006שאלה זו \u0005תישאל]\u0006 \u0003ל\u0004שיטת \u0003בן זומא,\u0004 כי \u0003עד כאן לא\u0004 שמענו ש\u0003מחייב בן זומא\u0004 טבילה \u0003אלא\u0004 בכניסה \u0003לגואי\u0004 \u0005[לפנים]\u0006 העזרה, \u0003אבל לבראי\u0004 \u0005[ל\u0006עמידה ב\u0005חוץ]\u0006 \u0003לא\u0004 שמענו שהוא מחייב טבילה, \u0003או דילמא\u0004 \u0005[שמא]\u0006 אף במקרה כזה יש לחשוש שמא \u0003אתי לאימשוכי\u0004 \u0005[יבוא להימשך]\u0006 תוך כדי עבודתו ויכנס בלא משים פנימה.","וכן \u0003תיבעי לרבנן דפליגי עליה\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006שיטת \u0005חכמים החולקים עליו]\u0006 על \u0003ר' יהודה.\u0004 כיצד? \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 שאין צורך בטבילה, דווקא באופן שהוא \u0003לא קא עביד\u0004 \u0005[עושה]\u0006 \u0003עבודה, אבל הכא דקא עביד\u0004 \u0005[כאן ש\u0006הרי \u0005הוא עושה]\u0006 \u0003עבודה — לא\u0004 התירו בלא טבילה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[שונה],\u0006 שאדם שאינו טמא אינו צריך לטבול שוב בכל מקרה. לשאלות אלו לא נמצאה תשובה והושארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה כי \u0003חמש טבילות ועשרה קידושין טובל\u0004 הכהן ומקדש בו ביום. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חמש טבילות ועשרה קידושין טובל כהן גדול ומקדש בו ביום, וכולן\u0004 היו \u0003בקדש\u0004 בלשכת \u0003בית הפרוה, חוץ\u0004 מטבילה \u0003ראשונה שהיתה בחול על גבי שער המים, ובצד לשכתו\u0004 של הכהן הגדול \u0003היתה. אמר אביי: שמע מיניה\u0004 \u0005[למד ממנה]\u0006 מהאמור בברייתא זו כי \u0003עין עיטם\u0004 המעין שממנו היו המים באים למקדש \u0003גבוה מקרקע עזרה עשרים ושלש אמות.\u0004 כיצד?","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003כל הפתחים שהיו שם\u0004 במקדש \u0003גובהן עשרים אמה ורחבן עשר אמות, חוץ מ\u0004פתחו \u0003של אולם\u0004 שהיה כפול, שגובהו ארבעים ורחבו עשרים. \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר: \u0003\"ורחץ בשרו במים\"\u0004 (ויקרא טו, יג), וכן: \"ורחץ במים את כל בשרו\" (ויקרא טו, טז), כוונתו במים הידועים — \u0003במי מקוה,\u0004 והדגשת הכתוב באומרו \u0003\"כל בשרו\"\u0004 — לומר שצריך לטבול \u0003במים שכל גופו עולה\u0004 (שוקע) \u0003בהן\u0004 בבת אחת. \u0003וכמה הן\u0004 מים אלה, מאי כמותם? — \u0003אמה על אמה ברום\u0004 (בגובה) \u0003שלש אמות\u0004 שאם טובל בהם יעלו המים ויכסו את כל קומתו, \u0003ושיערו חכמים\u0004 שנפח \u0003מי מקוה\u0004 הוא \u0003ארבעים סאה\u0004 שהיא כמות המים שיכולה להכנס בתוך חלל כזה. וכיון שגובה השער עשרים אמה וגובה בית הטבילה שעליו לפחות שלוש אמות נוספות, כדין מקוה, נמצא כי בסך הכל היו המים צריכים לעלות לפחות עשרים ושלוש אמות מקרקע העזרה."],["ומקשים: כיצד אומר אתה רק עשרים ושלוש אמות \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 מעל לחלל השער גם \u0003אמה\u0004 עובי של \u0003תקרה\u0004 של עץ \u0003ואמה מעזיבה\u0004 העשויה מטיח וטיט לסתום יפה את החרכים שבמבנה, הרי שהיו שם לפחות עשרים וחמש אמה! ומשיבים: \u0003שערים\u0004 של \u0003בית המקדש, כיון דשישא נינהו\u0004 \u0005[שמשל\u0006 אבן \u0005שיש היו],\u0006 \u0003במשהו עביד להו\u0004 \u0005[היו עושים אותם],\u0006 כלומר: לא היו צריכין לעשות מעל האבן תקרה ומעזיבה עבים כל כך, ואפשר היה לעשותם דקים מאד. ומקשים: \u0003והא איכא האיך\u0004 \u0005[והרי יש\u0006 על כל פנים \u0005אותו]\u0006 \u0003משהו\u0004 של תקרה ומעזיבה והרי זה יותר מעשרים ושלוש אמות! ומשיבים: אכן ודאי כך היה, אלא \u0003כיון\u0004 ש\u0003לא הואי אמתא\u0004 \u0005[היתה\u0006 התקרה \u0005אמה\u0006 שלימה\u0005]\u0006 \u0003לא חשיב לה\u0004 \u0005[מונה אותה].\u0006","שנינו במשנה כי היו פורסים מסביב לכהן בשעת טבילתו \u0003סדין של בוץ\u0004 (פשתן) לצניעות. ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מדוע דווקא\u0005]\u0006 \u0003של בוץ?\u0004 ומשיבים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב כהנא\u0004 בענין דומה: \u0003כדי שיכיר\u0004 וישים אל לבו ש\u0003עבודת היום\u0004 המיוחדת ליום הכיפורים \u0003בבגדי בוץ\u0004 הם. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 עשו סדין של בוץ כדי \u0003שיכיר שעבודת היום בבגדי בוץ.\u0004","\u0003פשט\u0004 הכהן הגדול בגדי הלבן שהיו עליו \u0003ירד\u0004 למקוה \u0003וטבל, עלה ונסתפג\u0004 (התנגב במגבת כדי לספוג את הלחות מעליו). לאחר מכן \u0003הביאו לו בגדי זהב,\u0004 שמונה בגדים של כהן גדול \u0003ולבש\u0004 אותם, \u0003וקידש\u0004 (רחץ) \u0003ידיו ורגליו. הביאו לו את\u0004 כבש \u0003התמיד\u0004 של שחר \u0003קרצו\u0004 (שחט את רוב שני הסימנים שבו) \u0003ומירק\u0004 (גמר) כהן \u0003אחר\u0004 את ה\u0003שחיטה על ידו\u0004 (בשבילו), כדי שיוכל הכהן הגדול למהר ולקבל את הדם ולהמשיך בעבודתו. ומיד בסיום השחיטה \u0003קבל\u0004 הכהן הגדול \u0003את הדם\u0004 בכלי \u0003וזרקו\u0004 על המזבח.","\u0003נכנס\u0004 לאולם כדי \u0003להקטיר קטורת של שחר, ולהיטיב את הנרות\u0004 במנורה, \u0003ולהקריב את הראש ואת האברים\u0004 של כבש התמיד \u0003והחביתין\u0004 (מנחתו המיוחדת של הכהן הגדול) \u0003ואת היין\u0004 של נסך קרבן התמיד. ומעירים: \u0003קטורת של שחר היתה קריבה בין\u0004 קבלה וזריקת \u0003הדם\u0004 ובין הקטרת ה\u0003אברים,\u0004 וקטורת \u0003של בין הערבים\u0004 היתה קריבה \u0003בין\u0004 העלאת ה\u0003אברים\u0004 למזבח להבאת ה\u0003נסכים\u0004 עליו.","ולענין טבילה \u0003אם היה כהן גדול זקן\u0004 שקשה לו לטבול בצינה \u0003או איסטניס\u0004 (חולני ומפונק) היו \u0003מחמין לו\u0004 מים \u0003חמין, ומטילין לתוך הצונן\u0004 שבמקוה \u0003כדי שתפיג\u0004 (תתמעט) \u0003צינתן\u0004 ויוכל הכהן לטבול בלא להצטער.","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים\u0006 דבר זה \u0005לפני]\u0006 \u0003רב פפא: הא\u0004 \u0005[\u0006משנתנו \u0005זו]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' מאיר. דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' מאיר\u0004 היא, \u0003כיון\u0004 ש\u0003אמר\u0004 ר' מאיר \u0003תרי קידושי אלבישה עביד להו\u0004 \u0005[שני הקידושים\u0006 שמקדש ידיו ורגליו \u0005—\u0006 \u0005על לבישת\u0006 הבגדים בכל פעם, הוא \u0005שעושה אותם],\u0006 פעם לפני לבישתם, ופעם שניה לאחר לבישה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003ליעביד תרי קידושי\u0004 \u0005[\u0006צריך \u0005לעשות שני קידושים]\u0006 על ה\u0003לבישה\u0004 ומלשון המשנה משמע כי פושט את בגדיו ואינו מקדש ידיו ורגליו!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא\u0004 לחכמים: \u0003בין\u0004 לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003בין\u0004 לשיטת \u0003ר' מאיר חד\u0004 \u0005[\u0006קידוש \u0005אחד]\u0006 עושים על \u0003פשיטה\u0004 של \u0003בגדי קודש, וחד\u0004 \u0005[ו\u0006קידוש \u0005אחד]\u0006 על ה\u0003לבישה\u0004 של בגד קודש אחר. \u0003והכא בהא קא מיפלגי\u0004 \u0005[וכאן ב\u0006עקרון \u0005זה נחלקו]:\u0006 נאמר: \u0003\"ופשט\u0004 את בגדי הבד אשר לבש בבואו אל הקודש והניחם שם \u0003ורחץ\u0004 את בשרו במים במקום קדוש \u0003ולבש\u0004 את בגדיו\u0003\"\u0004 (ויקרא טז, כג-כד). \u0003ר' מאיר סבר:\u0004 כי \u0003מקיש\u0004 \u0005[משוה]\u0006 הכתוב קידוש שבשעת \u0003פשיטה\u0004 לקידוש בשעת \u0003לבישה, מה\u0004 קידוש בשעת \u0003לבישה —\u0004 ראשית \u0003לובש ואחר כך מקדש\u0004 ידיו ורגליו, \u0003אף פשיטה — פושט ואחר כך מקדש.\u0004","\u0003ורבנן סברי\u0004 \u0005[סבורים]:\u0006 כי \u0003מקיש\u0004 \u0005[משוה]\u0006 \u0003פשיטה ללבישה, מה לבישה — כשהוא לבוש\u0004 כבר \u0003מקדש, אף פשיטה — כשהוא\u0004 עדיין \u0003לבוש מקדש,\u0004 ולכן אחר שהוא מסיים את העבודה הריהו מקדש את ידיו, ואחר כך פושט בגדיו. אולם בלבישת בגדי הקודש לראשונה, כיון שאינו פושט בגדי קודש — ודאי שאיננו צריך שני קידושים.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב פפא: וכי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כן]\u0006 שלדעת ר' מאיר אין צורך בשתי קידושים ללבישה ראשונה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פרסו סדין של בוץ בינו לבין העם, ופשט וירד וטבל עלה ונסתפג, הביאו לו בגדי זהב ולבש וקידש ידיו ורגליו.\u0004 ואילו \u0003ר' מאיר אומר: פשט וקידש ידיו ורגליו, וירד וטבל, עלה ונסתפג, הביאו לו בגדי זהב, ולבש וקידש ידיו ורגליו.\u0004 הרי מפורש שר' מאיר אומר שיש צורך בקידוש מיוחד טרם לבישת הבגדים! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי תניא תניא\u0004 \u0005[אם שנויה\u0006 ברייתא כזו \u0005—\u0006 \u0005שנויה\u0006 היא\u0005],\u0006 שכל מה שאמרתי מסברה אמרתי, אבל אם אכן שנינו במפורש שלא כשיטתי, חייב אני לחזור בי.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 על פי שיטת \u0003ר' מאיר, היינו דמשכחת לה\u0004 \u0005[כך הוא שאתה מוצא אותה\u0006 אפשרות\u0005]\u0006"],["\u0003עשרה קידושין,\u0004 שלשיטתו על כל טבילה יש צורך בשני קידושים. \u0003אלא\u0004 לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שאינם מצריכים קידוש בתחילה, אם כן \u0003תשעה\u0004 קידושים בלבד \u0003הוו\u0004 \u0005[היו]!\u0006 ומשיבים: \u0003אמרי לך רבנן\u0004 \u0005[\u0006היו יכולים \u0005חכמים לומר לך]:\u0006 \u0003קידושא בתרא\u0004 \u0005[הרחיצה האחרונה],\u0006 \u0003כי פשיט\u0004 \u0005[כאשר\u0006 היה \u0005פושט]\u0006 את \u0003בגדי\u0004 ה\u0003קדש ולביש\u0004 \u0005[ולובש]\u0006 את \u0003בגדי\u0004 ה\u0003חול, עביד ליה התם\u0004 \u0005[היה עושה אותה שם],\u0006 שלדעתם כשהוא פושט את בגדי הקודש צריך הוא לקדש, ואילו ר' מאיר סבור שרק לפני לבישה עליו לקדש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"ובא אהרן אל אהל מועד\"\u0004 (ויקרא טז, כג) \u0003למה הוא בא?\u0004 הרי כבר סיים עבודתו בהיכל! \u0003אינו בא אלא להוציא את הכף ואת המחתה\u0004 שהיו בקודש הקדשים. \u0003שכל הפרשה כולה\u0004 של עבודת יום הכפורים \u0003נאמרה\u0004 בתורה \u0003על הסדר\u0004 כדרך שעושים אותה במקדש, \u0003חוץ מפסוק זה\u0004 שלא נאמר כסדרו והיה צריך להיכתב לאחר הקרבת קרבן העולה (ויקרא טז, כד), כי הוצאת הכף אינה נעשית מיד אחר הכנסתה, אלא מפסיק באמצע בעבודות חוץ, ומחליף שוב את בגדיו. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מדוע אכן צריך היה להפסיק בין עבודת היום להוצאת הכף והמחתה בענין הקרבת אילו ואיל העם, שלא כסדר הנכון?","\u0003אמר רב חסדא: גמירי\u0004 \u0005[למודים\u0006 היו\u0005]\u0006 מפי המסורת כי \u0003חמש טבילות ועשרה קידושין טובל כהן גדול ומקדש בו ביום. ואי\u0004 \u0005[ואם]\u0006 \u0003כסדרן\u0004 של הפסוקים נעשות העבודות אם כן \u0003לא משכחת להו\u0004 \u0005[אין אתה מוצא]\u0006 \u0003אלא שלש טבילות וששה קידושין,\u0004 טבילה אחת להקרבת תמיד של שחר ואחת בין התמיד ושאר עבודת היום, כולל הוצאת הכף והמחתה מקודש הקדשים, ואחת נוספת בין הוצאת הכף והמחתה מקודגש הקדשים לעשיית אילו ואיל העם והקרבת המוספים ותמיד של בין הערבים שבא לאחרים. ואילו על ידי שינוי הסדר, שלאחר שהכניס הכהן את המחתה לקודש הקדשים היה צריך לעבוד עבודה אחרת בחוץ, ואחר כך לחזור לקודש הקדשים כדי להוציא את הכף, ושוב לצאת וללבוש לצרכה בגדים אחרים, הרי שיש צורך בחמש טבילות.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יהודה: מנין לחמש טבילות ועשרה קידושין שטובל כהן גדול ומקדש בו ביום? תלמוד לומר: \"ובא אהרן אל אהל מועד ופשט את בגדי הבד\u0004 אשר לבש בבואו אל הקודש והניחם שם \u0003ורחץ\u0004 את \u0003בשרו במים במקום קדוש ולבש את בגדיו ויצא ועשה\u0004 את עולתו ואת עולת העם\u0003\"\u0004 (ויקרא טז, כג-כד), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 \u0005[הרי]\u0006 מכתוב זה \u0003שכל המשנה מעבודה לעבודה\u0004 מעבודת פנים בקודש הקדשים לעבודת חוץ \u0003טעון טבילה,\u0004 ולפי סדר העבודות חמש טבילות הן.","\u0003אמר רבי: מנין לחמש טבילות ועשרה קידושין שטובל כהן גדול ומקדש בו ביום — שנאמר: \"כתנת בד קדש ילבש ומכנסי בד יהיו על בשרו ובאבנט בד יחגר ובמצנפת בד יצנף בגדי קדש הם ורחץ במים את בשרו ולבשם\"\u0004 (ויקרא טז, ד), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכתוב זה \u0003שכל המשנה מעבודה\u0004 הנעשית בפנים \u0003לעבודה\u0004 הנעשיץ בחוץ — \u0003טעון טבילה. ואומר\u0004 כתוב זה: \u0003\"בגדי קדש הם\",\u0004 ללמד כי \u0003הוקשו\u0004 (הושוו) \u0003כל הבגדים כולן זה לזה,\u0004 שכשם שטובל לבגדי לבן כך טובל הוא לבגדי זהב.","\u0003וחמש עבודות הן:\u0004 הקרבת \u0003תמיד של שחר\u0004 נעשית \u0003בבגדי זהב, עבודת היום\u0004 בפר ובשעיר שלאחר מכן נעשית \u0003בבגדי לבן,\u0004 ואחר מקריב את \u0003אילו\u0004 איל האשם ואת \u0003איל העם בבגדי זהב,\u0004 לאחר מכן הריהו מכניס לקודש הקדשים \u0003כף ומחתה בבגדי לבן,\u0004 ויוצא ומקריב \u0003תמיד של בין הערבים בבגדי זהב,\u0004 ומוציא את הכף בבגדי לבן.","\u0003ומנין שכל טבילה וטבילה צריכה שני קידושין\u0004 (רחיצת ידים ורגלים)? \u0003תלמוד לומר: \"ובא אהרן אל אהל מועד ופשט את בגדי הבד\u0004 אשר לבש בבואו אל הקודש והניחם שם \u0003ורחץ\u0004 את \u0003בשרו במים\"\u0004 (ויקרא טז, כג-כד) וכן נאמר: \u0003\"ורחץ\u0004 את בשרו במים במקום קדוש \u0003ולבש\u0004 את בגדיו\u0003\"\u0004 (ויקרא טז, כד), הרי לך רחיצה לפשיטה ורחיצה ללבישה.","\u0003ר' אלעזר בר' שמעון אומר: קל וחומר\u0004 הוא; \u0003ומה במקום שאין טעון טבילה,\u0004 שמן התורה אין הכהן צריך לטבול לפני שנכנס לעבוד עבודה במקדש, אולם בכל זאת \u0003טעון קידוש\u0004 ידים ורגלים לפני העבודה, \u0003מקום\u0004 (יום הכיפורים) \u0003שטעון טבילה\u0004 לכל החלפת בגדים, \u0003אינו דין שטעון\u0004 אף \u0003קידוש.\u0004","אולם קל וחומר זה ניתן להדחות: \u0003אי\u0004 \u0005[או]\u0006 אולי תאמר \u0003מה להלן,\u0004 לפני שאר עבודות במקדש צריך רק \u0003קידוש אחד, אף כאן\u0004 בעבודת היום אין צריך אלא \u0003קידוש אחד\u0004 בלבד? \u0003תלמוד לומר: \"ובא אהרן אל אהל מועד ופשט את בגדי הבד אשר לבש\"\u0004 (ויקרא טז, כג), \u0003מה תלמוד לומר: \"אשר לבש\"\u0004 והרי אין מילים אלה מלמדות אותנו מאומה, כי \u0003כלום אדם פושט\u0004 תמיד \u0003אלא מה שלבש! אלא\u0004 מילים יתירות אלה באו ללמדנו כי יש \u0003להקיש\u0004 (להשוות) \u0003פשיטה ללבישה,\u0004 ולומר: \u0003מה\u0004 לצורך \u0003לבישה טעון קידוש — אף\u0004 לצורך \u0003פשיטה טעון קידוש.\u0004 ומעתה באים לברר את שיטת ר' יהודה שהוזכרה קודם.","\u0003אמר ר' יהודה: מנין לחמש טבילות ועשרה קידושין שטובל כהן גדול ומקדש בו ביום תלמוד לומר: \"ובא אהרן אל אהל מועד\u0004 ופשט את בגדי הבד אשר לבש בבואו אל הקודש והניחם שם \u0003ורחץ את בשרו במים במקום קדוש\"\u0004 (ויקרא טז, כג-כד), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן \u0003שכל המשנה מעבודה\u0004 הנעשית בפנים \u0003לעבודה\u0004 הנעשית בחוץ — \u0003טעון טבילה.\u0004 ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 ראיה מכאן\u0005]\u0006 שכאשר משנה הכהן \u0003מבגדי לבן לבגדי זהב\u0004 טעון הוא טבילה, אולם כשמשנה \u0003מבגדי זהב לבגדי לבן מנין\u0004 שאף לכך טעון טבילה?"],["\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: קל וחומר\u0004 הוא; \u0003ומה בגדי זהב שאין כהן נכנס בהן לפני ולפנים\u0004 לקודש הקדשים — \u0003טעון טבילה\u0004 לפני לבישתן, \u0003בגדי לבן שנכנס בהן לפני ולפנים אינו דין שטעון טבילה.\u0004 ומקשים: \u0003איכא למפרך\u0004 \u0005[יש מקום לפרוך,\u0006 לשבור\u0005]\u0006 את הקל וחומר, ולומר: \u0003מה לבגדי זהב — שכן כפרתן מרובה\u0004 שהכהן הגדול עובד בהם ומכפר בהם על ישראל כל השנה כולה, ואילו בגדי לבן משמשים רק ליום הכפורים אחד בלבד, ולכך יתכן שלא יצטרך טבילה לצורך לבישתם! \u0003אלא, נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר\u0005]\u0006 מה שאמר \u0003רבי\u0004 שיש ללמוד זאת מלשון הפסוק כאמור.","ומסבירים קטע נוסף בברייתא שהובאה לעיל: \u0003אמר רבי: מנין לחמש טבילות ועשרה קידושין שטובל כהן גדול ומקדש בו ביום — תלמוד לומר: \"כתנת בד קדש ילבש\u0004 ומכנסי בד יהיו על בשרו ובאבנט בד יחגור ובמצנפת בד יצנוף בגדי קודש הם ורחץ במים את בשרו ולבשם\" \u0005(ויקרא טז, ד)\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת שכל המשנה מעבודה לעבודה\u0004 שהוא \u0003טעון טבילה.\u0004 ומעירים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 למדנו איפוא\u0005]\u0006 כי \u0003מבגדי זהב לבגדי לבן\u0004 טעון טבילה, \u0003מבגדי לבן לבגדי זהב מנין\u0004 שטעון טבילה?","\u0003תנא דבי\u0004 \u0005[שנה,\u0006 חכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: קל וחומר; מה בגדי לבן שאין כפרתן מרובה\u0004 שהרי אין הכהן לובשם אלא ביום הכיפורים של שנה אחת בלבד, \u0003טעונין טבילה\u0004 לפני לבישתם, \u0003בגדי זהב שכפרתן מרובה\u0004 בעבודתו בכל ימות השנה, \u0003אינו דין שטעונין טבילה?\u0004","ומקשים: הלא \u0003איכא למפרך\u0004 \u0005[יש מקום לפרוך,\u0006 לשבור\u0005]\u0006 את ההוכחה, ולומר: \u0003מה לבגדי לבן שכן נכנס בהן לפני ולפנים,\u0004 מה שאין כן בבגדי זהב, הרי שקדושת בגדי לבן גדולה משל בגדי זהב! ומעירים: \u0003היינו דקתני\u0004 \u0005[זהו ששנינו]\u0006 בהמשך אותה ברייתא, דברים שהם כתשובה לשאלה זו; \u0003ואומר: \"בגדי קדש הם ורחץ את בשרו במים ולבשם\"\u0004 (ויקרא טז, ד), שמפני קושי זה, הביאו את הכתוב הנוסף להדגיש שיש חובת רחיצה גם לבגדי קודש אחרים.","\u0003וחמש עבודות הן:\u0004 הקרבת \u0003תמיד של שחר\u0004 נעשית \u0003בבגדי זהב, עבודת היום\u0004 בפר ובשעיר שלאחר מכן נעשית \u0003בבגדי לבן,\u0004 ואחר מקריב את \u0003אילו\u0004 איל האשם ואת \u0003איל העם בבגדי זהב,\u0004 לאחר מכן הריהו מכניס לקודש הקדשים \u0003כף ומחתה בבגדי לבן,\u0004 ויוצא ומקריב \u0003תמיד של בין הערבים בבגדי זהב,\u0004 ומוציא את הכף בבגדי לבן.","\u0003ומנין שכל טבילה וטבילה\u0004 מטבילות אלה \u0003צריכה שני קידושין? תלמוד לומר: \"ופשט\u0004 את בגדי הבד אשר לבש בבואו אל הקודש והניחם שם ורחץ את בשרו במים\u0003\",\u0004 וכן: \u0003\"ורחץ\u0004 את בשרו במים במקום קדוש \u0003ולבש\u0004 את בגדיו\u0003\"\u0004 (ויקרא טז, כד). ומקשים: הלא \u0003האי\u0004 \u0005[זה]\u0006 \u0003בטבילה כתיב\u0004 \u0005[נאמר]\u0006 שהרי רחיצה זו האמורה כאן אינה רחיצת ידים (\"קידוש\") אלא משמעה טבילה! ומשיבים: \u0003אם אינו ענין לטבילה\u0004 שהרי \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד לו הדבר\u0005]\u0006 ממה שנאמר: \u0003\"בגדי קדש הם\",\u0004 שמפסוק זה למדנו שיש חובת טבילה בכל החלפת בגדים, על כן \u0003תנהו ענין לקידוש.\u0004","ושואלים: אם כן \u0003וליכתביה רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003בלשון קידוש\u0004 ידים ורגלים ולא בלשון \"ורחץ\" שמשמעה כרגיל טבילה! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 על ידי שימוש לשון זה ש\u0003טבילה כקידוש,\u0004 שיש ביניהם צד שוה \u0003—\u0004 ללמד: \u0003מה קידוש\u0004 ידים ורגלים נעשה \u0003במקום קדוש,\u0004 שהרי הכיור שממנו מקדשים מצוי בתוך העזרה, \u0003אף טבילה\u0004 זו הבאה להחלפת בגדים צריכה להיעשות \u0003במקום קדוש\u0004 ולא מחוץ למקדש.","ושואלים: \u0003ור' יהודה\u0004 הלומד מפסוק זה טבילה לבגדי זהב ואינו דורש את הפסוק \"בגדי קודש הן\" ללמד שצריך קידוש ידים ורגלים בכל החלפת בגדים, אם כן חובת \u0003קידוש מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר כדרך שלמד \u0003ר' אלעזר בר' שמעון,\u0004 שדבר זה נלמד מקל וחומר, ומה במקום שאין טעון טבילה טעון קידוש, מקום שטעון טבילה אינו דין שטעון קידוש, כאמור.","\u0003אמר רב חסדא: הא\u0004 \u0005[\u0006שיטתו \u0005זו]\u0006 של \u0003רבי\u0004 לגבי טבילה וקידוש \u0003מפקא\u0004 \u0005[מוציאה],\u0006 כלומר: אינה מקבלת לא את שיטת \u0003ר' מאיר\u0004 לענין קידוש, \u0003ומפקא מדרבנן\u0004 \u0005[ומוציאה\u0006 אף \u0005מדברי חכמים],\u0006 שהיא שיטה חדשה לעצמה. כיצד \u0003מפקא מדרבנן\u0004 \u0005[מוציאה מ\u0006שיטת \u0005חכמים]?\u0006 ש\u0003אילו רבנן אמרי\u0004 \u0005[חכמים אמרו]:\u0006 שכ \u0003שהוא לבוש מקדש, ואיהו\u0004 \u0005[והוא,\u0006 רבי\u0005]\u0006 \u0003אמר: כשהוא פושט מקדש. ומפקא\u0004 \u0005[ומוציאה\u0006 מדברי\u0005]\u0006 \u0003ר' מאיר:\u0004 ש\u0003אילו ר' מאיר אמר: הך קידוש בתרא\u0004 \u0005[קידוש אחרון זה],\u0006 כלומר, קידוש שני שהוא מקדש בכל טבילה \u0003כשהוא לבוש מקדש, ואיהו\u0004 \u0005[והוא]\u0006 רבי \u0003אמר: כשהוא פושט מקדש.\u0004","\u0003אמר רב אחא בר יעקב: הכל מודין בקידוש שני שלובש ואחר כך מקדש, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"או בגשתם אל המזבח\u0004 לשרת להקטיר אשה לה' ורחצו ידיהם ורגליהם ולא ימותו\u0003\"\u0004 (שמות ל, כ-כא), לומר: חובת רחיצה (קידוש) היא ב\u0003מי שאינו מחוסר אלא גישה,\u0004 ובכל השאר הוא מוכן לעבודה, \u0003יצא זה\u0004 כהן בלא בגדים \u0003שמחוסר\u0004 עדיין גם \u0003לבישה\u0004 וגם \u0003גישה.\u0004 הרי שקידוש הידים לפני העבודה צריך להיעשות כשהוא לבוש כבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: לא רב חסדא\u0004 שלדעתו לשיטת רבי יש לכהן לעשות את שתי הקידושים בין פשיטה ללבישה \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל את שיטת] \u0003דרב אחא,\u0004 כיון שלדעתו בשיטת רבי הקידוש נעשה לאחר הלבישה. \u0003ולא רב אחא\u0004 שלדעתו בשיטת רבי, צריך קידוש סמוך לעבודה \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל את שיטת\u0005]\u0006 \u0003רב חסדא,\u0004 שלדעתו לשיטת רבי, צריך לעשות את שני הקידושים כשהוא ערום. ש\u0003אם\u0004 תאמר \u0003כן\u0004 יצא כי לשיטת \u0003רבי הוו ליה חמיסר\u0004 \u0005[יהיו להם חמישה עשר]\u0006 \u0003קידושין,\u0004 שבכל החלפת בגדים צריך שלוש טבילות: אחד כשהוא פושט, אחד לפני לבישה, ואחד כשהוא לבוש.","נאמר במשנה: \u0003\"הביאו לו את התמיד\u0004 ו\u0003קרצו\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קרצו\"? אמר עולא: לישנא דקטלא\u0004 \u0005[לשון של הריגה]\u0006 \u0003הוא. אמר רב נחמן בר יצחק: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 ממנו למדים דבר זה — מתוך שנאמר: \u0003\"עגלה יפה-פיה מצרים קרץ מצפון בא בא\"\u0004 (ירמיה מו, כ). ושואלים: \u0003מאי משמע\u0004 \u0005[מה משמעותו]\u0006 של פסוק זה, ממנה יש ללמוד לעניננו? ומסבירים: \u0003כדמתרגם\u0004 \u0005[כפי שמתרגם]\u0006 אותו \u0003רב יוסף: מלכא יאי הוה מצרים עממין קטולין מציפונא ייתון עלה\u0004 \u0005[מלכות יפה היתה מצרים עמים רצחנים מצפון יבואו עליה],\u0006 ולמדנו מכאן כי לשון \"קרץ\" פירושו הריגה. ושואלים: \u0003קרצו\u0004 (שחטו) \u0003בכמה?\u0004 כלומר מה שיעורה של עיקר שחיטה זו על ידי הכהן? \u0003אמר עולא: ברוב שנים,\u0004 שהיה שוחט את רוב הקנה והושט (הקרויים \"סימנים\"), ודי בכך כדי להכשיר את השחיטה בצמצום.","\u0003וכן אמר ר' יוחנן: ברוב שנים. ואף ריש לקיש סבר ברוב שנים.\u0004 וההוכחה לכך שזו אכן דעתו, ממה ש\u0003אמר ריש לקיש: וכי מאחר ששנינו\u0004 בהלכות שחיטה כי \u0003רובו של\u0004 סימן \u0003אחד כמוהו.\u0004 אם כן \u0003למה שנינו\u0004 פעם שניה שם: \u0003רוב\u0004 סימן \u0003אחד בעוף ורוב שנים בבהמה\u0004 והרי דבר זה מובן מאליו לפי הכלל שבעוף צריך לשחוט סימן אחד, ובבהמה שנים. אלא, \u0003לפי ששנינו: הביאו לו את התמיד קרצו מירק\u0004 (סיים) כהן \u0003אחר\u0004 את ה\u0003שחיטה על ידו\u0004 (לצורכו), \u0003וקיבל את הדם וזרקו. יכול\u0004 אם \u0003לא מירק\u0004 הכהן האחר \u0003יהא פסול,\u0004 שאין השחיטה כשרה אלא אם כן נשחטו כל שני הסימנים.","לפני שמסיימים את הענין, תוהים על השאלה הראשונה, כיצד אפשר להעלות על הדעת כי \u0003\"יכול לא מירק יהא פסול\"\u0004 שהרי לפי זה יש הכרח בכך שישתתף כהן נוסף בעבודה, ו\u0003אם כן הויא ליה\u0004 \u0005[הרי זו]\u0006 \u0003עבודה\u0004 של קודש ביום הכפורים בכהן \u0003אחר, ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל עבודות יום הכפורים אינן כשרות אלא בו\u0004 בכהן הגדול. ומכאן שכל דבר שהוא חלק מהותי מסדר העבודה צריך להיעשות על ידי כהן גדול דווקא! על קושי זה עונים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 ברור שאין חובה מן התורה לגמור את שחיטת שני הסימנים, אולם \u0003יכול יהא פסול מדרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים],\u0006"],["\u0003לכך שנינו\u0004 פעם נוספת: \u0003רוב אחד בעוף ורוב שנים בבהמה\u0004 ללמדנו שדי בשחיטת רובם של הסימנים. ושואלים: \u0003וכי מאחר דאפילו פסולא מדרבנן ליכא\u0004 \u0005[כיון שאפילו פסול מדברי סופרים אין\u0006 בכך\u0005],\u0006 אם כן \u0003למה לי\u0004 לחייב כהן אחר \u0003למרק\u0004 (לסיים), שיסתפקו במה ששחט הכהן הגדול את רוב שני הסימנים! ומשיבים: מכל מקום \u0003מצוה\u0004 לכתחילה \u0003למרק\u0004 כדי שניתן יהיה להוציא בקלות רבה יותר את הדם.","\u0003אביי\u0004 היה \u0003מסדר מערכה,\u0004 כלומר: היה מונה את סדר העבודות בבית המקדש \u0003משמיה דגמרא\u0004 \u0005[משם\u0006 על פי, \u0005המסורת]\u0006 \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של התנא \u0003אבא שאול\u0004 בענין זה. וכך הוא הסדר: עריכת \u0003מערכה\u0004 (ערימה) \u0003גדולה\u0004 של עצים על גבי המזבח שעליה היו מקטירים את הקרבנות \u0003קודמת למערכה שניה\u0004 של עצים שהיו מסדרים לחוד סמוך לקרן מערבית דרומית של המזבח, וממנה היו חותים גחלים ומניחים אותם על גבי המזבח הפנימי פעמיים בכל יום לצורך הקטרת ה\u0003קטורת, מערכה שניה של קטורת קודמת לסידור שני גזירי עצים\u0004 מעל המערכה הגדולה כדי לקיים מצות הבאת עצים, \u0003וסידור שני גזירי עצים קודם לדישון\u0004 (להסרת הדשן) מעל ה\u0003מזבח הפנימי, ודישון מזבח הפנימי קודם להטבת\u0004 (סידור וניקוי) \u0003חמש נרות\u0004 משבעה נרות המנורה,","\u0003והטבת חמש נרות\u0004 נעשית \u0003קודם\u0004 לשחיטה קבלה וזריקת \u0003דם התמיד\u0004 של שחר, והזאת \u0003דם התמיד קודם להטבת שתי נרות\u0004 נוספים שהיו במנורה, \u0003והטבת שתי נרות קודם\u0004 להקטרת ה\u0003קטורת,\u0004 והקטרת ה\u0003קטורת\u0004 על גבי המזבח הפנימי \u0003קודם\u0004 להקטרת ה\u0003אברים\u0004 של קרבן התמיד על גבי המזבח החיצון, והקטרת \u0003האברים\u0004 קודמת להקרבת ה\u0003מנחה\u0004 השייכת לקרבן התמיד, והקרבת ה\u0003מנחה\u0004 קודמת להקרבת ה\u0003חביתין\u0004 (קרבן מנחה מיוחד שמביא הכהן הגדול, מחציתו בבקר ומחציתו בערב) \u0003וחביתין\u0004 קודמים להבאת \u0003נסכין\u0004 של התמיד,","\u0003ונסכין\u0004 של התמיד קודמים להקרבת \u0003מוספין, ומוספין\u0004 ביום שמקריבים בו קרבנות מוספים קודמים \u0003לבזיכין\u0004 של לבונה שמקריבים ביום השבת, \u0003ובזיכין\u0004 קודמים לסדר הקרבת \u0003תמיד של בין הערבים, שנאמר: \"\u0004וערך עליה העולה \u0003והקטיר עליה חלבי\u0004 ה\u0003שלמים\"\u0004 (ויקרא ו, ה) ומרמז הכתוב כי \u0003עליה,\u0004 כלומר: על עולת התמיד של שחר, \u0003השלם כל הקרבנות כולן\u0004 ולא על של בין הערבים, שבכל מקרה קרבן תמיד של בין הערבים הוא האחרון להקרבה.","לאחר רשימה זו של סדרי העבודה, באים לברר את פרטי הדברים ולמצוא את מקורותיהם במקרא ובסברה. \u0003אמר מר\u0004 \u0005[החכם,\u0006 אביי\u0005]:\u0006 \u0003מערכה גדולה קודמת למערכה שניה של קטורת.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"היא העלה על מוקדה על המזבח כל הלילה\"\u0004 (ויקרא ו, ב) — \u0003זו מערכה גדולה,\u0004 שלשון \"מוקדה\" משמעה — מדורה. \u0003\"ואש המזבח תוקד בו\"\u0004 (ויקרא ו, ב) — \u0003זו מערכה שניה\u0004 עצים סמוך לקרן המזבח שהיא לצורך ה\u0003קטורת.\u0004","ומקשים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 שראשונה תהא מערכת הקטורת ושניה לה מערכה גדולה! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003מערכה גדולה עדיפא\u0004 \u0005[עדיף]\u0006 וראוי להקדימה, \u0003שכן כפרתה מרובה\u0004 שהרי עליה מקטירים את כל הקרבנות המרובים, ולא קטורת בלבד.","ודוחים: \u0003אדרבא, מערכה שניה עדיפא שכן מכניסין ממנה\u0004 גחלים \u0003לפנים\u0004 לתוך ההיכל, מה שאין כן מערכה גדולה שאינה אלא לצורך הקטרת קרבנות שבחוץ. ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 הנימוק של \u0003כפרתה מרובה עדיפא\u0004 \u0005[עדיף],\u0006 וראוי להקדימה משום כך. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר: \u0003אי לא משכח\u0004 \u0005[אם לא מוצא]\u0006 \u0003עצים למערכה שניה — מי לא מעייל\u0004 \u0005[האם לא יכניס]\u0006 לקטורת \u0003ממערכה גדולה\u0004 שהרי הבאת הגחלים לקטורת דווקא ממערכה זו אינה חובה מהותית, ונמצא שמערכה שניה היא רק כתוספת למערכה העיקרית, שעליה כל הקרבנות.","שנינו עוד בדברי אביי כי \u0003מערכה שניה של קטורת קודמת לסידור שני גזירי עצים.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה? — שנאמר: \u0003\"ובער עליה הכהן עצים בבקר בבקר\"\u0004 (ויקרא ו, ה), ומכאן למדנו שיש מצוה להניח עצים חדשים על המערכה הגדולה (\"עליה\"). ומה שאמר לשון \u0003\"עליה\"\u0004 הוא להדגיש ולומר כי רק עליה, על המערכה הגדולה \u0003ולא על חברתה\u0004 המערכה השניה שלצורך הקטורת. אולם מתוך שיש צורך במיעוט כזה \u0003מכלל דאיתא\u0004 \u0005[מכאן\u0006 יש להבין כי \u0005יש]\u0006 גם את \u0003חברתה,\u0004 שכבר מצויות על המזבח שתי מערכות עצים, ואם כן משמע שהבאת שני גזירי עצים צריכה להיות לאחר הקמת מערכה שניה.","ומקשים: \u0003והאי\u0004 \u0005[וזו]\u0006 \u0003\"עליה\"\u0004 הרי \u0003מיבעי ליה לגופיה\u0004 \u0005[נצרך לו לגופו]\u0006 של דין זה, לומר שמניחים את הגזירים על המערכת! ומשיבים: \u0003תרי\u0004 \u0005[שתי\u0006 פעמים\u0005]\u0006 \u0003\"עליה\" כתיבי\u0004 \u0005[כתוב]\u0006 \"וביער עליה\" \"וערך עליה\" (ויקרא ו, ה), אחד לגופו ואחד להדגשה.","עוד שנינו בדברי אביי כי \u0003\"סידור שני גזירי עצים קודם לדישון מזבח הפנימי\". אף על גב דהכא כתיב\u0004 \u0005[אף על פי שכאן נאמר]\u0006 בסידור שני גזירי עצים \u0003\"בבקר בבקר\"\u0004 שמשמעו שיש להשכים ולעשות זאת בשעה מוקדמת בבוקר, \u0003והכא כתיב\u0004 \u0005[וכאן,\u0006 בדישון מזבח הפנימי, \u0005כתוב\u0006 גם כן\u0005]\u0006 \u0003\"בבקר בבקר\"\u0004 (שמות ל, ז), \u0003אפילו הכי\u0004 \u0005[כך]\u0006 עבודה שהיא עשויה להקדים ולהיות \u0003מכשיר\u0004 לעבודה אחרת \u0003עדיף,\u0004 ולכן סידור העצים שהם ה\"מכשירים\", שהרי בהם משתמשים להכנת הגחלים לקטורת, צריכים להיות לפני דישון המזבח הפנימי. ושואלים: \u0003מכשיר מאי ניהו\u0004 \u0005[מה הוא] —\u0006 \u0003שני גזירי עצים, והא אמרת\u0004 \u0005[והרי אומר אתה]\u0006 כי \u0003שני גזירי עצים למערכה גדולה אזלי\u0004 \u0005[הולכים]\u0006 ולא למערכת הקטורת, ואם כן אין בגזירים אלה כלל משום מכשירי הקטורת!","\u0003אמר רבי ירמיה: שום עצים.\u0004 שאמנם שני הגזירים האלו אינם מכשירים של הקטורת, אבל כיון שעצים בכלל נחוצים לקטורת, הרי שני הגזירים נכללים בכלל עצים (\"שם עצים\") וראויים הם משום כך להקדימם. \u0003רבינא אמר\u0004 טעם אחר: \u0003הואיל והתחיל\u0004 בעבודה של סידור ה\u0003מערכה — גומר,\u0004 ובכלל זה גם סידור שני גזירי העצים, ולאחר מכן פונה לעבודה אחרת. \u0003רב אשי אמר: אי לא משכח\u0004 \u0005[אם לא\u0006 היה \u0005מוצא]\u0006 \u0003עצים למערכה שניה\u0004 עבור הקטורת \u0003מי לא מעייל\u0004 \u0005[האם לא\u0006 היה \u0005מכניס]\u0006 לשם כך עצים \u0003ממערכה גדולה?\u0004 ואם כן אף שני הגזירים עשויים להיות במקרה מסויים מכשירי קטורת, ולכן עבודה זו קודמת.","שנינו עוד בדברי אביי כי \u0003\"ודישון מזבח הפנימי קודם להטבת חמש נרות\" מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של דבר? \u0003אמר אביי: גמרא גמירנא\u0004 \u0005[מסורת למדתי]\u0006 שכן הוא, אולם \u0003סברא\u0004 לכך \u0005—\u0006 \u0003לא ידענא\u0004 \u0005[איני יודע].\u0006 \u0003ורבא אמר:\u0004 הטעם הוא על פי דברי \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש: אין מעבירין על המצו‍ת\u0004 שמי שנזדמנה לידו מצוה שיש לעשותה, אסור לו לעזוב אותה ולעסוק במצוה אחרת,"],["\u0003וכי עייל\u0004 \u0005[וכאשר\u0006 הוא \u0005נכנס]\u0006 \u0003להיכל — במזבח פגע ברישא\u0004 \u0005[הוא פוגש תחילה]\u0006 לפני שהוא מגיע למנורה, ולכן עושה הוא את מצות המזבח קודם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ה\u0003שלחן\u0004 נמצא בצד \u0003צפון\u0004 של ההיכל, \u0003משוך\u0004 (מרוחק) \u0003מן הכותל שתי אמות ומחצה, ומנורה\u0004 נמצאת \u0003בדרום, משוכה מן הכותל שתי אמות ומחצה. מזבח ממוצע ועומד באמצע\u0004 ההיכל \u0003ומשוך כלפי חוץ קימעא\u0004 (מעט). ונמצא שבו פוגשים תחילה. לגוף הענין שואלים: \u0003ונוקמיה\u0004 \u0005[ונעמיד אותו],\u0006 את המזבח, \u0003להדייהו\u0004 \u0005[יחד עמם]\u0006 עם השלחן והמנורה בשורה אחת, ומדוע הוא משוך כלפי חוץ? ומשיבים: \u0003כיון דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת המנרה נכח השלחן\"\u0004 (שמות כו, לה), \u0003בעינן דחזו אהדדי\u0004 \u0005[צריכים אנו שיראו זה את זה],\u0006 ולכן אין מעמידים את המזבח בדיוק ביניהם כדי לא לחצוץ ביניהם.","\u0003אמר רבא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מדברי \u0003ריש לקיש\u0004 שאין מעבירין על המצוות, כי \u0003עבורי דרעא אטוטפתא\u0004 \u0005[לעבור\u0006 לדלג על תפילין \u0005של יד\u0006 כדי להניח \u0005תפילין של ראש]\u0006 \u0003אסור,\u0004 שהרי בשעת הנחתן הוא מגיע לזרוע תחילה. \u0003היכי עביד\u0004 \u0005[היאך הוא עושה]? —\u0006 \u0003מדרעא לטוטפתא\u0004 \u0005[\u0006מקדים בהנחת תפילין \u0005של יד\u0006 ואחר כך עובר לתפילין \u0005של ראש].\u0006","עוד שנה אביי כי \u0003\"הטבת חמש נרות קודם לדם התמיד ודם התמיד קודם להטבת שתי נרות\".\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר אביי: ההוא\u0004 (אותו) \u0003\"בבקר בבקר\"\u0004 שנאמרו \u0003בשני גזירי עצים דלא צריכי\u0004 \u0005[שאינם נצרכים]\u0006 לקביעת זמן סידורם לעצמו, שהרי כפי שכבר הובהר, מקדימים את הנחת שני גזירי העצים משום שהם שייכים לעבודת המערכה, ולכך \u0003שדינהו להכא\u0004 \u0005[הטל,\u0006 שים, מילים יתירות אלו \u0005לכאן],\u0006 לענין עבודות אחרות של בוקר, שאם אינו ענין ללמוד ממנו דבר אחד תנהו ענין ללמוד ממנו דבר אחר, ואם כן, \u0003חד שדייה\u0004 \u0005[\u0006\"בבוקר\" \u0005אחד הטל אותו]\u0006 לענין \u0003הטבת חמש נרות דליקדמי\u0004 \u0005[שיקדמו]\u0006 \u0003לדם התמיד, וחד שדייה\u0004 \u0005[ואחד הטל אותו]\u0006 \u0003לדם התמיד — דנקדמיה\u0004 \u0005[להקדימו]\u0006 \u0003להטבת שתי נרות.\u0004","ומפרטים: \u0003חד שדייה\u0004 \u0005[אחד הטל אותו]\u0006 \u0003להטבת חמש נרות — דליקדמי לדם התמיד\u0004 ועל ידי כך יש \u0003הכא תלתא\u0004 \u0005[כאן שלוש]\u0006 \"בבוקר\" שנים הכתובים במפורש בהטבת הנרות (שמות ל, ז) ואחד שהוספנו מן הכתוב בגזירי העצים. \u0003והכא\u0004 \u0005[וכאן]\u0006 בדם התמיד \u0003תרי\u0004 \u0005[שתים],\u0006 אחד הכתוב בו במפורש (שמות כט, לט) ואחד הנוסף מגזירי העצים.","\u0003וחד שדייה לדם התמיד\u0004 \u0005[ואחד הטל,\u0006 הוסף \u0005אותו]\u0006 על דם התמיד, \u0003דנקדמיה\u0004 \u0005[שיקדם]\u0006 \u0003להטבת שתי נרות. אף על גב דהכא תרי והכא תרי\u0004 \u0005[אף על פי שכאן שנים וכאן שנים]\u0006 שנאמרו פעמיים לשון \"בבוקר\" בהטבת הנרות (שמות ל, ז) ואם מוסיפים \"בבוקר\" אחד לתמיד נמצא כאילו בשניהם נאמר \"בבוקר בבוקר\", מכל מקום דם התמיד שבזריקתו הוא \u0003מכפר,\u0004 לכך הריהו \u0003עדיף\u0004 ויש להקדימו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ואימא\u0004 \u0005[ואמור]\u0006 לא כן, אלא: \u0003חד\u0004 \u0005[אחד]\u0006 מהכתובים \"בבוקר\" \u0003שדייה\u0004 \u0005[הטל,\u0006 הוסף, \u0005אותו]\u0006 למצוות \u0003דישון מזבח הפנימי, דנקדמיה\u0004 \u0005[שיקדם]\u0006 \u0003לדם התמיד, דהכא תלתא והכא תרי\u0004 \u0005[שכאן שלושה וכאן שנים],\u0006 \u0003וחד שדייה\u0004 \u0005[ואחד הטל,\u0006 הוסף \u0005אותו]\u0006 \u0003לדם התמיד דנקדום\u0004 \u0005[שיקדם]\u0006 \u0003להטבת חמש נרות\u0004 ותאמר, כפי שאמרנו, ש\u0003אף על גב דהכא תרי והכא תרי\u0004 \u0005[אף על פי שכאן שנים\u0006 \"בבוקר בבוקר\" \u0005וכאן שנים\u0006 \"בבוקר בבוקר\"\u0005],\u0006 מכל מקום דם שהתמיד שהוא \u0003מכפר עדיף\u0004 וראוי להקדימו! את הקושיה הזאת דחה אביי באומרו: \u0003אם כן אפסוקי במאי מפסקת להו\u0004 \u0005[במה מפסיק אתה אותם]\u0006 בין הטבת חמש להטבת שתי נרות?","\u0003הניחא\u0004 \u0005[זה נוח ומובן]\u0006 לדעת \u0003ריש לקיש\u0004 ש\u0003אמר: למה מטיבין וחוזרין ומטיבין\u0004 את המנורה, ואין מטיבים בבת אחת את כל שבעת הנרות — \u0003כדי להרגיש\u0004 (להרעיש) את \u0003כל העזרה כולה\u0004 שאנשים נכנסים ויוצאים לקיים מצוה זו בטכס גדול, לשיטה זו אכן \u0003שפיר\u0004 \u0005[יפה],\u0006 שהרי לא משמע מדבריו כי היתה נעשית עבודה כלשהי בין הטבת הנרות הראשונה לשניה,","\u0003אלא\u0004 לשיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי מה שנאמר בקטורת \u0003\"בבקר בבקר\",\u0004 פירושו — \u0003חלקהו לשני בקרים,\u0004 כלומר: חלק את עבודת הטבת הנרות לשני חלקים על ידי עבודה אחרת שתעשה ביניהן, ולשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי אין עבודה באמצע ואם כן בהכרח יש לפרש כדברי אביי הראשונים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 לעיקרם של דברי אביי, \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"בבקר בבקר\"\u0004 שנאמר בגזירי \u0003עצים, מי מייתר\u0004 \u0005[האם מיותר\u0006 הוא\u0005]\u0006 שניתן ללמוד ממילים אלה לענינים אחרים? \u0003הא מיבעי ליה לגופיה\u0004 \u0005[הרי נחוץ הוא לגופו],\u0006 \u0003דקאמר רחמנא\u0004 \u0005[שאמרה תורה]\u0006 \"בבוקר בבוקר\" — שעל ידי כך \u0003נקדמו\u0004 \u0005[שיקדימו\u0006 בסידורם\u0005]\u0006 \u0003למערכה שניה של קטורת! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולאו מי אוקימנא\u0004 \u0005[האם לא העמדנו,\u0006 הסברנו כבר\u0005]\u0006 שנאמר \u0003\"עליה\"\u0004 בהבערת העצים להדגיש עליה \u0003ולא על חברתה, מכלל דאיתה\u0004 \u0005[מכאן שיש]\u0006 כבר \u0003לחברתה —\u0004 המערכה השניה של הקטורת \u0005—\u0006 במקומה עוד טרם סידור שני גזירי העצים הללו.","ומוסיפים לשאול בדין הטבת הנרות, גם אם צריך לחלק את ההטבה לשני חלקים: \u0003מאי שנא דעביד\u0004 \u0005[במה שונה,\u0006 מה טעם, \u0005שהוא עושה]\u0006 \u0003הטבת חמש נרות ברישא\u0004 \u0005[בתחילה]?\u0006 \u0003נעביד ברישא\u0004 \u0005[נעשה]\u0006 \u0003הטבת שתי נרות\u0004 \u0005[בתחילה]!\u0006 ומשיבים: \u0003כיון דאתחיל בהו עביד\u0004 \u0005[שכבר התחיל בהן\u0006 בעבודה זו \u0005עושה הוא]\u0006 את \u0003רובן.\u0004 ומקשים: אם כן \u0003ונעביד שית\u0004 \u0005[ונעשה שש\u0006 נרות\u0005]!\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בהיטיבו את הנרת יקטירנה\"\u0004 (שמות ל, ז) \u0003ואין נרות\u0004 האמורים בלשון רבים \u0003פחותות משתים,\u0004 ללמדנו כי בכל עת שעושים הטבה צריך לתקן לפחות שני נרות.","נאמר עוד בדברי אביי כי \u0003\"והטבת שתי נרות קודמת לקטורת\",\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בהיטיבו את הנרת\"\u0004 תחילה, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר \u0003\"יקטירנה\",\u0004 הרי שהטבה קודמת להקטרה.","שנינו עוד בדברי אביי כי \u0003\"וקטורת\u0004 קודמת \u0003לאברים\".\u0004 ודבר זה נלמד ממה \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בביאור ענין זה: \u0003יוקדם דבר\u0004 (הקטרת הקטורת) \u0003שנאמר בו \"בבקר בבקר\", לדבר\u0004 (קרבן התמיד) \u0003שלא נאמר בו אלא \"בקר\" אחד בלבד\u0004 (\"את הכבש האחד תעשה בבוקר\". שמות כט, לט).","עוד אמר אביי כי \u0003\"ואברים\u0004 קודמין להקרבת ה\u0003מנחה\u0004 של קרבן התמיד\u0003\".\u0004 ודבר זה נלמד ממה \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מניין שלא יהא דבר\u0004 מונח על עצי המערכה \u0003קודם לתמיד של שחר?\u0004"],["\u0003תלמוד לומר: \"\u0004וביער עליה הכהן עצים בבוקר בבוקר \u0003וערך עליה העלה\"\u0004 (ויקרא ו, ה). \u0003ואמר רבא:\u0004 מתוך שהיה הכתוב יכול לומר \"וערך עליה\" ומכך תבין כי כל דבר העתיד להקרב ביום זה יהא מונח עליה, ובכל זאת הוסיף לומר \u0003\"העלה\" —\u0004 ללמד כי \u0003היא —\u0004 ה\u0003עולה,\u0004 תהא \u0003ראשונה\u0004 להקרבה.","עוד נשנה בדברי אביי כי \u0003\"ומנחה\u0004 קודמת \u0003לחביתין\"\u0004 שהרי אמר הכתוב: \"...להקריב אשה לה' עולה ומנחה זבח ונסכים דבר יום ביומו\" (ויקרא כג, לז) וממה שנאמר \u0003עולה ומנחה\u0004 למדים כי העולה (קרבן התמיד) קודמת למנחה, וכיון שהמנחה היא חלק מקרבן העולה, הרי שהיא קודמת למנחת חביתין שהיא קרבן מנחה לעצמה.","נאמר עוד בדברי אביי כי \u0003\"וחביתין\u0004 קודמין \u0003לנסכים\".\u0004 וטעם הדבר בגלל \u0003שום\u0004 (שם) \u0003מנחה,\u0004 שהרי אף החביתין סוג של מנחה היא, ומתוך שכבר הובהר כי על המנחה של קרבן התמיד להיות סמוכה לו, כאמור \"עולה ומנחה\", לכך יש אף להקדים כל מנחה שהיא ולסומכה לקרבן התמיד.","עוד נאמר בדברי אביי, כי \u0003\"ונסכים\u0004 קודמים \u0003למוספין\".\u0004 וזאת משום שנאמר בכתוב: \u0003\"זבח ונסכים\"\u0004 — ללמד שעל הנסכים להיות סמוכים לזבח ולא יפסיק ביניהם קרבן אחר. עוד אמר אביי, כי \u0003\"ומוספין\u0004 קודמין \u0003לבזיכין\".\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 להיפך: \u0003בזיכין קודמין למוספין!\u0004 ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 שנחלקו ר' ישמעאל ור' עקיבא במסכת פסחים (נח, א) מי מהן קודם.","\u0003אמר אביי: מסתברא כמאן דאמר\u0004 \u0005[מסתבר כמי שאמר]\u0006 \u0003מוספין קודמין לבזיכין,\u0004 והטעם — \u0003לאו מי אמרת\u0004 \u0005[האם לא אמרת]\u0006 כי כפילות המילים \u0003\"בבקר בבקר\"\u0004 באה להדגיש כי יש \u0003להקדים\u0004 את הקרבת קרבן התמיד, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בבזיכים שנכפל הלשון: \u0003\"ביום\" \"ביום\"\u0004 (\"ביום השבת ביום השבת יערכנו\", ויקרא כד, ח), אף זה להדגיש ולומר כי יש \u0003לאחר\u0004 לעשות כן עד תוקפו ועיצומו של היום.","ושואלים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה טעמו של מי שאמר]\u0006 כי \u0003בזיכין קודמין למוספין?\u0004 ומסבירים: \u0003גמר\u0004 \u0005[למד]\u0006 גזירה שוה \u0003\"חקה\" \"חקה\" מחביתין,\u0004 שבבזיכים נאמרה חוקה (\"חק עולם\". ויקרא כד, ט) וכן בחביתין (\"חק עולם\". ויקרא ו, טו), וכשם חביתין קודמים למוספין, כך אף הבזיכים.","ומקשים: \u0003אי מהתם גמר\u0004 \u0005[אם משם למד],\u0006 אם כן \u0003ליגמרה כולה מילתא מהתם\u0004 \u0005[שילמד את כל הדבר משם]\u0006 ויקטירו את הבזיכין מיד לאחר החביתין, ומדוע מפסיקים ביניהם בנסכים? ומשיבים: \u0003להכי אהני\u0004 \u0005[לכך הועיל]\u0006 מה שנאמר בבזיכין \u0003\"ביום\" \"ביום\",\u0004 כדי \u0003לאחר\u0004 מעט את זמנם\u0005.\u0006","לאחר שסיימו לבאר את דברי אביי בסדר עבודות היום, שבים אנו לפירושה של המשנה. שנינו כי \u0003קטורת של שחר היתה קריבה בין\u0004 קבלה וזריקה של \u0003דם\u0004 התמיד לבין הקרבת ה\u0003איברים.\u0004 ושואלים: \u0003מני\u0004 \u0005[\u0006משנה זו \u0005כשיטת מי\u0006 היא\u0005]?\u0006 \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים]\u0006 היא, הרי לדעתם (לעיל יומא טו, א) קטורת \u0003בין דם לנרות מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 אם כשיטת \u0003אבא שאול\u0004 (שם) \u0003—\u0004 הרי \u0003בין נרות לאיברים מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006","ומשיבים: \u0003לעולם\u0004 יש לפרש כי משנתנו כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, ובסידרא לא קא מיירי\u0004 \u0005[ובסדר אינו עוסק],\u0006 שאיננו משנה זו דנה בסדר העבודה בשלימותו איזו עבודה קודמת לחבירתה, ואינה אלא מציינת שבין דם לאברים של קרבן התמיד היו מקטירים את הקטורת, אבל לאמיתו של דבר היו עושים עוד עבודות נוספות, כגון הטבת הנרות.","נאמר במשנה כי קטורת \u0003של בין הערבים היתה קריבה בין איברים לנסכים.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 נלמדים? \u0003אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ואת הכבש השני תעשה בין הערבים \u0003כמנחת הבקר וכנסכו תעשה\u0004 אשה ריח ניחוח לה'\" (במדבר כח, ח), ולמדנו מכך כי \u0003מה\u0004 סדרה של \u0003מנחת הבקר, שקטורת קודמת לנסכים — אף כאן\u0004 בערב \u0003קטורת קודמת לנסכים.\u0004","ומקשים: \u0003אי מה להלן\u0004 בבוקר \u0003קטורת קודמת\u0004 אף \u0003לאיברים, אף כאן\u0004 בערב תהא ה\u0003קטורת קודמת לאיברים!\u0004 ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 במקרא \u0003\"כאיברי הבקר\"?\u0004 הלא רק \u0003\"כמנחת הבקר\" כתיב\u0004 \u0005[נאמר],\u0006 ללמד ולהדגיש שצריכה להיות \u0003כמנחת הבקר — ולא\u0004 שתהיה \u0003כאיברי הבקר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר: \u0003\"ונסכו רביעת ההין\u0004 לכבש האחד בקודש הסך נסך שכר לה'\u0003\"\u0004 (במדבר כח, ז) — \u0003ילמד\u0004 אופן וסדר הקרבה \u0003של שחרית\u0004 מאופן וסדר הקרבה \u0003של ערבית.\u0004 שכשם שצריך נסכים לתמיד של בין הערבים, כך גם לתמיד של שחר."],["\u0003רבי אומר:\u0004 למדים דין קרבן תמיד של \u0003ערבית\u0004 (בין הערבים) \u0003משל שחרית;\u0004 ש\"את הכבש האחד\" שנאמר במקרא, הכוונה לכבש התמיד של שחר, וממנו למדים לתמיד האחר, של בין הערבים.","ושואלים: \u0003בשלמא לרבנן\u0004 \u0005[נניח לשיטת חכמים]\u0006 הסבורים \u0003האי\u0004 \u0005[זה]\u0006 שנאמר בפסוק זה, \u0003בתמיד של בין הערבים כתיב\u0004 \u0005[נאמר]\u0006 לפי המשך הכתובים, ולכך הוא המלמד על התמיד של שחר. \u0003אלא רבי\u0004 הסובר כי יש ללמוד של בין הערבים משל שחר, \u0003מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006 \u0003אמר רבה בר עולא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לכבש האחד\" — איזהו כבש שנאמר בו\u0004 תחילה \u0003\"אחד\" — הוי אומר זה תמיד של שחר.\u0004 הרי שהפסוק הזה מדבר מענין התמיד של שחר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה אומרים הם על כך? ומשיבים: כי לדעתם \u0003מאי\u0004 \u0005[מה]\u0006 כוונת הפסוק באומרו \u0003\"אחד\",\u0004 כוונתו — \u0003מיוחד שבעדרו,\u0004 שיש להביא לקרבן התמיד כבש מובחר ומיוחד. ושואלים: \u0003ורבי,\u0004 מהיכן הוא לומד דין זה? ומשיבים: לדעתו ממה שנאמר: \u0003\"\u0004וכל \u0003מבחר נדריכם\"\u0004 (דברים יב, יא) \u0003נפקא\u0004 \u0005[יוצא לו,\u0006 נלמד\u0005]\u0006 דין זה, שהנדר צריך להיות מבחר צאנו. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 כיצד מפרשים הם כתוב זה? ומסבירים: לדעתם פסוק \u0003חד\u0004 \u0005[אחד]\u0006 לענין קרבן \u0003חובה\u0004 נאמר, \u0003וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 לענין קרבן \u0003נדבה\u0004 נאמר. \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 הדברים להיאמר בשני המקרים. מפני שיש צד לומר כי על כל דבר שהוא חובה להיעשות בשלימות, ולכך על קרבן חובה להיות מן המובחר, ומצד שני יש לומר, כי כשאדם עושה דבר מתוך נדבת ליבו, הריהו עושה כן באופן היפה והמושלם ביותר, ולכך על קרבן נדבה להיות מן המובחר.","שנינו במשנה כי \u0003אם היה\u0004 ה\u0003כהן\u0004 ה\u0003גדול זקן או איסטניס\u0004 היו מחממים לו מים חמים ומטילין בתוך המקוה, כדי להפיג את הצינה. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' יהודה: עששיות\u0004 (גושים, חתיכות) \u0003של ברזל היו מחמין\u0004 (מחממים) \u0003מערב יום הכפורים ומטילין לתוך צונן\u0004 שבמקוה \u0003כדי שתפיג צינתן.\u0004 ומקשים: \u0003והלא\u0004 כשעושה דבר זה \u0003מצרף\u0004 הוא את הברזל, שהוא מחסם ומחזק אותו על ידי כך, ונמצא עושה מלאכה ביום הכיפורים! \u0003אמר רב ביבי:\u0004 כאן מדובר שלא חיממו את גושי הברזל כל כך, \u0003שלא הגיע לצירוף. אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003שהגיע\u0004 הברזל מבחינת החימום לכדי \u0003צירוף.\u0004 אולם פעולה זו היא בכלל \u0003דבר שאין מתכוין,\u0004 שהרי אין כוונתו לתקן ולחמם את הברזל, אלא רק לחמם את המים, ולכן \u0003מותר.\u0004","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך],\u0006 שדבר שאין מתכוין מותר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"\u0004וביום השמיני ימול \u0003בשר ערלתו\"\u0004 (ויקרא יב, ג), ללמד: \u0003אפילו במקום שיש שם בהרת\u0004 של צרעת על גבי הערלה \u0003יקוץ\u0004 (יקצוץ) אותו וימול את התינוק, למרות איסור התורה לקצוץ את בהרת הצרעת, אלו \u0003דברי ר' יאשיה. והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 בבעיה זו: \u0003קרא\u0004 \u0005[הכתוב]\u0006 \u0003למה לי\u0004 להתיר דבר זה, הלא אינו מתכוין לקצוץ את הנגע אלא למצוות מילה, ומשום מה איפוא יש צורך בפסוק מיוחד להתיר? \u0003ואמר אביי:\u0004 דבר זה נאמר לפי שיטת \u0003ר' יהודה,\u0004 ש\u0003אמר: דבר שאין מתכוין אסור.\u0004 ולכן צריך כתוב מיוחד להתירו. ולעניננו מצאנו שאביי סבור כי ר' יהודה אוסר אפילו דבר שאינו מתכוין, ומדוע אומר הוא לענין עששיות של ברזל שר' יהודה מתיר כשאינו מתכוון?","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר אביי שר' יהודה אוסר כשאינו מתכוון, הרי זה \u0003בכל התורה כולה\u0004 כאשר האיסור שבדבר הוא מן התורה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בעששיות הלא \u0003צירוף\u0004 זה אינו ממש מלאכה גמורה האסורה מן התורה אלא רק איסור \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003הוא,\u0004 שאין איסורו אלא משום שבות (תקנת חכמים להוסיף במצוה שביתה), ולא החמירו חכמים לאסור מלאכה זו שמדבריהם כשאינו מתכוין לה.","\u0003הביאוהו\u0004 את הכהן הגדול כדי לטבול בשנית ללישכת \u0003בית הפרוה, ובקדש היתה\u0004 לישכה זו. \u0003פרסו סדין של בוץ בינו לבין העם\u0004 לצניעות, \u0003וקדש\u0004 הכהן \u0003ידיו ורגליו ופשט\u0004 את בגדיו. \u0003ר' מאיר אומר:\u0004 כך היה הסדר, קודם \u0003פשט,\u0004 ואחר כך \u0003קדש ידיו ורגליו. ירד וטבל\u0004 שנית, \u0003עלה ונסתפג\u0004 ומיד \u0003הביאו לו בגדי לבן, לבש\u0004 אותם \u0003וקדש ידיו ורגליו.\u0004","\u0003בשחר היה לובש\u0004 בגדי שש \u0003פלוסין\u0004 (הבאים ממצרים) \u0003של שנים עשר מנה,\u0004 שבשל טיבם, היה מחירם יקר כל כך. ו\u0003בין הערבים\u0004 היה לובש בגדי שש \u0003הנדויין\u0004 (מהודו) זולים במקצת והיו רק \u0003של שמונה מאות זוז\u0004 (שמונה מנה), אלו \u0003דברי ר' מאיר. וחכמים אומרים\u0004 שהיו שניהם יקרים יותר: \u0003בשחר היה לובש\u0004 בגדים \u0003של שמונה עשר מנה ובין הערבים\u0004 היה לובש \u0003של שנים עשר מנה\u0004 ובסך \u0003הכל\u0004 עלות בגדיו \u0003— שלשים מנה.\u0004 סכומים \u0003אלו\u0004 לבגדים היו \u0003משל ציבור ואם רצה\u0004 הכהן הגדול \u0003להוסיף\u0004 ולקנות מובחרים יותר — \u0003מוסיף משלו\u0004 מרכושו הפרטי."],["\u0003מאי\u0004 \u0005[מהו\u0006 שם\u0005]\u0006 \u0003\"פרוה\"\u0004 שנקראת לשכה זו? \u0003אמר רב יוסף: פרוה\u0004 הוא שמו של \u0003אמגושא\u0004 \u0005[מכשף פרסי]\u0006 אחד שנקשר שמו ללשכה זו מפני מעשה שהיה.","שנינו במשנה כי \u0003\"פרסו\u0004 שם \u0003סדין של בוץ\".\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה, מדוע דווקא]\u0006 \u0003של בוץ? אמר רב כהנא: כדי שיכיר\u0004 הכהן הגדול ויזכור \u0003שעבודת היום בבגדי בוץ\u0004 היא.","שנינו במשנה כי לדעת חכמים \u0003בשחר היה לובש פלוסין של שמונה עשר\u0004 מנה, ובסך הכל שלושים מנה. על סיכום זה תוהים: וכי ה\u0003תנא מניינא אתא לאשמועינן\u0004 \u0005[\u0006את \u0005החשבון בא להודיענו],\u0006 ולומר לנו שהסכום הכולל של שמונה עשר ושנים עשר הוא שלושים? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דבציר מהני\u0004 \u0005[שפחות מאלה],\u0006 מהסכום הכולל לבגדי השחר ולבגדי בין הערבים, \u0003לא נעביד\u0004 \u0005[אין עושים],\u0006 ונדייק: \u0003הא אי בציר מהני\u0004 \u0005[אבל אם הפחית מאלה]\u0006 של שחרית \u0003וטפי אהני\u0004 \u0005[והוסיף על אלה]\u0006 של הערב \u0005—\u0006 \u0003לית לן בה\u0004 \u0005[אין לנו בכך\u0006 איסור\u0005],\u0006 ויכול לחלק את העלות הכוללת לביגוד באופן שונה, כפי רצונו.","ומעירים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 בין לר' מאיר בין לחכמים \u0003מיהת\u0004 \u0005[בכל אופן]\u0006 בגדים של \u0003שחר עדיפי\u0004 \u0005[עדיפים]\u0006 ועליהם להיות משובחים ויקרים מאלו של בין הערבים, ודבר זה \u0003מנא לן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר רב הונא בריה\u0004 \u0005[בנו של]\u0006 \u0003רב עילאי: אמר קרא\u0004 \u0005[הכתוב]\u0006 בבגדי הלבן שלובש הכהן הגדול בשחרית: \"כתונת בד קודש ילבש ומכנסי בד יהיו על בשרו ובאבנט בד יחגור ובמצנפת בד יצנוף\" (ויקרא טז, ד), חזר הכתוב על לשון \u0003\"בד\" \"בד\" \"בד\" \"בד\"\u0004 ארבע פעמים, ללמד כי ראוי לקחת לצורך זה \u0003מובחר\u0004 ש\u0003בבד.\u0004"],["\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 נאמר: \"והיה בבואם אל החצר הפנימית בגדי פשתים ילבשו ולא יעלה עליהם צמר בשרתם בשערי החצר הפנימית וביתה\" ופסוק זה מדבר בודאי בענין עבודת יום הכיפורים, שהרי בשאר ימות השנה היה הכהן הגדול עובד בשמונה בגדים שהיו עשויים בין השאר גם מצמר. ונאמר לאחר מכן: \u0003\"\u0004ובצאתם אל החצר החיצונה אל החצר החיצונה אל העם יפשטו את בגדיהם אשר המה משרתים בם והניחו אותם בלשכות הקודש \u0003ולבשו בגדים אחרים ולא יקדשו את העם בבגדיהם\",\u0004","ומדייקים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003\"אחרים\"\u0004 פירושו: \u0003חשובין מהם,\u0004 לומר שבגדי לבן השניים צריכים להיות חשובים מן הראשונים! ודוחים: \u0003לא, \"אחרים\"\u0004 פירושו אמנם בגדים שונים, אבל \u0003פחותים מהן,\u0004 שאין הכהן לובשם לצורך כפרה, אלא לצורך פינוי הכף והמחתה שאינם אלא לכבוד המקום.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב הונא בר יהודה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב שמואל בר יהודה: אחר שכלתה עבודת ציבור, כהן שעשתה לו אמו כתונת\u0004 של כהונה — \u0003לובשה, ועובד בה עבודת יחיד,\u0004 כגון הוצאת הכף והמחתה שאינן עבודה לעצמן \u0003ובלבד שימסרנה לציבור.\u0004 שהרי צריך ללבוש בגדי קודש, ובגדי הקודש חייבים להיות משל ציבור, כשאר כלי המקדש. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 כיון שמסרה לציבור הריהי מעתה כשאר נדבות היחיד הנמסרות למקדש, ומה החידוש בכך?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 נחשוש \u0003שמא לא ימסרנה יפה יפה\u0004 בכל לבו, שהרי סוף סוף הוא שילבש כתונת זו, ושמא יכוין שתישאר בכל זאת שלו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאם מסרה לציבור, אין לחשוש לכך. אגב הלכה זו מסופר: \u0003אמרו עליו על ר' ישמעאל בן פאבי\u0004 שהיה כהן גדול \u0003שעשתה לו אמו כתונת\u0004 שהיה שוויה \u0003מאה מנה, ולובשה ועובד בה עבודת יחיד, ומסרה לציבור.\u0004","וכן \u0003אמרו עליו\u0004 על הכהן הגדול \u0003ר' אלעזר בן חרסום שעשתה לו אמו כתונת משתי ריבוא\u0004 (עשרים אלף דינרים) \u0003ולא הניחוהו אחיו הכהנים ללובשה מפני\u0004 שהיתה שקופה והיה \u0003נראה\u0004 בה \u0003כערום.\u0004 ושואלים: \u0003ומי מתחזי\u0004 \u0005[והאם נראה]?\u0006 האפשר שכתונת העשויה כדין בגדי כהונה תהא שקופה כל כך? \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 שבגדי כהונה \u0003חוטן כפול ששה\u0004 וכיון שנארגו מחוטים עבים כל כך כיצד יתכן שיראה בשרו מתוכם? \u0003אמר אביי: כחמרא דמזגא\u0004 \u0005[כמו יין בתוך\u0006 כוס \u0005מזוגה],\u0006 שלא היו רואים ממש את בשרו, אלא כיון שהיה הפשתן מובחר ביותר היה בכל זאת שקוף מעט והיה נראה צבע בשרו מבפנים.","כיון שהוזכר ר' אלעזר בן חרסום ועושרו, מביאים מאמר הקשור בכך. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עני ועשיר ורשע באין לדין\u0004 בפני בית דין של מעלה על מעשיהם בעולם הזה, \u0003לעני אומרים לו: מפני מה לא עסקת בתורה? אם אומר\u0004 כהתנצלות: \u0003עני הייתי, וטרוד במזונותי\u0004 ולכך לא הספקתי ללמוד, \u0003אומרים לו: כלום עני היית יותר מהלל\u0004 שהיה עני מרוד ובכל זאת לא נמנע בשל כך מהשתדלות?","שכן \u0003אמרו עליו על הלל הזקן שבכל יום ויום היה עושה\u0004 מלאכה \u0003ומשתכר בטרפעיק\u0004 (חצי דינר), ומכיון שבאותם דורות לא הניחו להכנס לבית המדרש ללמוד, אלא למי שהיה משלם שכר, לכך \u0003חציו\u0004 של שכר עבודתו \u0003היה נותן לשומר בית המדרש, וחציו\u0004 האחר היה מוציא \u0003לפרנסתו ולפרנסת אנשי ביתו. פעם אחת לא מצא להשתכר, ולא הניחו שומר בית המדרש להכנס. עלה\u0004 על הגג \u0003ונתלה וישב על פי ארובה\u0004 (מעל לחלון) \u0003כדי שישמע דברי אלהים חיים מפי שמעיה ואבטליון\u0004 גדולי הדור באותם ימים.","\u0003אמרו: אותו היום ערב שבת היה, ותקופת טבת היתה, וירד עליו שלג מן השמים. כשעלה עמוד השחר אמר לו שמעיה לאבטליון: אבטליון אחי, בכל יום\u0004 בשעה זו \u0003הבית\u0004 כבר \u0003מאיר\u0004 מפני החמה הנכנסת בחלון \u0003והיום אפל, שמא יום המעונן הוא? הציצו עיניהן וראו דמות אדם בארובה\u0004 (בחלון). \u0003עלו ומצאו עליו רום\u0004 (גובה) \u0003שלש אמות\u0004 של \u0003שלג. פרקוהו\u0004 מן השלג, \u0003והרחיצוהו וסיכוהו\u0004 בשמן, \u0003והושיבוהו כנגד המדורה\u0004 לחממו. \u0003אמרו: ראוי זה לחלל עליו את השבת.\u0004 שבודאי פיקוח נפש דוחה שבת בכל מקרה, אבל אדם גדול כזה ראוי הוא לכך במיוחד. הרי למדנו שעניות אינה יכולה להוות סיבה להימנע מהשתדלות בתורה.","ואם בא לפני בית דין של מעלה אדם \u0003עשיר, אומרים לו: מפני מה לא עסקת בתורה? אם אומר: עשיר הייתי וטרוד הייתי בנכסי. אומרים לו: כלום עשיר היית יותר מר' אלעזר\u0004 שהיה עשיר גדול ובכל זאת עסק בתורה? שכן \u0003אמרו עליו על ר' אלעזר בן חרסום שהניח לו אביו\u0004 בירושה \u0003אלף עיירות\u0004 (כפרים) באחוזותיו \u0003ביבשה, וכנגדן אלף ספינות בים. ובכל יום ויום\u0004 היה \u0003נוטל נאד של קמח על כתיפו ומהלך מעיר לעיר וממדינה למדינה ללמוד תורה\u0004 מהחכמים המצויים באותם מקומות. וכל כך היה שקוע בלימודו עד שלא הכירוהו אפילו האנשים שעבדו עבורו.","\u0003פעם אחת מצאוהו עבדיו\u0004 שהוא עובר בתוך העיירות באחוזתו ולא הכירוהו, \u0003ועשו בו אנגריא\u0004 (עבודת כפיה), שחשבו שהוא תושב אחת העיירות האלה וחייב לעבוד עבור בעל האחוזה. \u0003אמר להן: בבקשה מכם, הניחוני ואלך ללמוד תורה. אמרו לו: חיי ר' אלעזר בן חרסום שאין\u0004 אנו \u0003מניחין אותך.\u0004 ומעירים: \u0003ומימיו לא הלך וראה אותן\u0004 את כל נכסיו ורכושו, \u0003אלא\u0004 היה \u0003יושב ועוסק בתורה כל היום וכל הלילה.\u0004","ואם היה בא \u0003רשע\u0004 לדין, \u0003אומרים לו: מפני מה לא עסקת בתורה? אם אמר: נאה הייתי, וטרוד ביצרי\u0004 שהיו לי פיתויים מרובים, \u0003אומרים לו: כלום נאה היית מיוסף\u0004 שעל אף יופיו, לא גררו הדבר להבטל מן התורה? שכן \u0003אמרו עליו על יוסף הצדיק: בכל יום ויום היתה אשת פוטיפר משדלתו\u0004 (מפתה אותו) \u0003בדברים. בגדים שלבשה לו\u0004 (בשבילו) \u0003שחרית לא לבשה לו ערבית\u0004 אלא החליפה בגדיה לעורר בו ענין. \u0003בגדים שלבשה לו ערבית\u0004 ביום זה \u0003לא לבשה לו\u0004 למחרתו \u0003לשחרית.\u0004","\u0003אמרה לו: השמע לי\u0004 לתשמיש! \u0003אמר לה: לאו\u0004 \u0005[לא].\u0006 \u0003אמרה לו: הריני חובשתך בבית האסורין! אמר לה:\u0004 איני מתיירא, שכן נאמר: \u0003\"ה' מתיר אסורים\"\u0004 (תהלים קמו, ז). אמרה לו: \u0003הריני כופפת קומתך\u0004 מיסורים! אמר לה: \u0003\"ה' זקף כפופים\"\u0004 (תהלים קמו, ח). אמרה לו: \u0003הריני מסמא את עיניך!\u0004 ענה לה: \u0003\"ה' פקח עורים\"\u0004 (תהלים קמו, ח). \u0003נתנה לו אלף ככרי כסף לשמע אליה \"לשכב אצלה להיות עמה\"\u0004 (בראשית לט, י) \u0003ולא רצה.\u0004","ומסבירים את לשון הכתובים המיוחדת: שאם ייעתר לה \u0003\"לשכב אצלה\" בעולם הזה,\u0004 הרי נגזר עליו \u0003\"להיות עמה\" לעולם הבא,\u0004 ומשום כך לא רצה. \u0003נמצא: הלל מחייב את העניים, ר' אלעזר בן חרסום מחייב את העשירים, יוסף מחייב את הרשעים.\u0004 שהרי יש דוגמה לכל אלה שיכול אדם לגבור על פיתוייו וטרדותיו וללמוד תורה.","\u0003בא לו\u0004 הכהן הגדול \u0003אצל פרו, ופרו היה עומד\u0004 בשטח \u0003בין האולם ולמזבח, ראשו\u0004 של הפר לצד \u0003דרום ופניו\u0004 פונים \u0003למערב. והכהן עומד\u0004 בצד \u0003מזרחי\u0004 לפר \u0003ופניו\u0004 פונים \u0003למערב. וסומך\u0004 הכהן \u0003שתי ידיו עליו, ומתודה.\u0004","\u0003וכך היה אומר\u0004 בוידויו: \u0003\"אנא השם! עויתי, פשעתי, חטאתי לפניך אני וביתי. אנא השם! כפר נא לעונות ולפשעים ולחטאים שעויתי ושפשעתי ושחטאתי לפניך אני וביתי, ככתוב בתורת משה עבדך: \"כי ביום הזה יכפר עליכם לטהר אתכם מכל חטאתיכם לפני ה' תטהרו\"\u0004 (ויקרא טז, ל) \u0003והן\u0004 הכהנים והעם שהיו בעזרה \u0003עונין אחריו\u0004 כשהוא מזכיר את השם: \u0003\"ברוך שם כבוד מלכותו לעולם ועד\".\u0004"],["נאמר במשנה, כי בשעת הוידוי היה הפר עומד בין האולם והמזבח, ומתוך מה ששנינו להלן (מא, ב) כי שחיטת הפר היתה נעשית במקום הוידוי, ודאי ששטח זה נחשב כצפון, ומבררים: \u0003מאן שמעת ליה דאמר\u0004 \u0005[ממי שמעת שהוא אומר]\u0006 שהשטח \u0003בין האולם ולמזבח צפון\u0004 הוא, וכשר לשחיטת קדשי קדשים שנאמר בהם: \"על ירך המזבח צפונה\" —","\u0003ר' אלעזר בר' שמעון היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו צפון — מקיר של מזבח\u0004 שבצד \u0003צפוני ועד כותל העזרה, וכנגד כל המזבח כולו צפון\u0004 אלו \u0003דברי ר' יוסי בר' יהודה.\u0004 ו\u0003ר' אלעזר בר' שמעון מוסיף\u0004 לומר כי \u0003אף\u0004 השטח בצד צפון שהוא \u0003בין האולם ולמזבח\u0004 נחשב כצפון. \u0003רבי מוסיף אף מקום דריסת רגלי הכהנים ואף מקום דריסת רגלי ישראל\u0004 בצידם הצפוני, שאף אלה קרויים צפון לענין קרבנות. \u0003אבל מן החליפות ולפנים,\u0004 כלומר: אותו חלק שעודף לצד זה, ששם היתה לישכה שבה היו מניחים את הסכינים, \u0003הכל מודים\u0004 שהוא \u0003פסול\u0004 לפי שאינו נראה מצד המזבח.","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי משנתנו כשיטת \u0003ר' אלעזר בר' שמעון היא ולא\u0004 כשיטת \u0003רבי?\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי משנתנו כשיטת \u0003רבי\u0004 היא, אלא, \u0003ורבי השתא\u0004 \u0005[\u0006הרי, \u0005עכשיו]\u0006 רק על דברי \u0003ר' יוסי בר' יהודה\u0004 הוא \u0003מוסיף,\u0004 ואילו על דברי \u0003ר' אלעזר בר' שמעון לא מוסיף?!\u0004 ודברי ר' אלעזר בר' שמעון בכלל דברי רבי.","והשואל מיישב את דברי שאלתו: \u0003אנן הכי קא אמרינן\u0004 \u0005[אנחנו כך אנו אומרים,\u0006 כך היתה כוונת השאלה\u0005]:\u0006 משנתנו \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003רבי היא,\u0004 שלדעתו כל העזרה צפון היא \u0003נוקמיה בכולה עזרה\u0004 \u0005[שנעמידנו בכל העזרה כולה]\u0006 ולאו דווקא בין האולם ולמזבח! ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 סבור אתה לומר כי משנתנו רק כשיטת \u0003ר' אלעזר בר' שמעון היא,\u0004 אולם אף לשיטתו אפשר לשאול: \u0003ונוקמיה\u0004 \u0005[ושיעמידנו]\u0006 את הפר \u0003בין מזבח ולכותל,\u0004 שהרי הכל מודים בשטח זה שהוא נחשב כצפון!","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 להסביר מפני מה מעמיד אותו במקום זה \u0003משום חולשא\u0004 של ה\u0003כהן גדול\u0004 שלא יצטרך לטרוח הרבה ולהתרוצץ ביום הכיפורים, אם כן לשיטת \u0003רבי נמי\u0004 \u0005[גם כן],\u0006 \u0003משום חולשא דכהן גדול\u0004 הוא עושה כן, אף כי היה מותר להעמיד את הפר גם בכל מקום אחר בעזרה.","שנינו במשנה כי \u0003ראשו\u0004 של הפר היה לצד \u0003דרום ופניו למערב.\u0004 ושואלים: \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]\u0006 שיהיה ראשו בצד אחד ופניו לצד אחר? \u0003אמר רב: בעוקם את ראשו\u0004 כלומר אמנם גופו עומד בין צפון לדרום, אולם פניו היו מופנים כלפי מערב. ושואלים: \u0003ונוקמיה להדיא\u0004 \u0005[שיעמידנו במישרין]\u0006 שיהיו אחוריו למזבח ופניו מערבה להיכל. \u0003אמר אביי: גזירה שמא ירביץ\u0004 (יטיל) \u0003גללים\u0004 בינתיים כנגד המזבח, ונמצא בזיון למזבח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כיצד סומך\u0004 הכהן על \u0003הזבח? עומד\u0004 היה הקרבן \u0003בצפון\u0004 העזרה (בקדשי קדשים), \u0003ופניו למערב, והסומך עומד\u0004 בצד \u0003מזרח\u0004 לקרבן \u0003ופניו\u0004 של הסומך היו מופנים \u0003למערב, ומניח שתי ידיו בין שתי קרנות\u0004 (קרניים) \u0003של\u0004ה\u0003זבח, ובלבד שלא יהא דבר חוצץ בינו לבין הזבח, ומתודה\u0004 על חטאיו. אם היה זה קרבן \u0003חטאת\u0004 הריהו מתוודה על \u0003עון\u0004 שמביאים עליו קרבן \u0003חטאת\u0004 (על שגגה במצוות לא תעשה) \u0003ועל\u0004 ה\u0003אשם\u0004 היה מתוודה על \u0003עון אשם\u0004 (כגון גזילות ומעילות) \u0003ועל עולה\u0004 (שלא נתפרש בתורה על איזה עוון היא באה) היה מתוודה על \u0003עון לקט שכחה ופאה ומעשר עני\u0004 שלא הפריש, אלו \u0003דברי ר' יוסי הגלילי.\u0004","\u0003ר' עקיבא אומר: אין עולה באה אלא על\u0004 ביטולה של מצות \u0003עשה, ועל לא תעשה שניתק לעשה\u0004 כלומר: כל אותן מצוות לא תעשה שמיד לאחריהן באה מצות עשה הבאה לתקנן (כגון: עוון גניבה, שמיד לאחר שאסרתו התורה בלא תעשה הובאה מצוות עשה של השבת הגניבה), שאין לוקין עליו ואין נענשין עליו בידי אדם, אבל כדי שתהיה לו כפרה משמים צריך להביא קרבן עולה.","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]\u0006 ומה הוא בסיס מחלוקתם? \u0003אמר ר' ירמיה:\u0004"],["\u0003בלאו\u0004 של איסור אכילת \u0003נבילה\u0004 והדומים לו \u0003קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 לפי שנאמר: \"לא תאכלו כל נבילה לגר אשר בשעריך תתננה ואכלה\" (דברים יד, כא), ונחלקו האם יש לראותו כלאו שניתק לעשה או כלאו רגיל, שיש עליו עונש מלקות.","\u0003ר' עקיבא סבר לאו מעליא הוא\u0004 \u0005[לאו מעולה,\u0006 גמור, \u0005הוא]\u0006 שהעובר עליו לוקה, כעובר על שאר לאוין, שלדעתו אי אפשר לומר שהוא בכלל לאו הניתק לעשה, שהרי במקרה זה אין העשה של \"לגר אש בשעריך תתננה ואכלה\" מהווה תיקון כלשהו לאיסור שעבר, שהרי מאחר וכבר אכלה שוב אינו יכול לתיתה לגר, אלא ודאי כוונת הפסוק לומר כי אסור לך לאכול נבילה ולכן תנה לגר. \u0003ור' יוסי הגלילי סבר: לאו לאו מעליא\u0004 \u0005[אינו לאו מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 אלא הוא מעין לאו הניתק לעשה, שכיון שנאמרה האמירה החיובית בסוף המאמר (\"תתננה ואכלה\") הרי זה כמצוות לא תעשה שיש לה תיקון.","ואילו \u0003אביי אמר: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003לאו\u0004 של איסור \u0003נבילה לאו מעליא הוי\u0004 \u0005[מעולה,\u0006 גמור \u0005הוא]\u0006 ואינו נחשב כלאו הניתק לעשה \u0003והכא\u0004 \u0005[וכאן]\u0006 נחלקו בדין לקט שכחה ופאה, שלאחר שנאמר: \"ובקוצרכם את קציר ארצכם לא תכלה פאת שדך לקצור ולקט קצירך לא תלקט. וכרמך לא תעולל ופרט כרמך לא תלקט\" נאמרה מצות עשה: \"לעני ולגר תעזוב אותם אני ה' אלהיכם\" (ויקרא יט, ט-י), ובמצוות \u0003\"תעזב\"\u0004 האמורה שם \u0003קא מיפלגי\u0004 \u0005[חלוקים];\u0006","ש\u0003ר' עקיבא סבר: \"תעזב\" מעיקרא משמע\u0004 \u0005[מתחלה משמע],\u0006 שמלכתחילה יש מצות עשה לעזוב לקט שכחה ופאה, ואם לא עזב ולקטם — עבר על מצוות לא תעשה גמורה, ולוקה עליה. ואילו \u0003ר' יוסי הגלילי סבר: השתא משמע\u0004 \u0005[עכשיו משמעו],\u0006 שגם אם עבר וליקט, חל עליו החיוב לתקן את שעשה בכך שיעזוב לעניים את שליקט, ואם כן אין זה איסור לאו גמור, אלא בכלל \"לאו הניתק לעשה\", שהרי יש לו תיקון במעשה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003כיצד מתודה\u0004 מהו סדר המילים בוידוי — \u0003\"עויתי פשעתי וחטאתי\" וכן בשעיר המשתלח הוא אומר\u0004 בכתוב לפי הסדר זה: עוונות, פשעים, חטאים, שכן נאמר: \u0003\"והתודה עליו את כל עונת בני ישראל ואת כל פשעיהם לכל חטאתם\"\u0004 (ויקרא טז, כא). \u0003וכן\u0004 בהתגלות ה' ל\u0003משה הוא אומר: \"נשא עון ופשע וחטאה\"\u0004 (שמות לד, ז), אלו \u0003דברי ר' מאיר. וחכמים אומרים\u0004 שתוכן הדברים הוא כי \u0003עונות אלו הזדונות\u0004 (עבירות שעושים בזדון) \u0003וכן הוא אומר\u0004 בכתוב: \u0003\"הכרת תכרת הנפש ההוא עונה בה\"\u0004 (במדבר טו, לא) הרי שמדובר על עבירות שעושה אדם במזיד.","\u0003פשעים אלו המרדים,\u0004 שלא די שחטא במזיד, אלא שעושה זאת כיון שמורד בקדוש ברוך הוא, \u0003וכן הוא אומר\u0004 במקרא: \u0003\"מלך מואב פשע בי\"\u0004 (מלכים ב' ג, ז), כלומר: מרד בי. \u0003ואומר: \"אז תפשע לבנה בעת ההיא\"\u0004 (מלכים ב' ח, כב), ואילו \u0003\"לכל חטאתם\" — אלו השגגות, וכן הוא אומר: \"נפש כי תחטא בשגגה\"\u0004 (ויקרא ד, ב). ואם כן לפי משמעות הדברים לא יתכן הסדר שהציע ר' מאיר, כי \u0003מאחר שהתודה על הזדונות ועל המרדים חוזר ומתודה על השגגות?!\u0004","\u0003אלא כך היה מתודה: חטאתי ועויתי ופשעתי לפניך אני וביתי. וכן בדוד הוא אומר\u0004 לפי סדר זה: \u0003\"חטאנו עם אבתינו העוינו הרשענו\"\u0004 (תהלים קו, ו), \u0003וכן בשלמה הוא אומר: \"חטאנו והעוינו רשענו\"\u0004 (מלכים א' ח, מז), \u0003וכן בדניאל הוא אומר: \"חטאנו ועוינו הרשענו ומרדנו\"\u0004 (דניאל ט, ה). אולם לפי זה \u0003מהו\u0004 הסדר בלשון הדברים \u0003שאמר משה \"נשא עון ופשע וחטאה\"?\u0004 שהרי בדבריו לשון \"חטאה\" הוא האחרון! — כך יש להבין: \u0003אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, בשעה שישראל חוטאין לפניך ועושין תשובה — עשה להם זדונות כשגגות\u0004 ולכן יהא נושא (מוחל) על עון ופשע כאילו היתה זו חטאה, כלומר שגגה.","\u0003אמר רבה בר שמואל אמר רב: הלכה כדברי חכמים,\u0004 שסדר הדברים הוא \"חטאתי עויתי פשעתי\". ותוהים על פסק הלכה זה: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא כלל ידוע הוא: \u0003יחיד ורבים הלכה כרבים!\u0004 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 במקרה זה, כיון ש\u0003מסתבר טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' מאיר דקמסייע ליה קרא\u0004 \u0005[שמסייע לו הכתוב]\u0006 של \u0003משה\u0004 שבו מפורש סדר הדברים כדבריו ולכך תהא הלכה כמותו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת הלכה כחכמים.","מסופר: \u0003ההוא דנחית קמיה\u0004 \u0005[\u0006אדם \u0005אחד ירד\u0006 לפני התיבה \u0005לפני]\u0006 \u0003רבה ועבד\u0004 \u0005[ועשה]\u0006 כסדר הוידוי של \u0003ר' מאיר, אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003שבקת רבנן\u0004 \u0005[עזבת את\u0006 שיטת \u0005חכמים]\u0006 שהם רבים \u0003ועבדת\u0004 \u0005[ועשית]\u0006 כשיטת \u0003ר' מאיר?! אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: אני כשיטת \u0003ר' מאיר סבירא לי\u0004 \u0005[סבור אני],\u0006 \u0003כדכתיב\u0004 \u0005[כפי שנאמר]\u0006 מפורש \u0003בספר אורייתא דמשה\u0004 \u0005[תורת משה].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במדרש ההלכה: נאמר: \"והקריב אהרן את פר החטאת אשר לו \u0003וכפר\u0004 בעדו ובעד ביתו\" (ויקרא טז, ו), ויש לומר כי \u0003בכפרת דברים\u0004 שבוידוי \u0003הכתוב מדבר. אתה אומר בכפרת דברים, או אינו אלא כפרת דמים\u0004 שכל כפרה האמורה בקרבן היא בהזאת הדם על המזבח.","\u0003הרי אני דן\u0004 בגזירה שוה: \u0003נאמרה כאן\u0004 בפר החטאת לשון \u0003\"כפרה\" ונאמרה להלן\u0004 בשעיר המשתלח לשון \u0003\"כפרה\"\u0004 (\"והשעיר אשר עלה עליו הגורל לעזאזל יעמד חי לפני ה' לכפר עליו\". ויקרא טז, י) \u0003מה \"כפרה\" האמורה בשעיר\u0004 כפרת \u0003דברים\u0004 שהרי אינו נשחט, ואין דמו נזרק על המזבח, \u0003אף \"כפרה\" האמורה בפר — דברים.\u0004","\u0003ואם נפשך\u0004 (רצונך) \u0003לומר\u0004 ולטעון דבר כנגד הוכחה זו, הרי לך הוכחה נוספת: \u0003הרי הוא אומר: \"והקריב אהרן את פר החטאת אשר לו וכפר בעדו ובעד ביתו\u0004 ושחט את פר החטאת אשר לו\u0003\"\u0004 (ויקרא טז, יא), הרי שנאמרה לשון כפרה אף ש\u0003עדיין לא נשחט הפר\u0004 והרי זו הוכחה שכפרה זו כפרת דברים בוידוי היא, ולא בזריקת הדם.","ומבררים במדרש זה: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש האמור בו \u0003\"ואם נפשך לומר\",\u0004 שמובן ממנו שיש מקום לערער את תוקפו של הטעם הראשון, ומה היא הקושיה שרמז לה? — הוא הדבר: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שבמקום ללמוד משעיר המשתלח \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003משעיר הנעשה בפנים,\u0004 נלמד מהשעיר שמביאים דמו לפני ולפנים \u0003שכפרתו בדמים,\u0004 אם כן \u0003הרי הוא אומר\u0004 כנגד זה \u0003\"וכפר\" — ועדיין לא נשחט הפר.\u0004"],["\u0003ומנין\u0004 שוידוי זה צריך להתחיל במילת \u0003\"אנא\u0004 השם \u0003\"? — נאמר כאן\u0004 לשון \u0003\"כפרה\", ונאמר להלן\u0004 בבקשת משה על חטא העגל \u0003בחורב:\u0004 \"אולי אכפרה בעד חטאתכם\", שאף הוא לשון \u0003\"כפרה\"\u0004 (שמות לב, ל), \u0003מה להלן\u0004 בלשון \u0003\"אנא\u0004 השם\u0003\"\u0004 (\"אנא חטא העם הזה חטאה גדולה\". שמות לב, לא) \u0003אף כאן —\u0004 בלשון \u0003\"אנא\u0004 השם\u0003\", ומנין\u0004 שבוידוי של יום הכיפורים מזכירים את השם? \u0003נאמר כאן\u0004 לשון \u0003\"כפרה\", ונאמרה בעגלה ערופה\u0004 לשון \u0003\"כפרה\"\u0004 (\"כפר לעמך ישראל אשר פדית ה' ואל תתן דם נקי בקרב עמך ישראל וניכפר להם הדם\". דברים כא, ח) \u0003מה להלן\u0004 בעגלה ערופה יש הזכרת ה\u0003שם, אף כאן בשם.\u0004","\u0003אמר אביי: בשלמא\u0004 \u0005[נניח]\u0006 \u0003חורב מעגלה ערופה לא יליף\u0004 \u0005[אינו לומד]\u0006 לומר שגם בחורב היה וידוי בשם — כי \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ומעשה שהיה בימי משה — כך היה. \u0003אלא, עגלה ערופה\u0004 שהיא מצוה לדורות \u0003תיליף\u0004 \u0005[תלמד]\u0006 \u0003מחורב\u0004 וכשם שבחורב אומר לשון \"אנא\" אף בעגלה ערופה יאמרו לשון \"אנא\"? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר: כן הוא גם כן]\u0006 ובאמת כך יש לומר, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכהנים אומרים: \"כפר לעמך ישראל\"\u0004 (דברים כא, ח) \u0003ואילו\u0004 בלשון \u0003\"אנא\" לא קא אמר\u0004 \u0005[אינו אומר],\u0006 משמע שאין למדים מחורב, ואין מוסיפים על מה שנאמר במקומו. ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע אין עושים כן.","שנינו במשנה כי בשעה שהיה הכהן הגדול מתוודה והיה מזכיר את השם היו \u0003הן\u0004 הכהנים והעם שהיו בעזרה \u0003עונין אחריו\u0004 ואומרים: \"ברוך שם כבוד מלכותו לעולם ועד\". \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר: \"כי שם ה' אקרא הבו גדל לאלהינו\"\u0004 (דברים לב, ג), פירושו: ש\u0003אמר להם משה לישראל: בשעה שאני מזכיר שמו של הקדוש ברוך הוא\u0004 (\"שם ה' אקרא\") \u0003אתם הבו גדל\u0004 ואימרו לכבודו דברי שבח. \u0003חנניה בן אחי ר' יהושע אומר\u0004 ראיה לדבר מכתוב אחר: נאמר: \u0003\"זכר צדיק לברכה\"\u0004 (משלי י, ז), \u0003אמר להם נביא\u0004 (שלמה) \u0003לישראל: בשעה שאני מזכיר צדיק עולמים\u0004 (הקדוש ברוך הוא) \u0003אתם תנו ברכה.\u0004","\u0003בא לו\u0004 הכהן \u0003למזרח העזרה\u0004 הרחוק יותר מקודש הקדשים ובצד \u0003צפון\u0004 של \u0003המזבח, הסגן\u0004 עומד \u0003מימינו וראש בית אב\u0004 שהיה תורו לשמש בשבוע זה עומד \u0003משמאלו. ושם\u0004 מעמידים \u0003שני שעירים, וקלפי\u0004 (תיבה של גורל) \u0003היתה שם, ובה שני גורלות, של\u0004 עץ \u0003אשכרוע\u0004 (ברוש) \u0003היו\u0004 מתחילה, \u0003ועשאן\u0004 הכהן הגדול יהושע \u0003בן גמלא של זהב, והיו מזכירים אותו לשבח\u0004 על מה שעשה.","וכיון שהוזכרו לשבח אלה שעשו מעשים בתיקון המקדש מספרים כי הכהן הגדול \u0003בן קטין עשה שנים עשר דד\u0004 (ברזים) \u0003לכיור,\u0004 כדי שיוכלו יותר כהנים לעסוק בקידוש ידים ורגלים בבת אחת, \u0003שלא היה לו\u0004 לכיור לפני כן \u0003אלא שנים. ואף הוא עשה מוכני\u0004 (מכשיר) \u0003לכיור,\u0004 שאפשר יהא באמצעותו להכניסו לתוך מים נובעים בשעות הלילה, כדי \u0003שלא יהיו מימיו\u0004 של הכיור \u0003נפסלין בלינה\u0004 ויצטרכו בכל בוקר לשפוך אותם ולמלא מים חדשים, וכיון שהוא שקוע בתוך מים נובעים, דינו כמותם ואין מימיו נפסלים בלינה.","ומעשה נוסף של תיקון: \u0003מונבז המלך היה עושה\u0004 (כלומר, תורם את הכסף שיעשו) \u0003כל ידות הכלים של יום הכפורים של זהב, הילני\u0004 המלכה \u0003אמו עשתה נברשת\u0004 (מנורה תלויה רבת-קנים) \u0003של זהב על פתח היכל\u0004 לנוי, \u0003ואף היא עשתה טבלא של זהב שפרשת סוטה כתובה עליה\u0004 שיוכלו להעתיק ממנה בשעת הצורך ולא יצטרכו להביא לשם כך ספר תורה. \u0003נקנור נעשו נסים לדלתותיו\u0004 הן דלתות המקדש בשער הקרוי על שמו \"שער ניקנור\", \u0003והיו מזכירין אותן\u0004 את כל אלה שמנינו \u0003לשבח\u0004 על מעשיהם.","\u0003מדקאמר\u0004 \u0005[ממה שנאמר]\u0006 במשנה שהיה הכהן בא \u0003לצפון המזבח, מכלל\u0004 הדברים אתה למד כי \u0003מזבח\u0004 עצמו \u0003לאו בצפון קאי\u0004 \u0005[\u0006היה \u0005עומד]\u0006 אלא בצד דרום של העזרה. ושואלים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 היא דעה זו? ומשיבים: כשיטת \u0003ר' אליעזר בן יעקב היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"\u0004ושחט אותו על ירך המזבח \u0003צפנה לפני ה'\"\u0004 (ויקרא א, יא), לומר \u0003שיהא צפון כולו פנוי,\u0004 והמזבח עצמו בצד דרום, וצד צפון יהיה פנוי, אלו \u0003דברי ר' אליעזר בן יעקב\u0004","ושואלים: \u0003והא רישא\u0004 \u0005[והרי תחילתה\u0006 של המשנה\u0005]\u0006 שהיא לסדר שלנו המשנה הקודמת, כפי שכבר הוסבר שיטת \u0003ר' אלעזר בר' שמעון היא\u0004 שלשיטתו היה מקצת המזבח בצפון! ודוחים: \u0003כולה,\u0004 כל משנתנו ואף חלקה הראשון שיטת \u0003ר' אליעזר בן יעקב היא, ותני\u0004 \u0005[ושנה]\u0006 והבן בגרסת המשנה הראשונה כי מדובר \u0003בבין האולם ולמזבח\u0004 ולא באותו מקום ממש אלא סמוך לו, בצד המזבח ממש, במקום שהוא לדעת הכל צפון.","נאמר במשנה כי \u0003הסגן בימינו\u0004 של כהן גדול, \u0003וראש בית אב משמאלו.\u0004 ומביאים מה ש\u0003אמר רב יהודה\u0004 בהלכות דרך ארץ: \u0003המהלך לימין רבו הרי זה בור\u0004 כלומר, אינו בקי אפילו ביסודות מנהגי הנימוס. ותוהים: הלא \u0003תנן\u0004 \u0005[שנינו]\u0006 כאן כי \u0003הסגן\u0004 (שהוא לגבי הכהן הגדול כתלמיד) \u0003בימינו\u0004 של כהן גדול, \u0003וראש בית אב בשמאלו!\u0004","\u0003ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שלשה שהיו מהלכין בדרך —\u0004 אלא ילכו בשורה אחד אחרי חבירו אלא ילכו בשורה אחת כש\u0003הרב\u0004 מהלך \u0003באמצע, גדול\u0004 התלמידים מהלך \u0003בימינו, וקטן\u0004 שבהם \u0003משמאלו. וכן מצינו בשלשה מלאכי השרת שבאו אצל אברהם\u0004 אבינו, \u0003מיכאל\u0004 הגדול שבהם היה \u0003באמצע, גבריאל בימינו ורפאל בשמאלו.\u0004 משמע שבכל זאת הולך התלמיד לימין רבו!","\u0003תרגומא\u0004 \u0005[תרגם,\u0006 הסביר אותה\u0005]\u0006 \u0003רב שמואל בר פפא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אדא: כדי שיתכסה בו רבו\u0004 כלומר שאיננו הולך ממש לימינו כחבר אלא מאחוריו לצד ימינו. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המהלך כנגד רבו\u0004 באותה שורה — \u0003הרי זה בור,\u0004 המהלך \u0003אחורי רבו\u0004 שמניח את רבו ללכת לפניו — \u0003הרי זה מגסי הרוח!\u0004 ומשיבים: \u0003דמצדד אצדודי\u0004 \u0005[שמצדד\u0006 במקצת\u0005]\u0006 שאינו הולך ממש בצידו באותה שורה אלא מעט אחריו, אבל אינו מצוי במרחק רב מאחריו.","במשנה שנינו כי \u0003קלפי היתה שם\u0004 במזרח העזרה \u0003ובה שני גורלות. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר: \u0003\"ונתן אהרן על שני השעירם גרלות\u0004 גורל אחד לה' וגורל אחד לעזאזל\u0003\"\u0004 (ויקרא טז, ח), גורלות משמע — \u0003גורלות של כל דבר\u0004 ולא הקפידה התורה מאיזה חומר הם עשויים.","\u0003יכול יתן שנים\u0004 (שני גורלות) \u0003על\u0004 שעיר \u0003זה, ושנים על זה — תלמוד לומר: \"גורל אחד לה' וגורל אחד לעזאזל\"\u0004 (ויקרא טז, ח) — \u0003אין כאן לשם אלא גורל אחד, ואין כאן לעזאזל אלא אחד. יכול יתן של שם ושל עזאזל על\u0004 שעיר \u0003זה ושל שם ושל עזאזל על זה — תלמוד לומר: \"גורל אחד לה'\" — אין כאן לה' אלא אחד, ואין כאן לעזאזל אלא אחד. אם כן מה תלמוד לומר \"גורלות\"\u0004 שהרי אין נותנים על שני השעירים שני גורלות לכל אחד אלא גורל אחד בלבד — \u0003שיהיו\u0004 הגורלות \u0003שוין\u0004 זה לזה, \u0003שלא יעשה אחד של זהב ואחד של כסף, אחד גדול ואחד קטן.\u0004","שנינו בברייתא זו כי גורלות היו \u0003גורלות של כל דבר\u0004 שממנו ניתן לעשותן. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי לא נאמר בתורה מאיזה חומר יש לעשותם! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 אלא \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לפי שמצינו בציץ\u0004 של כהן גדול \u0003שהשם כתוב עליו והוא של זהב, יכול אף זה\u0004 הגורל \u0003כן,\u0004 שכיון שכתוב השם עליו יעשוהו של זהב — \u0003תלמוד לומר\u0004 פעמיים: \u0003\"גורל\" \"גורל\" ריבה,\u0004 שאין צריך להיות מזהב דווקא ו\u0003ריבה\u0004 גורל העשוי מעץ \u0003זית,\u0004 ו\u0003ריבה של\u0004 עץ \u0003אגוז,\u0004 וכן \u0003ריבה של\u0004 עץ \u0003אשכרוע\u0004 (ברוש).","שנינו במשנה כי הכהן הגדול \u0003בן קטין עשה שנים עשר דד\u0004 (ברזים) \u0003לכיור. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כדי שיהיו שנים עשר אחיו הכהנים העסוקין בתמיד\u0004 (כפי שמבואר בפרקים קודמים) \u0003מקדשין\u0004 (רוחצין) \u0003ידיהן ורגליהן בבת אחת. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003שחרית\u0004 שהיה הכיור \u0003במילואו — מקדש ידיו ורגליו מן\u0004 הברזים הקבועים בצד \u0003העליון\u0004 של הכיור, שהמים מגיעים עד שם, ו\u0003ערבית\u0004 שהיה הכיור \u0003בירידתו,\u0004 שאינו מלא כל כך — \u0003מקדש ידיו ורגליו מן\u0004 הברזים הקבועים בצד \u0003התחתון.\u0004","שנינו במשנה על בן קטין: \u0003ואף הוא עשה מוכני לכיור.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003מוכני\u0004 זה? \u0003אמר אביי: גילגלא דהוה משקעא ליה\u0004 \u0005[גלגל,\u0006 מנוף, \u0005שהיה משקע אותו\u0006 בבור\u0005].\u0006","ח שנינו במשנה כי \u0003מונבז המלך עשה כל ידות הכלים\u0004 של יום כיפור זהב. ושואלים: אם רצה לתרום וליפות את המקדש, \u0003נעבדינהו לדידהו\u0004 \u0005[שיעשה אותם\u0006 את הכלים עצמם\u0005]\u0006 של \u0003זהב\u0004 ולא רק את ידותיהם!"],["\u0003אמר אביי:\u0004 מדובר כאן \u0003בידות סכינין\u0004 שלהבי הסכינים אינם ניתנים להיעשות זהב, שהזהב רך מכדי לשחוט בו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא אחרת שנאמר בה: \u0003אף הוא\u0004 מונבז \u0003עשה כני כלים, ואוגני כלים, וידות כלים וידות סכינין של יום הכפורים של זהב.\u0004 משמע שידות כלים לחוד וידות סכינים לחוד! ומשיבים: \u0003תרגומא\u0004 \u0005[הסבירה]\u0006 \u0003אביי:\u0004 הכוונה ל\u0003בקתתא דנרגי וחציני\u0004 \u0005[בקתות,\u0006 ידות \u0005הגרזנים והקרדומות],\u0006 שאף הן צריכות להיעשות ממתכת קשה ולא מזהב, על כן עשה רק את ידותיהן זהב.","שנינו במשנה כי \u0003הילני אמו\u0004 של מונבז \u0003עשתה נברשת\u0004 (מנורה תלויה רבת-קנים) \u0003של זהב\u0004 על פתח ההיכל לנוי\u0003. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003בשעה שהחמה זורחת ניצוצות יוצאין ממנה,\u0004 מן המנורה, שהיתה מבריקה ביותר \u0003והכל יודעין שהגיע זמן קריאת שמע\u0004 שזמנה עם הנץ החמה.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003הקורא את שמע שחרית עם אנשי משמר\u0004 אנשי משמר של כהנים המשרתים במקדש באותו שבוע, או עם \u0003אנשי מעמד\u0004 שהיו באים בקבוצות קבועות בעם, ונלוים למשמר להיות בירושלים באותו שבוע — \u0003לא יצא\u0004 ידי חובתו, \u0003מפני שאנשי משמר משכימין\u0004 יותר מן הזמן הראוי כדי שיהא להם פנאי לעבודת הקודש \u0003ואנשי מעמד\u0004 שיש להם להתפלל תפילות ארוכות מיוחדות ולעמוד על הקרבן בשעת הקרבתו \u0003מאחרים\u0004 מן הזמן הראוי, ואם כן למי במקדש הועיל נצנוץ החמה בנברשת כסימן לזמן קריאת שמע! \u0003אמר אביי:\u0004 סימן היה \u0003לשאר עמא\u0004 \u0005[לשאר העם]\u0006 ש\u0003בירושלים\u0004 שהם היו קורין בזמנה, ומכיון שראו את אור הנברשת מנצנץ משער המקדש, היו יודעים שהגיע הזמן.","שנינו במשנה כי \u0003אף היא\u0004, הילני המלכה, \u0003עשתה טבלא\u0004 שכתובה בה פרשת סוטה. ומעירים: \u0003שמעת מינה\u0004 \u0005[שומע אתה\u0006 מכאן\u0005]\u0006 כי \u0003כותבין מגילה\u0004 שכתובות בה רק פרשיות אחדות מן התורה \u0003לתינוק\u0004 כדי \u0003להתלמד בה.\u0004 שנחלקו חכמים אם מותר לכתוב חלקים מן התורה בפני עצמם, אפילו לצורך זה. \u0003אמר ריש לקיש משום ר' ינאי:\u0004 מכאן אין להוכיח לענין זה, כי הטבלא שעשתה הילני היתה \u0003באלף בית\u0004 שנכתבו בה רק האותיות הראשונות של כל מילה, לסייע לזכרון.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בדיני סוטה: \u0003כשהוא\u0004 הסופר \u0003כותב\u0004 את מגילת הסוטה \u0003רואה וכותב מה שכתוב בטבלא,\u0004 משמע שבטבלא כתובים הדברים במלואם! ודוחים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003רואה וכותב כמה שכתוב בטבלא,\u0004 כלומר: הכתוב בטבלא משמש רק כתזכורת כיצד צריך לכתוב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא אחרת שנאמר בה: \u0003כשהוא כותב — רואה וכותב מה שכתוב בטבלא, ומה כתוב בטבלא — \"אם שכב איש אותך\" \"ואם לא שכב\",\u0004 (במדבר ה, יט) \u0003\"אם שטית\" \"\u0004ו\u0003אם לא שטית\"\u0004 (במדבר ה, יט) משמע שבטבלא נכתבה לשון הפרשה כולה! ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר"]]};
